var _DAILY_DB={
  "8,0":{"third":10,"text":"اليوم مناسب لإحداث تغيير، سواء في الم dwelling أو في المزاج، سيجلب بداية جديدة. تتلاشى الأشياء القديمة، وتجد الخلافات مخارجها، الطريق أمامك مختلف عما كان عليه من قبل، لكنه مليء بإمكانات جديدة. جدير بأن يُتوقع."},
  "8,10":{"third":0,"text":"هناك أخبار سارة في التجارة والعمل، عودة الأشخاص قريبة، والأفراح تلوح في الأفق. لكن اليوم لا يَجوز السفر بعيداً، الأمور الحالية كافية لأن تكون مشغولاً، وبانتباعك الثبات في مكانك ستجد الحصاد."},
  "8,1":{"third":8,"text":"اليوم من الأفضل الالتقاء مع الآخرين، فالأشياء الطيبة تتشكّل بقوة الجمع. يمكن حل الخلافات وتزداد العلاقات ودا، وهو مناسب لدفع أمور الزفاف أو الاجتماعات أو التعاون. ما تتوقعه يقترب."},
  "8,8":{"third":1,"text":"اليوم مناسب للتحرك، حتى لو كانت الطريق طويلة فلا داعي للعجلة، ستصل الأمور في النهاية إلى المكان الذي تريده. ومع ذلك، فيما يخص العاطفة والأمور التجارية، لا بأس بإعطاء بعض الوقت لبعضكما البعض."},
  "8,4":{"third":11,"text":"تدفق الثروة اليوم يبدو أبطأ قليلاً، لكن الجد والاجتهاد سيفتحان لك الطريق. ما تطلبه قابل للتحقق، بشرط أن تكون مستعداً لبذل الجهد المقابل."},
  "8,11":{"third":4,"text":"أخبار سارّة في الطريق، ولا سيما من كبار السن أو من بعيد. فرح اليوم مُثمر ومناسب لتوقعات زواج وعائلة في المستقبل."},
  "8,2":{"third":9,"text":"قد تكون هناك تطوّرات جديدة في الثروة أو الإرث، كما أن لقاء الأصدقاء القدامى مُنتظر. لكن السفر يتطلب الحذر؛ قد تظهر نفقات غير مخطَّطة، فلتكن في حدود طاقتك."},
  "8,9":{"third":2,"text":"اليوم مناسب للإنهاء، حالة المريض تتحسن، ومن المحتمل استرجاع المفقود. الربح في الأعمال ضعيف، لكن المعاملات سلسة، الأيام تسير في اتجاه أفضل."},
  "8,13":{"third":14,"text":"في المناسبات الاجتماعية يحدث أمر جيد، ويتحسن المكانة والعلاقات. السعادة في متناول اليد، وعودة الأصدقاء تجعل اليوم أكثر دفئًا."},
  "8,14":{"third":13,"text":"سفَرٌ أو انتقال مفيد ماليًا، والعمليات التجارية تسير بسلاسة. لكن انتبه لصحة من حولك، فبعض المخاطر موجودة بهدوء، ولا يجب التهاون."},
  "8,6":{"third":7,"text":"قد تشعر اليوم بمزاج منخفض بسهولة، وخاصة عند المسائل المتعلقة بالأطفال أو الأسرة حيث قد تشعر بالقلق. من الناحية المالية يُنصح بتأجيل النفقات الكبيرة لفترة ومنح الأمور بعض الوقت."},
  "8,7":{"third":6,"text":"تقدّم الأمور يسير ببطء، وقد تواجه خلافات أو جدال. بعض الأشخاص قد لا يكونون متاحين مؤقتًا—لا حاجة للإلحاح في الاستفسار؛ الانتظار بهدوء قد يكون أفضل."},
  "8,5":{"third":15,"text":"حظ اليوم مشرِق، وشؤون الشراكة تسير بسلاسة، وما تُرجى منه يُحتمل أن يتحقق. في جانب الزواج أو العلاقات العاطفية هناك أيضًا تحركات إيجابية، وكل شيء مسترخٍ وميسَّر."},
  "8,15":{"third":5,"text":"هذا مزيجٌ موفَّق للغاية، واليوم كل الأمور ملائمة. سواء تحرَّكت أو انتظرت، ستشعر بتوافق اتجاهك الداخلي مع العالم الخارجي."},
  "8,3":{"third":12,"text":"اليوم قد تكون هناك مخاوف وشعور بفقدان، لكن الزواج والسفر سيكونان على العكس سلسين. ما فقدته قد يعود بطريقة أخرى، فحافظ على الثقة."},
  "8,12":{"third":3,"text":"اليوم مناسب للسفر أو لطلب الدعم المالي، وعلى الرغم من الضائقة المالية بعض الشيء، فإن العلاقات الاجتماعية ستقدم لك يد العون. لقاءات طويلة وإعادة لقاءات قد طال انتظارها تثير الترقب."},
  "5,14":{"third":0,"text":"من المرجح استرجاع الأشياء المفقودة، وستسير أمور الدراسة والعمل بإيقاع سلس. الانتقال ليس وقتًا مناسبًا حاليًا؛ بقليل من الصبر وقليل من الاضطراب تمرّ الأيام بسلاسة."},
  "5,0":{"third":14,"text":"ستصل أخبار من بعيد؛ السفر والانتقال على ما يرام إلى حدٍ ما، لكن الوضع المالي يُظهر بعض التقلبات. تعافي المريض يبشر بالاطمئنان، وباقي الأمور فلننتظر ونرى."},
  "5,5":{"third":1,"text":"اليوم تُختتم الأمور على نحوٍ مُرضٍ؛ في الزواج والثروة علامات البهجة واضحة. اليوم ثابت ومطمئن، وما هو مقدّر سيأتي في وقته."},
  "5,1":{"third":12,"text":"محاط بشعبية واسعة، يفتح لك باب الرزق، وتحيطك الصحة والمودّة. الذين فقدتهم في طريقهم للعودة، والحياة تشعر بأنها تتسع."},
  "5,12":{"third":5,"text":"التعاون يسير بسلاسة، العلاقة الزوجية مستقرة، والمعرفة والعلاقات الاجتماعية كلها في خدمتك. اليوم يوم جدير بالثقة."},
  "5,2":{"third":11,"text":"الثروة مبهجة، والتقدم في الأمور واضح وملموس. يمكن توقع السفر واللقاءات من جديد، والخسائر تُعوَّض شيئًا فشيئًا."},
  "5,11":{"third":2,"text":"كل الأمور تتجه نحو الأفضل: الصحة والعمل والعاطفة كلها تسير على المسار الصحيح. احتمالية اللقاء مجدداً أكبر مما تتصور."},
  "5,6":{"third":8,"text":"العلاقات مع الأكبر سناً متناغمة؛ الزواج والشراكة يسيران على ما يرام. \"الخير\" اليوم ليس ضجيجاً، بل إتمام هادئ."},
  "5,13":{"third":4,"text":"المجد والأمنيات تتشكلان، والأخبار السارة تأتي بلا استئذان. اليوم مناسب لأن تسير وأنت رافع رأسك، اكتفِ بابتسامة."},
  "5,10":{"third":6,"text":"الثروة والسمعة سيتحسّنان كلاهما، سيعود أشخاص من الماضي، وستُحلّ الضغائن القديمة. ستسير الرحلات والمصالحة على نحوٍ سلس، ومن المتوقع استعادة المفقودات."},
  "5,4":{"third":9,"text":"انتبه لأمور التنقل وتصليح السيارات، فقد تحدث احتكاكات بسيطة بين الأصدقاء. قد يكون في المنزل أمور تتعلق بالإنجاب أو الإنتاج، ومع وجود بعض العقبات، في النهاية يمكن أن يأتي التحول إلى الأفضل."},
  "5,7":{"third":10,"text":"اليوم من السهل أن تتأثر بما يأتي من أعلى، سواء كان ضغطًا أم رعاية. لا يجب تصديق كل شائعة عن حرب أو صراع، الثبات على نفسك هو النصر."},
  "5,8":{"third":15,"text":"جسمك وعقلك في راحة، والمشكلات التي تزعجك تتلاشى تدريجياً. يعينك أشخاص نافعون، ويعود الأصدقاء، واليوم مناسب لعرض حالتك الجيدة على العالم."},
  "5,15":{"third":8,"text":"الأمور التجارية والمتعلقة بالأراضي تسير بسلاسة، والأخبار السارة تتوالى. الشخص المحبوب بأمان، والسفر والشفاء كلّهما مُيسّران كما هو مرغوب."},
  "5,3":{"third":2,"text":"الظروف المالية قد تكون ضيقة بعض الشيء، وقضايا الحكومة أو المؤسسات قد تثير القلق بسهولة. قد تجعلك مشاجرات الأصدقاء تشعر بالإرهاق، ومن الأفضل الحفاظ على مسافة."},
  "5,9":{"third":7,"text":"الكلام قد يجرح بسهولة، وهناك مخاطر أعلى للجدال. في مسائل النقل والشؤون المالية لا تتسرع، ومع قدر أكبر من التسامح داخل الأسرة ستتمكنون من تجاوز هذا اليوم."},
  "14,14":{"third":1,"text":"اليوم قد تشعر بالتيه وعدم الاستقرار، ومزاجك كأنّه شجرة بلا جذور. هناك ارتفاع في مخاطر الشجارات أو سوء التفاهم، ومن الأفضل في الأمور المالية أن تحافظ ولا تقدم على مجازفة؛ اترك لنفسك بعض المساحة للتراجع."},
  "14,1":{"third":14,"text":"قد يشعر المرء بالفراق داخل العائلة أو بين الأصدقاء المقربين، لكن هذا لا يعني بالضرورة أمراً سيئاً. يمكن تأجيل أمر السفر قليلاً وإعطاء العلاقات بعض المساحة للتنفّس، وسيكون ذلك في الواقع أفضل."},
  "14,0":{"third":5,"text":"اليوم ثمة رعاية من شخص ذي نفوذ، وخاصة الاهتمام القادم من أعلى يمنحك الاطمئنان. الدعم المتبادل بين الأصدقاء سيجعل سير الأمور أكثر سلاسة."},
  "14,5":{"third":0,"text":"الأمور المالية قد تكون متوترة قليلاً، لكن لا داعي للقلق المبالغ فيه. الأشخاص أو الأمور المفقودة ستعود في النهاية، وطيب نية الأصدقاء والشركاء سيفتحان لك آفاقًا جديدة."},
  "14,10":{"third":2,"text":"اليوم مناسب لشراء أو تحديث ممتلكات، سواء كانت سيارة، منزل أو المعرفة الداخلية. من المتوقع العثور على الأشياء المفقودة، والعلاقة مع الإخوة والأخوات تميل إلى المصالحة."},
  "14,15":{"third":5,"text":"تسير أمور الانتقال والسفر بسلاسة نسبيًا، لكن قد تحدث احتكاكات بسيطة بين الأصدقاء. وبعد الخسائر التي لحقت بك، ستحصل على تعويض، بل قد تحقق مكاسب غير متوقعة أثناء السفر."},
  "14,11":{"third":13,"text":"اليوم مناسب لجمع مختلف \"اللحظات الصغيرة السعيدة\" المتناثرة، وقد تتحقق الأمنيات. كما ستسير الأمور المتعلقة بالسفر والإجراءات الإدارية بسلاسة، وقد تكون هناك دلائل على اكتمال في المجال العاطفي."},
  "14,13":{"third":7,"text":"في العمل هناك بعض التعرّجات/التأتّك، وفي الزواج قد تنشأ نزاعات كلامية بسهولة. لكن الخبر السار أن حالة المريض تتحسّن، وهناك علامات على سير الولادة بأمان."},
  "14,8":{"third":15,"text":"اليوم يسير على ما يرام، والصعوبات تُزاح واحدة تلو الأخرى. الأعداء يتراجعون، والعائدون سالمون، والوئام يعم البيت؛ يوم يستحق أن تتنفس فيه الصعداء."},
  "14,2":{"third":6,"text":"نقطة التحول اليوم تكمن في \"التحرك\" — السفر، البحث عن عمل، والمعاملات قد تشهدان اختراقًا. الحزن يتبدد، والأشياء أو الأشخاص المفقودون في طريقهم للعودة."},
  "14,4":{"third":9,"text":"ينبغي الانتباه أكثر إلى الصحة والسمعة، فقد تنشأ خلافات بين الأصدقاء. إذا كان ضميرك مستقيمًا، فلا داعي للقلق المفرط من الشائعات الخارجية."},
  "14,9":{"third":4,"text":"السفر والانتقال ليسا مجديين جدًا، وقد تنشأ مشاحنات بين الزوجين. لكن حالة المرض ستتحسن، والصعوبات بدأت تتبدد تدريجيًا وتشرق بالضوء."},
  "14,12":{"third":8,"text":"وصلت أخبار سارة من صديق بعيد؛ السفر والشؤون تجريان بسلاسة وإحسان. الصديقة أو الحبيبة بخير، اليوم يستحق أن تُدعى لمن هم بعيدون."},
  "14,6":{"third":10,"text":"اليوم يوم مناسب لـ\"حل العقد\" — الاقتصادية، الزوجية، والشراكات، كلها يمكن ترتيبها وتوضيحها. خاصةً قبل وبعد يوم الخميس مناسب جداً لتمني الأمنيات أو دفع الأمور الكبيرة قدماً."},
  "14,7":{"third":3,"text":"اليوم المزاج عُرضة للاكتئاب، والشعور بالثقة يتآكل. أمور السفر ستواجه صعوبات كبيرة، لكن الحمل أو المرض قد يشهَدان تحولاً نحو الأفضل."},
  "14,3":{"third":2,"text":"أشعر اليوم ببعض العزلة وقلة الدعم، وضغط مالي واجتماعي ثقيل على كتفيّ. لكن لا تيأس — أشد اللحظات قد تكون مقدِّمة لانقلابٍ نحو الأفضل."},
  "1,1":{"third":1,"text":"اليوم مناسب للاجتماع وليس للتفرق، سواء لمواجهة العدو أو لاستقبال الضيوف، قوة الجماهير في صفك. تصل رسالة من بعيد أو من مكان عالٍ تجعلك تشعر بأنك مرئي ومقدَّر."},
  "1,8":{"third":8,"text":"في ميدان التجارة ستحظى بنجاح وازدهار، وبشؤون الزواج ستتضح الأمور. ستلتقي بكبار الاحترام أو المعلمين، والنزاعات في المحكمة ستسير لصالحك. اليوم مناسب للقراءة والدراسة ولسماع أخبار سارة."},
  "1,7":{"third":7,"text":"اليوم قد تتولد لديك مشاعر الوحدة بسهولة، وشؤونك المالية قد تشهد بعض التعثر. لا تهتم بالخلافات مع من هم أدنى منك منزلة، فالأهم هو الاعتناء بنفسك. على المرضى أن يكونوا أكثر حذراً اليوم."},
  "1,2":{"third":2,"text":"أولئِكَ الذين يعيشون تحت سقفٍ واحدٍ يجلبون لك الدفء، والخدم أو التابعون يبذلون جهدهم بإخلاص. سيتلقّى أصدقاء من بعيد أخبارًا، لكن حالة المريض لن تشهد تحسّنًا كبيرًا في الوقت الحالي، ويجب الانتظار."},
  "1,11":{"third":11,"text":"اليوم يستحق أن يكون مفعمًا بالأمل، ستقابل أشخاصًا جديرين بالاحترام، أو ستحرز تقدمًا في الحكمة. ستكون العلاقة مع المسؤولين متساهلة، والنزاعات ستنتهي بطريقة أفضل لك."},
  "1,12":{"third":12,"text":"اليوم مناسب للتواجد مع أشخاص حكماء؛ نظراتهم ستمنحك الطمأنينة. الخوف والقلق في تراجع، وتُهيأ رحلة ممتعة أو رحلة عمل."},
  "1,13":{"third":13,"text":"أشياء جيدة تحدث بهدوء؛ المال سيأتي بطريقة نظيفة وشريفة، وستكون العلاقات مع الأصدقاء والنساء سلسة ومتناغمة. أخبار سارة من بعيد في الطريق، واليوم مناسب للاتجاه نحو الحدائق والواحات والأماكن الواسعة."},
  "1,4":{"third":4,"text":"قد تظهر حولك أمور تتعلق بالحرب أو الدعاوى القضائية أو التعازي، لكن ليس عليك الانغماس فيها بشدة. هناك من يتعرض للظلم، وما يمكنك فعله هو الحفاظ على وعيك ولطفك."},
  "1,15":{"third":15,"text":"بشكل عام اليوم سيتجه نحو نتيجة جيدة، فالطمأنينة والسلام سيظهران في النهاية. لكن إذا كان هناك جدال من حولك، فلا تسرع في اتخاذ موقف؛ أحيانًا التراجع خطوة إلى الوراء أبلغ حكمة من الاندفاع إلى الأمام."},
  "1,3":{"third":3,"text":"شؤون الأسرة تُثير القلق، والوضع المالي متوتر بعض الشيء. لكن أمور العمل ستكون آمنة، والزواج والحب يجدان نقاط تحوّل وسط الفوضى. الأشخاص الذين هم في مراتب أدنى يدعمونك بصمت."},
  "1,6":{"third":6,"text":"اليوم قد يكون هناك خسائر لا تُستَرد، لكن ثَمّة مكاسب مشروعة أيضًا. إذا رأيت علامات مبشرة، فسيُسير الزواج والتجارة بسلاسة. في شأن الابنة أخبار سارة، والرغبة تقترب."},
  "1,0":{"third":0,"text":"اليوم مناسب للسفر والانتقال، السكن مستقر والأعمال التجارية مشغولة ومثمرة. ستحظى بانتباه المسؤولين، لكن قد تنشأ مشادات كلامية بين الزوجين؛ لا تضخموا الأمور الصغيرة."},
  "1,10":{"third":10,"text":"اليوم مناسب لأن تكرّس كل طاقتك للعمل أو الأعمال التجارية، فالثروة والامور ستتجه إلى مسارٍ جيد. رحلة ممتعة، وستحظى بتقدير ورفع من قبل أصحاب المناصب العليا."},
  "1,9":{"third":9,"text":"اليوم عرضة للشعور بالحزن، وقد تنشأ نزاعات أو عداءات مع الآخرين. أمور السفر قد لا تكون سلسة، والأخبار السارة لن تأتي مؤقتًا؛ اهتم أولًا بالحفاظ على هدوءك الداخلي."},
  "1,5":{"third":5,"text":"اليوم تسير كل الأمور نحو نهايات سعيدة، الحب مُكتمل، والزواج سعيد. الأشخاص الذين فقدتهم في طريقهم للعودة، وستشعر أن الفجوات في حياتك تُملأ."},
  "1,14":{"third":14,"text":"اليوم قد تشعر بخيبة أمل ومرارة بسهولة، فالمشاحنات والخسائر المالية تُرهقك. عندما يطول بك المرض من الأفضل أن تبطئ وتنتقل بحذر، فبعض الخسائر تحدث لإفساح المجال لشيء جديد."},
  "15,1":{"third":15,"text":"اليوم مناسب للتجمعات؛ البهجة في حفلات الزفاف أو الاحتفالات ستجعلك تشعر بأنك مرغوب. لكن إذا بدت العلامات سلبية، فاحذر من حدّة الكلام، ومن الأفضل أيضاً ألا تكون متسرعاً في الأمور المالية أو العائلية مؤقتاً."},
  "15,13":{"third":0,"text":"السفر والأمور كلها تسير بسلاسة، والسعادة قريبة منك. الأصدقاء متناغمون، وهناك أخبار طيبة في البيت، لكن شأن المرضى يحتاج إلى مزيد من الصبر."},
  "15,7":{"third":11,"text":"أثناء السفر قد تحصد بعض النتائج، والأعمال يمكن أن تستمر في التقدّم أثناء سيرها. الخدم أو المرؤوسون سيبذلون جهدًا من أجلك، والخسائر تُعوَّض تدريجيًا، فلا داعي للقلق."},
  "15,11":{"third":7,"text":"خطواتك تتقدم ببطء بعض الشيء، ويجب الانتباه إلى الأمور الصحية. إذا كنت تنتظر تحولًا في الزواج أو العلاقة، فلا تتعجل الحكم اليوم وامنح الأمر نظرة إضافية قبل اتخاذ القرار."},
  "15,6":{"third":4,"text":"اليوم معاملات تجري بسلاسة، وأمور الزواج بدأت تتضح. أخبار من مكان بعيد مثيرة للتوقع، مناسب لزيارة الأصدقاء، والزراعة والبناء، إنه يوم مناسب للتحرك."},
  "15,4":{"third":6,"text":"الأمور المالية غير مستقرة بعض الشيء، والنزاعات مع الآخرين قد تستنزف الذهن. لكن الأصدقاء في طريقهم للعودة، وحالة المريض تتحسّن ببطء؛ امنح الوقت بعض الوقت."},
  "15,15":{"third":1,"text":"السفر والشراكات مفيدان، وتشعر براحة مالية أيضًا. إن سلاسة اليوم ليست صدفة، بل نتيجة الخطوات التي اتخذتها سابقًا."},
  "15,0":{"third":13,"text":"النساء والمرؤوسون سيقدمون لك المساعدة، ومن المتوقع استعادة الأشياء المفقودة. اليوم مناسب للاستفادة من قوة من حولك، فلا حاجة لأن تفعل كل شيء بنفسك."},
  "15,3":{"third":2,"text":"ما فُقد عاد ليُستعاد، والالتقاء بالنساء والأصدقاء مليء بالدفء. لكن لا ينبغي الانخراط في القمار أو المضاربة، فالخسارة غالبًا ما تختبئ في الإغراء."},
  "15,2":{"third":3,"text":"الظروف المالية ضاغطة بعض الشيء، ومن السهل أن تنشأ سوء تفاهم داخل العائلة. لكن رغم صعوبة الرحلة، فلن تذهب سدى، وهناك مؤشرات على تيسّر في مسألة الاحتجاز."},
  "15,10":{"third":14,"text":"اليوم يحمل معه مكاسب ومخاطر في آنٍ واحد، السفر يسير بسلاسة، لكن هناك احتمال لتكبد خسائر مالية. أمور الحوامل قد تشهد بعض المطبات، والنتيجة لا تزال مبشرة، ولا حاجة للمبالغة في الحساب بين الأصدقاء."},
  "15,14":{"third":10,"text":"الأمور الطيبة قادمة، والأشخاص والأشياء القديمة في طريقها للعودة. سيتحسن الزواج والصحة، يمكنك أن تمضي اليوم بقلبٍ يملؤه الانتظار."},
  "15,8":{"third":5,"text":"الراحة الجسدية والنفسية، والثروة والزواج يتجهان نحو تحسّن أكبر. الأصدقاء الذين فقدتهم سيعيدون الظهور في حياتك."},
  "15,5":{"third":8,"text":"كل ما في اليوم يحمل طابع \"كِفَايَة\" — ثروة كافية، سعادة كافية، أصدقاء كافون. الرحلة سلسة، والمزاج مليء."},
  "15,9":{"third":12,"text":"الحظ آخذ في الارتفاع، هناك أخبار جيدة للسفر والثروة، والرؤساء أو الحكومة سيولونك بعناية أكثر. قد يكون من الصعب استرجاع بعض ما فقدت، لكن الجديد في الطريق."},
  "15,12":{"third":9,"text":"أحداث اليوم الجيدة تتعلق بالنساء بشكل أكبر، كما أن السفر والبهجة سيكونان أخفّ. قد تتلقى أخبارًا من بعيد، أو تقضي وقتًا ممتعًا مع صديقات أو قريبات."},
  "6,1":{"third":6,"text":"اليوم يوصى بالهدوء لا بالنشاط، ومن الأفضل تأجيل السفر أو الانتقال مؤقتًا. في قلبك أمور تشغلك، لكنها تمهيد لـ\"شراء\" مستلزمات جديدة للحياة، وسيمنحك دعم ومرافقة النساء شعورًا بالاطمئنان."},
  "6,6":{"third":1,"text":"تميل أفعال اليوم إلى التركيز على \"البناء\" — سواء كان بناء منزل أو تأسيس أسرة أو بدء شراكة. يبدو أن المنصرفين يظهرون بوادر عودة، والعلاقات الحميمة تبدو أكثر تماسكًا اليوم."},
  "6,2":{"third":0,"text":"من المرجح أن تتحقق أهداف اليوم عبر نساء في محيطك أو شراكات أو معاملات. لكن انتبه، فقد تكون بعض المعاملات مزعجة، وإذا كانت تتعلق بسفر مريض أو حالة امرأة حامل فليتحلَّ الأمر بمزيد من الحذر."},
  "6,0":{"third":2,"text":"قد تأتي أخبار اليوم فجأة، وربما تصاحبها بعض النقاشات أو الجدل، لكن لا داعي للقلق بشأن ذلك. غالبًا ما تكون خيوط الدخل والصداقة مخبأة داخل هذه الروابط غير المتوقعة."},
  "6,9":{"third":10,"text":"ربما تواجه صعوبات اليوم، لكن النتيجة ستكون جيدة. في السفر أو عند مواجهة صراعات مع السلطات، ستكسب المعرفة والسلوك الحسن الثروة والاحترام في النهاية. كل الصعاب تمهّد الطريق للرغبات التي تريد تحقيقها."},
  "6,10":{"third":9,"text":"اليوم قد تكون هناك قلق قصير الأمد على الصعيد المالي، ومن الممكن أن تخلُو لقاءاتك مع الأصدقاء من بعض الاختلاف في الآراء. لكن الخبر السار أن المرض والقيود يتلاشىان، وطالما لم تتمسك بالتفاصيل الدقيقة فستكون الأمور عموماً بخير."},
  "6,5":{"third":6,"text":"اليوم هو نمط \"تبدأ بالمر ثم تنتهي بالحلو\". الجدال مع القاضي أو المسؤول قد يكون مرهقًا، لكنك ستكتشف في النهاية أن هذه العقبات الظاهرة هي التي تعزز مكانتك وثروتك. بتجاوز الصعوبات الحالية سيتحقق ما تتمنى."},
  "6,11":{"third":7,"text":"من المرجح أن تواجه اليوم تغيّرات جيدة أثناء السفر أو الانتقال، وستتحسّن حظوظك المالية قليلاً، لكن قد تشعر بالاغتراب عاطفياً. السعادة غالباً ما تمنحها لنفسك؛ بدلاً من انتظار الآخرين لملء الفراغ، اعتنِ بنفسك أولاً."},
  "6,14":{"third":13,"text":"اليوم قد تحقّق بعض المكاسب المادية من السفر أو الانتقال، لكن من السهل أن تنشأ احتكاكات كلامية مع الزوجة أو الأصدقاء. إذا شعرت بتوتر في العلاقة، فلا بأس أن تتراجع خطوة وتمنح نفسك بعض المساحة."},
  "6,12":{"third":8,"text":"اليوم الوضع المالي قد يكون متوتراً قليلاً والدخل أيضاً ضئيلاً، وقد تحدث بعض الخلافات مع النساء. لكن إن خرجت من المنزل فقد تكتشف فرصاً أثناء السفر، وحالة المريض تتحسّن."},
  "6,8":{"third":5,"text":"اليوم مناسب لبدء شيء بنشاط — عمل واحد، محادثة، صفقة. علاقة مع الزوجة متناغمة، وقد يصل خبر من زوج أو رفيق فقدت الاتصال به، ويمكن تحقيق توافق بين الشركاء."},
  "6,7":{"third":9,"text":"اليوم المزاج قد ينزلق إلى الأسفل بسهولة، وقد تتعرّض خطط السفر أيضًا للعقبات. انتبه للأصوات القريبة منك التي تبدو ودودة لكنها قد تجلب الخيانة أو النقد. أحيانًا العزلة تحميك أكثر من الضوضاء."},
  "6,3":{"third":10,"text":"اليوم مناسب لتجميع الثروة، وخصوصًا عبر الوسائل المشروعة. النساء سيجلبن الفرح والسعادة، ومن المناسب أيضًا التخطيط لمواضيع تتعلق ببناء أو تجديد المنازل. قد تكون هناك بعض الشجارات مع الأصدقاء، لكنها ليست سوى حجر صغير في الطريق."},
  "6,13":{"third":3,"text":"قد تواجه اليوم بعض الصيحات أو المشاجرات المزعجة، لكن هناك أيضًا فرصة لكسب مكاسب قيمة. الحب يزدهر أحيانًا من الاحتكاك، والزواج والسفر يسيران بسلاسة، وأخبار صديق بعيد تثلج القلب."},
  "6,15":{"third":11,"text":"قد تكون هناك رغبة في الزواج في قلبك اليوم، وقد تشعر ببعض القلق الذي لا يزول بسهولة. لكن ما فُقد سيعود بطريقة أخرى، وما هو مكبوت سيُطلق سراحه، وسيكون الحمل آمنًا."},
  "6,4":{"third":2,"text":"اليوم يوم \"المشي\" و\"الوصول\". الخروج سيجلب لك مكاسب، وستتطور الأمور بالطريقة التي تتوقعها. وجود نساء حولك سيمنحك الطمأنينة، والشخص المفقود في طريقه للعودة سالماً. هذا يوم يسهل فيه تحقيق الأمنيات."},
  "7,0":{"third":9,"text":"اليوم تشعر بممانعة تجاه التنقل، كما أن تحركاتك قد تُعاق بسهولة. لديك أمورٌ مضغوطة في قلبك، ومن السهل أن يزعجك الأشخاص الصغار المحيطون بك. الجدال مع من يختلفون معك معرفيًا سيستنزف طاقتك، فالصمت هو حكمة اليوم."},
  "7,9":{"third":0,"text":"لون اليوم قاتم قليلاً؛ التوقف الاقتصادي ومشاكل السفر تراكبت لتمنحك شعورًا بالضعف. لكن تذكّر: كلما شعرت أنك \"لا تستطيع المضي قدمًا\"، زاد احتياجك لأن تتوقف وتعدّل تنفسك."},
  "7,8":{"third":6,"text":"سعادة اليوم تأتي من البعيد — رسالة، عودة عزيز، أو صفقة جيدة. لكن الأمور بين الناس قد تخيّب الأمل بسهولة، فالشقوق في الشراكة أو الزواج ليست شيئًا يحدث بين عشية وضحاها. ما ينبغي أن تبتهج به هو تلك المكاسب التي هي حقًا لك."},
  "7,6":{"third":8,"text":"اليوم شعور بالجمود واضح، سواء في العمل أو الحياة، هناك شعور بأن شيئًا ما يعيقك. بالنسبة للحوامل أو المرضى، فهو يوم يتطلب الحذر الشديد. لكن التحول غالبًا ما يأتي بعد هذا \"التعثر\"، فالصبر يختزن بدايات الانفراج."},
  "7,5":{"third":4,"text":"اليوم سيكون هناك بعض المكاسب المالية أو المادية. لكن إن لم تكن الأجواء المحيطة مناسبة، فقد تليها مشاحنات وخسائر. المال شيء جيد، ولكن عندما يأتي محاطًا بالمخاطر عليك أن تتبصر أولًا قبل أن تمتد يدك."},
  "7,4":{"third":5,"text":"اليوم مناسب للمبادرة بالخروج؛ قد تجني فوائد غير متوقعة أثناء السفر أو التنقل. قد تشعر برغبة في الزواج أو في علاقة عاطفية، لكن احذر—فالعداء غالبًا ما يختبئ وراء الإفراط في الودّ."},
  "7,14":{"third":3,"text":"سفر اليوم بلا طعم، لا ربح فيه ولا متعة، سيستهلك فقط الطاقة والمال بلا فائدة. أمور الزواج أيضاً لا تثير الحماس. إذا شعرت بالإرهاق في داخلك، فاسمح لنفسك ألا تضطر لإنجاز أي شيء اليوم."},
  "7,3":{"third":14,"text":"نهاية اليوم ليست جيدة، سواء من خسائر اقتصادية أو التباعد في العلاقات، كل ذلك يجعل المرء يشعر بالإحباط. إذا كان هناك لقاء أو موعد، اليوم ليس مناسبًا للإصرار عليه. صخب الحشود قد يجعلك تشعر بمزيد من الوحدة."},
  "7,1":{"third":7,"text":"رحلة اليوم تبدو بلا معنى، وقد تتعرّض لخسائر مالية. قد تشعر بالاغتراب وسط الحشود. لا تُجهد نفسك لتندمج؛ في بعض الأيام، يحتاج القلب أولاً إلى أن يجد مكانه لدى نفسه."},
  "7,7":{"third":1,"text":"يبدو أن حزن اليوم تزايد، والمشاجرات، والصراع مع الأشخاص الدونيين، وفقدان المكانة والسلطة، كأن كل الأبواب تُغلق. وقد تنقلب قسوتك مع المرؤوسين عليّك أيضاً. لكن تذكّر، إن أعمق الوديان غالباً ما تكون المكان الوحيد الذي يبدأ منه طريق الخروج."},
  "7,10":{"third":2,"text":"معظم متاعب اليوم تنبع غالبًا من التعامل مع أشخاص يصعب التعايش معهم — قد يكونون ناقصي العقل، أو قد تكون النساء فاسدات الأخلاق. بدلاً من الجدل، تجنّب. هذا ليس ضعفًا، بل ترك للطاقة للأشياء التي تستحقها."},
  "7,2":{"third":10,"text":"ستتحسن الأوضاع الاقتصادية اليوم، وسيبدأ الأشخاص أو الأمور المفقودة في الظهور تدريجياً. كما يتحسن الوضع الصحي. لكن الانتقال أو السفر لا يزالان غير ميسّرين كثيرًا؛ فبعض الأمور ليست للقيام بها الآن، بل انتظارًا لزمن مناسب."},
  "7,13":{"third":12,"text":"اليوم ستتلقى رسالة أو خبرًا من شخص بعيد أو صديق يدفئ قلبك. ستسير الأعمال والوظيفة بسلاسة، والأمور التي أثقلت قلبك لفترة طويلة بدأت تتلاشى. حالة الزوجة أو الصديقة الأنثوية ستمنحك الطمأنينة أيضًا."},
  "7,12":{"third":13,"text":"أخبار اليوم مطمئنة — الأمور تسير بسلاسة، والنهاية مُرضية، والصديقات والأقارب النساء بخير، والسفر قيد التخطيط أيضًا. الذين فقدتهم في طريق العودة، وكل شيء يتجه نحو حيث ينبغي أن يكون."},
  "7,11":{"third":15,"text":"حظك اليوم يحمل لمحة من المرونة والنور — العمل والسفر والصحة كلها على المسار الصحيح، والأشخاص الذين فقدتهم يعودون تدريجياً. كبار السن أو السادة في الحكومة يراقبونك، والمخاوف تتلاشى شيئاً فشيئاً."},
  "7,15":{"third":11,"text":"اليوم من المرجح أن تتحقق الأمنيات، وسيتجمع الأصدقاء من جديد حولك. الفرح والسعادة ملموسان — راحة الجسد والنفس، وسير الأمور بسلاسة، والمشاحنات السابقة على وشك الانتهاء. قد يبقى في قلبك بعض القلق، لكنه مجرد شعور إنساني طبيعي، فلا داعي للقلق المفرط."},
  "4,1":{"third":1,"text":"اليوم فيه بعض الصخب، والأماكن المزدحمة قد تنشأ فيها خلافات بسهولة. قد تتلقى ثوبًا أحمر أو ثمينًا، لكن قد يرغب البعض أيضًا في المغادرة. من الأفضل تجنّب الشرب والمقامرة في الوقت الحالي، إذ أن الفرح الظاهري يخفي ثمنًا."},
  "4,4":{"third":4,"text":"في حظك اليوم، كل من \"الحركة\" و\"الاصطدام\" واضحان — السفر والقيام بأعمال يلوحان في الأفق، لكن قد تواجه أيضًا تقلبات أو صراعات. الخوف والقلق قد ينبعان من المراتب العليا، والخسائر المادية تضيف قلقًا. لكن تذكر أن في الاضطراب أيضًا فرصة للحياة، وأن الفوضى تعني انهيار النظام القديم."},
  "4,7":{"third":7,"text":"ألوان اليوم قاتمة بعض الشيء. يبدو أن الشجار والعدائية لا مفر منهما، وبالرغم من احتمال ورود مبالغ أو ممتلكات إلى يديك، إلا أن العمل لا يزال متوقفًا وضغوط الحياة مستمرة. ما يمكنك فعله هو إنجاز ما أمامك واحدة تلو الأخرى—الحزن لن يبقى إلى الأبد."},
  "4,5":{"third":5,"text":"اليوم قد تشعر بمرارة \"الشيء المكتسب ثم المفقود\". الجدال مع من هم في موقع أدنى، أو المشاكل في الزواج، قد تجعلك تشعر أن الأمور الجيدة لا تدوم. لكن الذين فقدتهم في طريقهم إلى العودة، والخلافات في الشراكة ما هي إلا عواصف عابرة. انتبه إلى تلك الإشارات الطفيفة من اللطف."},
  "4,8":{"third":8,"text":"صعوبات اليوم تتحول إلى صفحة جديدة. الأمور تسير بسلاسة، ووضعك وطموحاتك يتحركان في اتجاه إيجابي. راحة الأقارب الإناث وتوافقك مع الأصدقاء هما الدعامة الأكثر ثباتًا لهذا اليوم. أنت تستحق أن تفرح لثبات هذه اللحظة."},
  "4,11":{"third":11,"text":"رحلة اليوم كانت مع الريح، ومع ما تجلبه الريح من مكاسب. تنساب سفرك وتحركاتك بسلاسة، ورفقة امرأة وودّ الأصدقاء يمنحانك دفءًا. الهدف يقترب، والتقدّم الذي يبدو تافهًا في الواقع يستحق أن يُرى."},
  "4,10":{"third":10,"text":"حصاد اليوم ملموس — اشتريت ما يرضيني، وما فقدته استعدته بسرعة. في الزواج ثمة دفء، والمكانة ترتفع بثبات. الفرح والسعادة ليسا وهماً بعيداً، بل حياة اليوم الملموسة والقابلة للإحساس."},
  "4,12":{"third":12,"text":"اليوم هو يوم \"الشُّون\" (الشُّوْن). السفر يسير بسلاسة، والأحوال جيدة، والنساء والأصدقاء يمنحونك شعورًا بالأمان والدعم. لن تتأخر الأمنية طويلًا، ستأتيك بسرعة وبطريقة غير متوقعة. احرص على أن تكون منفتحًا لاستقبال الأمور الطيبة اليوم."},
  "4,2":{"third":2,"text":"اليوم تبدو الحوادث المحظوظة والمسيئة متشابكة — فبينما تتعثر بعض الأمور، يسود البيت حيوية ووفرة. العلاقات مع النساء تجلب الدفء، كما قد تجني نفعًا من السفر أو التجارة. قد يكون هناك ضغط من سلطات أو أشخاص أصحاب نفوذ، لكن ليس عليك الرد على كل شيء."},
  "4,13":{"third":13,"text":"خير اليوم واضح. التقدّم حاصل في الزواج والسفر، وما فُقد آخذٌ في العودة، والأمنيات تتبلور. أمور مستلزمات الزواج أو الهدايا تُثير التطلع، وعودة الحبيب أو الأقارب تجعل اليوم كاملاً. تستحق أن تشعر بالاطمئنان حيال ذلك."},
  "4,0":{"third":0,"text":"اليوم غير مناسب للانتقال أو السفر؛ ستكون الأفعال عرضة للعوائق، والخسائر المالية ستجعل الخطط صعبة. تحتاج حالة حمل الزوجة إلى مزيد من العناية، وقد تنشأ خلافات في علاقات الشراكة. اليوم يستحسن التمهل والهدوء."},
  "4,3":{"third":3,"text":"اليوم قد تشعر بثقل شديد. الخسائر المالية، معاناة ذوي المكانة المتدنية، المشاكل في الزواج والعمل، كلها تجعل التنفس صعبًا. لكن تذكّر أن أصعب اللحظات غالبًا ما تكون اللحظة التي ينمو فيها الإنسان فعلاً."},
  "4,14":{"third":14,"text":"غيوم اليوم كثيفة إلى حد ما. الاضطراب والخلافات المحيطة تبدو لا يمكن تجاهلها، والخوف والقلق يدوران في قلبك. الخسائر الاقتصادية والركود في الأمور تجعلك تشعر بالعجز. لكن كلما كانت الأيام كذلك، زاد لزوم تذكُّر حماية نفسك."},
  "4,9":{"third":9,"text":"اليوم قد تشعر بسهولة بالندم. السفر والأعمال قد لا تسيران بسلاسة، وقد تتعرض لخسائر مالية. تحتاج حالة حمل الزوجة إلى عناية إضافية، وقد تواجه السيارة أو الأغراض أعطالاً. لكن ثق أن هذه الصعوبات ستمضي، والندم جزء من النمو."},
  "4,6":{"third":6,"text":"اليوم هو يوم \"المرض يزول كخيط يُسحب\". الألم والمرض يتراجعان تدريجيًا، وحمْل الزوجة سيكون آمنًا وسلسًا. الأعمال والزيجات ستشهد تقدمًا، والمنازل المفقودة أو الأشياء القديمة من المرجح أن تعود بأمان. صَبْرُك اليوم يستحق العناء."},
  "4,15":{"third":15,"text":"حظك اليوم يتضمن كلمتين: \"الاستعانة بالقوة\". اقترضِ المال أو اطلبِ المساعدة من امرأة، فذلك سيمكنك من تجاوز العقبات بسهولة. السفر وقضاء الوقت مع الآخرين يجلبان الرزق، لكن قد تنشأ مشاحنات بين النساء. اليوم كل ما عليك فعله هو القيام بواجبك، ولا داعي لأن تتورطي في خلافات الآخرين."},
  "13,1":{"third":13,"text":"اليوم مناسب للتجمّع مع الناس، ومن المناسب بشكل خاص حضور التجمعات النسائية أو حفلات الزفاف. وإذا أمكنك المشي في الهواء الطلق فسيكون ذلك أوْفى — فالتخيّل المتعلق بالحدائق أو الواحات ليس ببعيد عنك. الحظ المالي والأهداف مخفيّان داخل هذا الصخب، وينتظران نضوج الوقت."},
  "13,13":{"third":1,"text":"سعادة اليوم تكمن في البعيد — رسائل أو بريد أو أخبار من الأصدقاء ستجلب دفئًا وراحة. الاقتراحات المتعلقة بالأدوات المنزلية أو المواعيد تستحق الانتباه أيضًا. قد تكتشف أن البهجة معدية."},
  "13,12":{"third":7,"text":"اليوم تجري أمورك وسفرك بسلاسة، وتشعر براحة مادية بعض الشيء. أولئك الذين يبدون متواضعين أو غير بارزين حولك هم في الحقيقة من يمنحونك الاطمئنان. لا حاجة للسعي وراء أمور عظيمة؛ رخاؤك اليوم يكمن في هدوء الحياة."},
  "13,7":{"third":12,"text":"قد تنشأ احتكاكات اليوم مع النساء أو الشركاء، كما أن العقبات في العمل قد تثير القلق. لكن من فقدتهم في طريقهم إلى العودة، والأخبار من بعيد تحمل دفئًا. لا تخشَ الفجوة مع الأكبر سِنًا في العائلة؛ فأحيانًا الصمت أقوى من الحوار."},
  "13,8":{"third":14,"text":"اليوم ليس مناسبًا لإجراء مشتريات أو استثمارات كبيرة، ويجب توخي الحذر الشديد أثناء السفر. لكن حالة المريض تتحسن، وهناك دفء يظهر في العلاقات العاطفية. قد لا تعود الأشياء المفقودة فورًا، لكن العبء الذي في قلبك بدأ يخف تدريجيًا."},
  "13,14":{"third":8,"text":"تداولات اليوم ليست سلسة تمامًا، وقد تجلب أمور متعلقة بالنساء أو بالغطاء بعض القلق. لكن القيود تزول وحالة المريض تتحسن. الأمور التي بدت غير مواتية في حياتك تفتح لك نافذة أخرى."},
  "13,2":{"third":4,"text":"اليوم، أثناء التعامل مع النساء، قد تشعر بسهولة بضغط أو خلافات مالية. لكن أولئك الذين فقدتهم أو الأشياء المفقودة في طريقها للعودة؛ لا تدع الخلافات الصغيرة أمامك تُنْسِي ضوء البعيد."},
  "13,4":{"third":2,"text":"اليوم يطفو على السطح رغبة في الزواج أو الشؤون العاطفية، كما أن اللقاء مجدداً مع امرأة أو مريض يبعث على التطلع. السفر والبحث عن الأشياء المفقودة مناسبان للتقدّم، كما أن الصفقات والشراء والبيع أكثر سلاسة."},
  "13,15":{"third":0,"text":"حظك اليوم مشرق — الأمور تتقدم بسلاسة، والأمنيات تتشكّل خطوةً بخطوة. لقاء الأحبة وفرح الأصدقاء يجعلان اليوم مليئًا بالرضا. ما فُقد سابقًا يتم تعويضه، والأمل يبدأ في التحقق."},
  "13,0":{"third":15,"text":"رحلة اليوم ليست جغرافية فقط، بل هي أيضاً حالة نفسية. سترى أشياءً ووجوهًا جميلة، وسيبدو الوجود أكثر امتلاءً. قد تظهر أمامك حفلات زفاف واحتفالات، فالحب والاحترام أكثر سهولة في التدفق اليوم."},
  "13,6":{"third":3,"text":"ربما تكون ظروف المرأة اليوم أو أقربائها/صديقاتها غير مواتية، والخسائر المادية تثير القلق. قد تلازمك صعوبات الحياة وقضايا متعلقة بالحمل في ذهنك. لكن ثق أنه رغم القيعان هناك بقايا ضوء—فالمركبة أو الأشياء المفقودة ليست نهاية المطاف."},
  "13,3":{"third":6,"text":"رحلتك اليوم لم تكن مريحة، الحزن والقلق يطفوان بسهولة. الخسائر المادية، معاناة الخدم أو المرؤوسين تتركك متعبًا. العقبات في الزواج أو الشراكات تسبب صداعًا أيضًا. لكن تذكر أن هذه المشاعر مجرد عابر مؤقت."},
  "13,9":{"third":11,"text":"تسير أمور اليوم بسلاسة، والأعمال مستمرة في التشغيل. خلال السفر ستحظى بلطف واحترام من قبل المسؤولين أو الإداريين. على الرغم من أن بعض الأشياء قد يصعب استعادتها، فإن طالما لديك الإرادة وصبرت، فإن عناية السماء ستأتي في النهاية."},
  "13,11":{"third":9,"text":"حظك اليوم في تحسّن — ترقية مكانتك، تقدير من الرؤساء، شوق للزواج واكتمال الحب. خبر حمل الزوجة وولادة الطفل يبعث على الاطمئنان. الأمنيات في طريقها للتحقق، فلا تستعجل."},
  "13,5":{"third":10,"text":"اليوم مليء بأشياء جميلة — السعادة والفرح محسوسان بوضوح. التنقل وشراء وسائل النقل يسيران بسلاسة، والزواج والعلاقات الشراكية تتحسن. الأغراض المسروقة أو المفقودة ستُستعاد سريعًا، اليوم هو يوم \"مُكتمل\"."},
  "13,10":{"third":5,"text":"ثروتك ومنزلة اليوم في تحسّن، والمهام تتقدّم بسلاسة، والنهاية ستكون جيدة. الأصدقاء الذين فقدتهم سيعودون إليك قريبًا، والجفوة بين الأصدقاء بدأت تتلاشى. زوجتك حامل وبصحة جيدة، وستحقق نجاحًا أيضًا في الأعمال والعلاقات الشراكية. اليوم يستحق التوقُّع."},
  "11,1":{"third":1,"text":"سعادة اليوم تتسع نحو الخارج — تلك التقدّمات المتعلقة بالمكانة والسلطة والشؤون كلها تسير بسهولة، كأن قوة سلسة تدفعك للأمام. الأهداف والرغبات لم تعد مضطرة أن تبقى مخبأة في قلبك، لأنها تتحقق خطوة بخطوة."},
  "11,11":{"third":11,"text":"اليوم مناسب للخروج والتنزه مع الكبار والأصدقاء، ستسير الرحلات والتحركات بسلاسة، والثروة تقترب أيضاً. علاقات الشراكة جيدة، وكل شيء يبدو مرتباً. فقط هناك أمور بمجرد فقدانها يصعب استعادتها — ليس كل ما فات له طريق للعودة، فالأفضل اليوم أن تُقدّر ما أمامك."},
  "11,0":{"third":10,"text":"خيطا اللقاء مخبوء في تنقلك أو تحركاتك اليوم — الأشخاص المفقودون في طريقهم للعودة، والأمور تسير بسلاسة أكثر مما تتوقع. كبار السن بصحة جيدة، ومكانتك وثروتك ترتفعان بثبات، وكل شيء يتجه نحو الأفضل."},
  "11,12":{"third":12,"text":"رحلة اليوم ومعاملاتك تحملان بركات ومساعدة من الأكبر سناً. الخدم أو المرؤوسون موالون وجديرون بالثقة. الأمنيات التي كنت تفكر بها دائماً تقترب منك بطريقة هادئة ومؤكدة. اليوم مناسب للابتهاج مع وضع القدم على الأرض."},
  "11,2":{"third":6,"text":"رحلة اليوم خفيفة، يرافقك الفرح. تسير الأمور بسلاسة، وحالة المرضى تتحسن أيضًا. الأمنيات في طريقها إلى التحقيق، لا تسرعها؛ ستأتي في وقتها المناسب."},
  "11,14":{"third":4,"text":"في مسيرتك اليوم حققت مكاسب. حماية الكبار ودخول الثروة يجلبان سعادة ملموسة. تلك الأعمال الجيدة تكتسب لك الحقوق ورأس المال، فتابع التقدم إلى الأمام."},
  "11,6":{"third":2,"text":"اليوم ستنال رحلاتك وثروتك اعترافًا ورعاية من الأكبر سنًا والمرؤوسين. سترى بعض الأشياء الجميلة، كما أن شراكاتك تبدو متينة. اليوم مناسب لمرافقة الأشخاص الحكماء."},
  "11,5":{"third":13,"text":"اليوم ستتلقى أخبارًا من صديق بعيد، والانتقال أو مسألة الزواج تسير بسلاسة. مساعدة الكبار ووفاء الخدم يجعلان الأمور تتقدم بصورة أكثر سلاسة. المريض أيضًا يتعافى، واليوم هو يوم \"كل شيء في الطريق\"."},
  "11,3":{"third":10,"text":"اليوم، وسط الحزن والهم يظهر صوت آخر — قد تنشأ احتكاكات بين الأكبر سناً وزوجتك، وقد يظهر العداء بين الأصدقاء. لكن الأعمال والثروة تنمو بهدوء داخل التناقضات. قد تتحقق رغبات الحبيب بسبب إصرارك، لكن المسار لن يكون سلسًا."},
  "11,10":{"third":7,"text":"سعادة اليوم ملموسة — الأمور تسير بسلاسة، الأمنيات تتحقق، والأعداء يتراجعون. تلك الأعباء التي كانت تثقل كاهلك تُنزَع واحدة تلو الأخرى."},
  "11,15":{"third":5,"text":"أرباح وتقدّم اليوم أمام عينيك. مساعدة وفرح الأكبر سناً يحيطان بك أيضًا. رحلات وسفر مليء بالبركات، والأمنيات في طريقها للتحقق. هذا يوم تشعر فيه بأن \"الأيام تمضي إلى الأمام\"."},
  "11,7":{"third":3,"text":"يبدو أن صراعات اليوم تأتي من اتجاهين — من جهة ضغوط من الرؤساء أو السلطات، ومن جهة أخرى عداوة بين النساء أو بين الصديقات. حالة المريض خطيرة، والمفقودون يمرون أيضًا بمعاناة. اليوم يتطلب كتمانَ المواقف، والمرور بهدوء."},
  "11,8":{"third":6,"text":"ثروة اليوم ووفاء الخادم أمران واقعيان. الرغبات في الزواج أو الحب تقترب أيضًا من التحقيق. الأشياء التي كانت تقيدك سابقًا بدأت تتحلل، والسفر وارتقاء المكانة في الطريق أيضًا. اليوم هو يوم مناسب لـ\"انكشاف الظلام وظهور النور\"."},
  "11,4":{"third":2,"text":"في رحلةَ اليومِ وأفعالك تختبئ ثروات. رغمَ أنَّ الشجارَ والتشويهَ والعداوةَ قد تُلازمك، فإنَّ سعادةَ الحبيبِ وعودةَ المفقودِ ستُضفيان على اليومِ لمسةً دافئة. لستَ مُلزَماً بالردِّ على كلِّ نزاعٍ، فقط اِتَّجِه إلى حيثُ يجبُ أن تذهب."},
  "11,9":{"third":15,"text":"كل خطوة تخطوها اليوم تقع على النقاط المناسبة — إجراءاتك تسير بسلاسة، ثروتك تتزايد، وسمعتك ثابتة. العداوة التي كانت تزعجك تتلاشى، والخسائر تُعوَّض. شراء وسيلة نقل أو ملابس سيكون موفقًا. الخيرات التي تأتي اليوم وصلت في الوقت المناسب."},
  "11,13":{"third":14,"text":"اليوم ستحصل على أخبار متعلقة بالميراث، أو هدية من أحد الأكبر سناً. الثروة والأخبار السارة تأتيان معًا، ومساعدة من امرأة تجعل الرحلة أكثر سهولة. من فقدته في طريقه إلى العودة، والأمنية على وشك أن تتحقق. اليوم يستحق الترقب."},
  "12,0":{"third":11,"text":"اليوم مناسب للسفر؛ أخبار من بعيد أو رسالة من صديق ستجلب لك دفئًا. ليست زيادة الثروة والسمعة بعيدة المنال، الأعداء في تراجع، والأمنيات تقترب. اليوم يوم مناسب \"للسير مع التيار\"."},
  "12,11":{"third":0,"text":"هناك اتجاه تصاعدي في حظك اليومي، والانتباه والتقدير القادم من الأعلى يجعلك تشعر بالاعتراف. أولئك الذين كانوا يزعجونك يتراجعون بعيدًا. إن لم يكن قرارًا متهورًا ناجمًا عن الحظ، فالرجاء ملاحظة التذكيرات الدقيقة بشأن صحتك — فهي أهم مما تظن."},
  "12,1":{"third":12,"text":"اليوم مناسب لقطع عقد الماضي — الأصدقاء في طريقهم للعودة، والما فقد يعود إلى مكانه. شراء وسيلة نقل أو الدفع بعمل ما سيسير بسلاسة أكثر من المتوقع، وضغط الحياة الثقيل يبدأ في الانحسار ببطء. اليوم يستحق أن تفتح قلبك."},
  "12,12":{"third":1,"text":"لون اليوم هو \"الوفرة\" و\"الراحة\". الحياة مزدهرة، والأحداث الأخيرة تبدو مريحة ومطمئنة. رفقة النساء واجتماعات الأصدقاء تمنحك دفئًا، وتسير الأمور بسلاسة، والمصاعب في تلاشي. اليوم مناسب للجلوس والتأمل والشعور بثبات اللحظة."},
  "12,13":{"third":7,"text":"اليوم ستتلقى أخبارًا من شخص بعيد أو من محتاج، والأمور تتقدّم في اتجاهٍ جيد، والخسائر تُعوَّض. الأمور التي كانت تقلقك بدأت تخفّ شيئًا فشيئًا."},
  "12,7":{"third":13,"text":"اليوم الحزن يتلاشى. الأحباء أو الأمور المهمة المفقودة تعود، والمنازعات تقترب من نهايتها. العمل يستقر، والسفر فيه مناظر لكن يحمل أيضًا إزعاجات. لا حاجة للتشبث بانتظار \"أخبار سارة\"، لأن نهاية الحزن بحد ذاتها هي أفضل خبر."},
  "12,4":{"third":10,"text":"ثروتك اليوم أكثر رسوخًا—قد تظهر حولك ذهب أو مجوهرات أو أشياء ثمينة. السفر أو الشراء يسيران بسلاسة، وخبر حمل أو ولادة الزوجة يبعث على الترقب. اليوم مناسب للمشاهدة والمشاهدة والمشاهدة، فالأحداث السارة تُعرض الآن."},
  "12,10":{"third":4,"text":"أحوال العمل أو التجارة اليوم تسير بشكل جيد، وتقدم أيضًا تخطيط للمنزل أو الأرض. تلك التصرفات الحسنة التي أجلتها تعود لتُستأنف، والخسائر تُعوَّض، وأمنيات الأصدقاء على طريق التحقيق. اليوم مناسب لبدء \"العمل\"."},
  "12,3":{"third":8,"text":"رحلاتك وأعمالك اليوم تتسم بلطف وانسيابية. أمور الشراء تجري بسلاسة، والخسائر مُعوضة، والذين غابوا عائدون في الطريق. تحسّن في الحالة الصحية، ومساعدة من امرأة تجعل الأمور أخف. أمانيك اليوم أقرب خطوة مما كانت عليه أمس."},
  "12,8":{"third":3,"text":"اليوم السعادة تصحبها مخاوف — قد تكون هناك خسائر مادية، وهروب من في موقع أدنى أو حالة مريض تسبب قلقًا. لكن الخلافات في طريقها إلى الانتهاء، لا تزال هناك مودة في الزواج، وما فُقد عائد. اليوم \"الخير\" و\"الشر\" متداخلان، لا داعي للتعجل في التمييز، فقط استمر في التقدم."},
  "12,5":{"third":2,"text":"اليوم مناسب للاجتماع مع الأصدقاء، والثروة والأماني في طريقها إلى التحقيق. تسير الأمور بسلاسة، والحميمية في الزواج تتحسن، وحالة المرضى في تحسّن، والخسائر قيد التعويض. اليوم يوم جيد لـ\"الإصلاح\"."},
  "12,2":{"third":5,"text":"ثروةُ اليوم وسفرك محاطانٌ ببركةِ الأكبر سِنّك. الذين فقدتهم في طريقهم للعودة، وحملُ الزوجة وولاءُ الخدم يبعثان فيك الطمأنينة. الأماني تاقترب، والأيام تبدو ميسّرةً ومستقرة."},
  "12,15":{"third":9,"text":"عودة اليوم ونهايته حدثتا في آن واحد — الأشخاص الذين فقدت عادت بسلام، والأمور سارت بسلاسة، والنهاية جميلة. الحزن يتلاشى، وهناك دفء في الزواج أيضاً. اليوم يوم مناسب لـ“إنهاء الأمور” و“الالتقاء”."},
  "12,9":{"third":15,"text":"رحلتك وأعمالك اليوم عرضة للعوائق، والحزن والقلق يشعران بثقل. قد تظهر عقبات في العمل، خسائر مالية، ونَدَم يتعلق بسيدات أو بالأرض. اليوم ليس مناسبًا لاتخاذ قرارات كبيرة؛ الانتظار أقوى من الفعل."},
  "12,6":{"third":14,"text":"اليوم تبدو الأمور الاقتصادية والمعيشية متوترة بعض الشيء. الفقر والشعور بالمشقة يثقلان القلب، وحمل الزوجة يسبب قلقاً. شراء وسيلة نقل ليس موفقاً، والرغبات في الزواج أو العلاقات العاطفية قد تُخيّب بسهولة. اليوم من المستحسن \"التحفظ\"، وليس \"التقدم\"."},
  "12,14":{"third":6,"text":"رحلات اليوم وتحركاتك لن تكون سلسة، وقد تفقد الملابس أو الأغراض الشخصية بسهولة، وقد تنشأ عداوة وشجار بين الزوجين. الانقسامات في شراكات العمل تثير القلق أيضًا. اليوم من الأفضل أن تمضي ببطء، واترك للزمن أن يسبقك."},
  "9,1":{"third":9,"text":"اليوم تبدو كل الأمور صعبة. هناك خسائر مادية، وتقدّم الأمور مُعاق في كل جانب. الزوجة الحامل أو التوقّعات في البيت ما زالت قائمة، لكن التعب من السفر يشعر بالإرهاق ويفقدك القدرة على المُضي قُدماً. ما تحتاجه الآن ليس الثبات بالقوة، بل أن تُبطئ وتمنح نفسك قسطًا من الراحة."},
  "9,9":{"third":1,"text":"في الهواء اليوم يسود شعور بـ“التفكك” — السفر معرقل، الحركة بطيئة، وقد تنشأ شقوق بين الأصدقاء والزوجين. الثقة في الشراكات تتراجع، كما لو أن النظام القديم يتحرك بهدوء. لا حاجة للإسراع في التمركز، راقب اتجاه الريح أولاً."},
  "9,7":{"third":0,"text":"رحلة اليوم لم تسر بسلاسة، والمزاج سهل الانزلاق نحو الأسفل. الخسائر المادية وفكرة الانتقال تتشابكان معًا، وفراق الأطفال أو سفر الأصدقاء يجعل القلب مضطربًا. لكن للحزن فصله الخاص، والطريق لا يزال تحت الأقدام."},
  "9,0":{"third":7,"text":"اليوم معرض للوم والتشويه بسهولة، والخسائر المادية وهروب ذوي المناصب المنخفضة تسببان خيبة أمل. معاناة المرضى وخطر المفقودين تحوم في العقل كالظل. المفتاح اليوم هو \"الثبات\"، لا تدع أصوات الخارج تُضلّك."},
  "9,8":{"third":2,"text":"فرح اليوم ينبع من \"الاستقرار\" — الانسجام في التعامل مع الكبار، وتزداد الثروة والمعرفة، والحياة مُيسّرة ومريحة. إخلاص الخدم أو المرؤوسين يجعلك تشعر بالاطمئنان. اليوم مناسب للعمل بهدوء دون الحاجة لملاحقة مناظر بعيدة."},
  "9,2":{"third":8,"text":"اليوم مناسب للجلوس مع الأصدقاء؛ الدردشة أو التخطيط لعمل مشترك يقربك من تحقيق رغباتك. عندما تجد مكانًا للمحبة والرغبة، حتى الأشخاص الذين بدوتهم متواضعة سيجلبون لك منفعة. اليوم ستكون مرئيًا ومحترمًا."},
  "9,14":{"third":4,"text":"لون اليوم باهت بعض الشيء — الحزن يلتف، العمل متوقف، ومن السهل أن تنشأ عدائية بين الزوجين أو الشركاء. الخسائر المادية وخيانات ذوي المرتبة الأدنى تُشعرك بالإرهاق. لكن تذكّر أن بعض العلاقات تحتاج أن تتصدع أولاً لتصبح أكثر صدقاً."},
  "9,4":{"third":14,"text":"اليوم غير مناسب للسفر؛ قد تتعرض وسائل النقل أو الأمتعة لمشكلات. يبدو أن الخلافات والعداء لا مفر منهما، وقد يتأثر سمعتك أيضًا. ستشعر بالخوف عند مواجهتك لكبار السن أو أصحاب السلطة، لكن لا يجب أن تتحمّل كل الضغوط بمفردك."},
  "9,11":{"third":13,"text":"اليوم يوم للتقدّم. الأمور تتقدم بسلاسة، واحترام من المسؤولين أو الكبار يمنحك الاطمئنان. الثروة والمكانة تتراكم، والرغبات والآمال تبدأ في التحقيق. اليوم مناسب لـ\"استقبال\" هذه النوايا الحسنة."},
  "9,13":{"third":11,"text":"أحداث جيدة اليوم تأتي من حولك. رعاية كبار السن أو الأشخاص ذوي المكانة المرموقة تجعلك تشعر بالدعم، ورغباتك وأهدافك تقترب. حالة المريض تتحسن، والسعادة والبهجة محسوستان بوضوح. اليوم يستحق أن تقضيه مع الذين يهتمون بك."},
  "9,15":{"third":12,"text":"سلامة اليوم ملموسة. اقتناء وسيلة النقل تم بسلاسة، هدوء المرأة ووفاء الخادم يبثان الطمأنينة، شفاء المريض وإطلاق سراح المسجون أيضاً أمامنا. اليوم هو يوم مناسب \"للفكّ\"."},
  "9,12":{"third":15,"text":"أينما تجمّع الناس اليوم، قد تختبئ الأمور الطيبة. شراء وسائل النقل يسير بسلاسة، والفرح والسعادة حاضران أيضًا. تتقدّم الأمور بسلاسة، والنهاية مُرضية، والأشخاص المفقودون عائدون. اليوم مناسب لـ“الاجتماع” ومناسب لـ“الإنجاز”。"},
  "9,3":{"third":5,"text":"يبدو أن الثروة والحزن قد جاءا اليوم معًا. الخلافات والشجارات بين الزوجين تُشعِر بالتعب، والرحلات لا تسير بسلاسة. لكن تذكّر أن اكتساب الثروة قد يصحبه ثمن أحيانًا، وقد يكون الألم الداخلي هو الوجه الآخر للنمو."},
  "9,5":{"third":3,"text":"جسدك وروحك على ما يرام اليوم، ووجود صديقات أو قريبات من النساء يبعث فيك الطمأنينة. لكن الخسائر المالية وظلال المرض ما زالت قائمة، وخيانة الأشخاص ذوي المكانة المنخفضة تثير القلق. عليك اليوم أن تتعلم كيف تحمي نفسك في هدوء."},
  "9,6":{"third":10,"text":"اليوم غير مناسب للسفر، وقد تُعيقك المقاومة عند التحرك. قد لا تجد الرغبة في الزواج أو المشاعر تجاوبًا، ومرض الزوجة يثير القلق. لكن ثق أن العوائق ليست دائمة، فالرياح ستتحول."},
  "9,10":{"third":6,"text":"اليوم شهد بعض العقبات، لكن النتيجة جيدة. السعادة والفرح تظهران بعد الصراع، ودفء الزواج وحديث كبار السن يبعثان فيك الراحة. الخوف والقلق في تراجع، والعمل سينتهي بسلاسة. اليوم هو النور الذي يُرى \"بعد التحمل\"."},
  "3,1":{"third":1,"text":"من المرجح أن تشعر بعدم الارتياح بين الحشود اليوم. الإنفاق المالي، والقلق الداخلي، وتدخلات الأشخاص ذوي المكانة المنخفضة تثقل كاهلك. تصرفات النساء والأشخاص الأقل مكانة قد لا تكون على مستوى التوقعات، والحياة تبدو فوضوية بعض الشيء. لا تحاول حل كل المشكلات اليوم؛ ثبت أقدامك أولاً."},
  "3,3":{"third":1,"text":"قد لا تسير الرحلات والتحركات اليوم بسلاسة، وقد تشعر بالإرهاق أثناء السفر. قد يتركك فراق امرأة أو خادمة، أو مشاكل في الزواج، بشعور بالفراغ. لكن تذكّر أن الوحدة أفضل من الاستنزاف في علاقة خاطئة."},
  "3,7":{"third":7,"text":"يبدو أن وضع اليوم ثقيل بعض الشيء. الخسائر الاقتصادية، معاناة النساء، وتعطل الأمور كلها تثير شعورًا بالكآبة. لا يمكن تحريك أي من الأمور التي نريد دفعها قدمًا، لكن أحيانًا \"التوقف\" بحد ذاته يكون حكمة."},
  "3,14":{"third":4,"text":"ترتكز اليوم الأمور على «الفقدان» و«المغادرة». قلق الزوجة وهروب ذوي المناصب المنخفضة، ووضع المحتجزين الصعب، كل ذلك يثقل القلب. السفر قد يواجه عقبات، والزواج يبدو بارداً، والحوامل أو المرضى بحاجة إلى عناية إضافية. ليست هذه أخطاء منك، بل مجرد مرحلة تتطلب الصبر."},
  "3,9":{"third":5,"text":"أمور التجارة أو السفر اليوم ستحرز تقدماً، والأمنية تقترب. الأشخاص المفقودون سيعودون بمساعدة المقربين، وستسير مفاوضات مالية وشراء الملابس وغيرها من الأمور بسلاسة. اليوم هو يوم \"التحرك\"."},
  "3,5":{"third":9,"text":"الجسدية والحالة النفسية اليوم على ما يرام إلى حد ما، لكن الخسائر المالية وحالة المريض لا تزال مقلقة. قد يجلب الحديث مع امرأة أو خادمة بعض العزاء، لكنك تعلم في قرارة نفسك أن بعض الأمور لا يمكن حلها فورًا."},
  "3,0":{"third":13,"text":"رحلتك اليوم تتطلب أن تكون مستعدًا. السفر سيكون سلسًا، لكن النفقات قد تتجاوز التوقعات. الأشخاص ذوو المكانة المنخفضة قد يظهرون علامات رغبة في الهروب، وقد يظهر الخيانة من المحيط القريب. اليوم تحتاج إلى \"أن ترى بوضوح قبل أن تمضي\"."},
  "3,4":{"third":14,"text":"اليوم ليس مناسبًا للسفر، ومن المتوقع تكبد خسائر مالية. الأشخاص الذين فقدتهم يمرون بوقت عصيب، والمرضى لم يتحسنوا بعد. البرود في الزواج يثير الإحباط، ويبدو أن الأشياء المفقودة من الصعب استرجاعها. لكن ثق أن بعض الخسائر تكون فقط تمهيدًا لقدوم ما هو أفضل."},
  "3,8":{"third":12,"text":"رحلة اليوم تحمل نور الأمل. النهاية سعيدة، وكل خطوة تبدو وكأنها تقف على بركة. الأمنيات في طريقها لتتحقق، وما كان يثير قلقك بدأ يزول تدريجيًا."},
  "3,12":{"third":8,"text":"تقدَّمت أمور اليوم بسلاسة، ومساعدة الخادم جعلت الحياة تبدو أكثر يسرًا. الآمال والرغبات تتشكل، وإتمام الحب والإنفاق على شخص جميل يجعلان اليوم يشعر بأنه \"مستحق\"."},
  "3,13":{"third":6,"text":"علاقات الزواج والنساء اليوم تبدو متناغمة، وتمضي الأمور بسلاسة، والتعامل مع الأشخاص ذوي المكانة المنخفضة سلس أيضًا. الأمنيات في طريقها للتحقق، واليوم يوم \"هادئ\" مناسب لذلك."},
  "3,6":{"third":11,"text":"اليوم يحتاج الأمر إلى مزيد من العناية بالحوامل أو الأمهات الجدد، لكن الرحلات لا بأس بها، ورغبة الزواج لا تزال تحوم في القلب. قد تشهد الحياة بعض التقلبات، لكن المسار العام يسير بسلاسة. من المستحسن اليوم الحفاظ على اللطف والصبر."},
  "3,11":{"third":9,"text":"رحلتك اليوم ستُحاط بالعناية من الأعلى، ومن المتوقع عودة الثروات والأشياء المفقودة. الأمور التي كانت تُقلقك بدأت تتحسّن واحدةً تلو الأخرى. اليوم يستحق التوقع."},
  "3,10":{"third":7,"text":"اليوم النساء وكبار السن جميعهم في أمان، وخبر حمل الزوجة وولادتها يبعث على الطمأنينة. كل شيء يبدو هادئًا ودافئًا. اليوم مناسب لقضاء الوقت مع العائلة، للشعور بتلك السعادة الصغيرة لكنها الحقيقية."},
  "3,2":{"third":3,"text":"اليوم يجري اللقاء مع امرأة أو شخص ذو مكانة مرموقة بدفء، والحب يبدو مُكتملًا. كل الأمور تتجه نحو الأفضل، اليوم هو يوم \"الاكتمال\"."},
  "3,15":{"third":2,"text":"اليوم يوم جميل. الأمور تسير بسلاسة، والثروة تقترب، والرحلات والتنقلات تسير بسهولة. إذا لاحظت بعض دلائل الفرح، فهذا دليل على اقتراب السعادة والهناء. اليوم كل ما عليك هو المشي بهدوء، وستأتي الأشياء الطيبة من تلقاء نفسها."},
  "10,1":{"third":10,"text":"اليوم مناسب للخروج إلى الحشود. الفرح والسعادة تتصاعد بين الناس، وتسير الأمور بسلاسة، والثروة تقترب. التآلف مع الأصدقاء، والمشاركة في حفلة زفاف أو احتفال، سيجعلان اليوم يشعر بالامتلاء والدفء."},
  "10,10":{"third":1,"text":"رحلة اليوم وتجارتهما تنفذان بسلاسة. مساعدو الخادم وتعايش أشباه العامة يبعثان على الشعور بأن الحياة مستقرة. قد تظهر مناقشات حول توزيع الوراثة أو الأمور العقارية، لكن إذا كان الجو أحمرًا قليلًا—فهذا مجرد خلاف في الرأي."},
  "10,7":{"third":2,"text":"اليوم تتكدس المناقشات التي قد تتسبب في خسائر مادية، وقلبي يعرف أن جزءاً فقط يمكن تعويضه. الحزن والقلق يلتفان حول العمل والعلاقة الزوجية، كما ظهرت تشققات بين الشركاء والأصدقاء. لكن من فضلك ثق بأن بعض الفقدان مُهيأ لدخول أشياء جديدة."},
  "10,2":{"third":7,"text":"اليوم يتركز الاهتمام على \"الفقدان\" و\"الخيانة\"。التكاليف الاقتصادية، مرض الأشخاص في القاع، والخيانة كلها تتركك في تعب. المناقشات المتعلقة بالممتلكات أو الأمور مستمرة بلا توقف، والعمل يتعثر أيضًا. اليوم من الأفضل عدم السعي لحل جميع المشاكل فورًا، اعتنِ بقلبك أولاً."},
  "10,8":{"third":0,"text":"اليوم هو يوم جميل. السعادة والبهجة في المتناول، تتقدم الأمور بسلاسة، ورغبتك في الزواج وشراء الأشياء تسير بخير. الثروة تتراكم، وأولئك الذين فُقدوا في طريقهم يعودون. فقط السفر قد يترتب عليه بعض الخسائر—هذه هي الثمن الذي تريد دفعه."},
  "10,0":{"third":8,"text":"رحلته وإجراءاته اليوم سارت بسلاسة، التجارة مزدهرة، لكن النفقات كثيرة. يجب الانتباه إلى حالة المرضى، قد لا تكون أمور الزواج كما تتوقعون، والشراكة مع الشركاء قد تكون هشة بعض الشيء. الثروة عرضة للسرقة، قد تكون هناك إشارات هروب لأشخاص في موقع منخفض. اليوم يُنصح بـ“حفظ ممتلكاتك”."},
  "10,4":{"third":12,"text":"أفعال اليوم ورحلتك تفيض بروح \"اندفاع\"، قد تظهر مشاجرات وعداء،لكن أمور الزواج والشراء تسير بسلاسة بشكل مفاجئ. يتواجد التناقض والنجاح غالبًا معًا، المفتاح هو أي جانب تختار رؤيته."},
  "10,12":{"third":4,"text":"الصحة الجسدية والعقلية اليوم، تتحقق الأمنيات، وعودة الحبيبين وتعاون الزواج يسيران بسلاسة. ولكن إذا ظهرت اليوم صراعات أو جدالات، فربما تكون مجرد تقلبات في الحظ المالي، فلا داعي للقلق."},
  "10,13":{"third":5,"text":"اليوم، الثروة والسفر يسيران بسلاسة، حالة الرحلة جيدة. احترام وتقدير كبار السن والأصدقاء يمنحانك الإحساس بالثقة. شراء وسائل النقل ناجح، والأماني في طريقها للتحقق. اليوم هو يوم \"المعاملَة الحسنة\"."},
  "10,5":{"third":13,"text":"اليوم الثروة وفيرة، والحياة ميسورة. الزواج والشراكة يسيران بسلاسة، والرحلة مليئة بالبركات. يتم تعويض الخسارة، وتبدو الأيام أكثر استقرارًا. اليوم من المستحب الاستمتاع حقًا بهذه \"الكمالات\"."},
  "10,3":{"third":11,"text":"اليوم من السهل الشعور بالحزن والقلق. الخسارة الاقتصادية، خيانة واستعباد من هم في القاع، ركود العمل يثقل كاهلنا. الخوف من كبار السن يضغط على القلب أيضًا. لكن تذكر، غالبًا ما تكون أصعب الأيام هي اللحظة التي ينمو فيها الشخص حقًا."},
  "10,11":{"third":3,"text":"تُراعى الرحلة والإجراءات اليوم من قبل الرؤساء أو المسؤولين، والشراء أو إضافة ملابس يسير بسلاسة. لكن حالة المريض ما زالت تحتاج إلى متابعة، ولم يَرْتَقِ التحسن واضحًا. تتشابك الفوائد والمخاوف التي يجلبها الكبار في السن. اليوم مناسب للمضي بثبات."},
  "10,6":{"third":9,"text":"الوضع اليوم ثقيل بعض الشيء. حالة الأشخاص المفقودين غير جيدة، والعمل مُعوق، حالة المرضى تثير القلق أيضًا. الخسائر الاقتصادية، وهروب الأشخاص في القاع، وسوء الحظ في الزواج كلها تُشعر الإنسان بالإرهاق. اليوم من الأفضل أن نكون \"ساكنين\"، لا \"نتحرك\"."},
  "10,9":{"third":6,"text":"أفعال اليوم وثراؤه يتقدمون، الرحلة تسير بسلاسة، لكن قد توجد جدالات ونزاعات. شراء مستلزمات الحياة يسير، لكن الاختلافات بين الزوجين والشركاء موجودة كتيار خفي. بناء منزل أو شراء عقار يسير بشكل أكثر سلاسة. يومنا هذا يوجد فيه \"الطيب\" و\"السيئ\" معًا، الاختيار لأي جانب يعود لك."},
  "10,15":{"third":14,"text":"الوضع اليوم يجعل الناس يشعرون بالقلق. الخسائر الاقتصادية وخطر المفقودين يلاحقاننا كظل، والرحلة ليست سهلة، وقد تقع حوادث مفاجئة. البرد في الزواج والحب يجعلنا نشعر بخيبة أمل أيضًا. لكن تذكر أن بعض \"الفقدان\" هو أن المصير يعيد ترتيب النظام."},
  "10,14":{"third":15,"text":"اليوم قد تظهر الحزن والغضب معًا. حالة المريض خطيرة، والندم والجدال يملآن الأيام. قد تجعلك الصدامات مع السلطة تشعر بالإرهاق، لكن الخسارة ليست بلا فائدة بالكامل — فجزء منها يُعَوَّض على الأقل. درس اليوم هو: أن تجد مركزك في الفوضى."},
  "2,1":{"third":2,"text":"اليوم من المناسب إضافة أشياء كبيرة—سواء كانت مركبات أو حيوانات أُخرى يمكن أن تتم بنجاح. في الاجتماعات والتجمعات توجد فرص وفرح، الناس العائدون في الطريق، ومساعدة الخدم أو التابعين ستجعل الأمور أخف وزناً. إذا كانت هناك فرصة للدخول في المياه، فربما تكون هناك رحلة جيدة."},
  "2,2":{"third":1,"text":"اليوم يحظى بشعبية كبيرة يجتمع الرجال والنساء والشباب وكبار السن في مكان واحد. الزواج أو التجمعات المزدحمة هي موضوع اليوم، لكنها كذلك سريعة لإثارة نقاش بسبب الأمور المالية والميراث. إذا كان هناك خلاف بين الأصدقاء والشركاء، فذلك أيضاً نتيجة “الاقتراب الشديد” وخلق الاحتكاك. في الأجواء المزدحمة، الحفاظ على مسافة بسيطة هو الأفضل في الواقع."},
  "2,15":{"third":2,"text":"الاجتماع اليوم مع الأصدقاء ومع الأقل مكانة في قاعة واحدة، حالة المريض تبدو أسوأ قليلًا، لكن شراء المجوهرات أو الأقمشة يجعل الناس سعداء. مساعدة الخادم تعوض الخسارة. على الرغم من أن الرحلة لم تكن سلسة جدًا، إلا أن اللطف من حولنا يكفي ليمنح دفئًا لليوم."},
  "2,3":{"third":15,"text":"اليوم هو يوم \"المصالحة\". تتدفق السعادة والفرح في العلاقات، ويتلاشى الحاجز بين الأصدقاء، وشفاء المريض وإطلاق سراح المحتجزين يبعثان على راحة البال. تتقدم الشراكة بسلاسة، وتتجه الأمور نحو اتجاهات إيجابية. اليوم هو يوم جيد لإصلاح العلاقات."},
  "2,10":{"third":3,"text":"اليوم تحرز الشراكة والزواج تقدمًا، ومع أنباء من بعيد أو من الحبيب ستجلب دفئًا. الأحبة المفقودون في طريقهم إلى العودة، ويتم تعويض الخسائر. الأمور التي تشغلك وتقلقك تَهدأ تدريجيًا واحدة تلو الأخرى."},
  "2,7":{"third":8,"text":"القلق اليوم يأتي أساساً من كبار السن، أو القلق المرتبط بهم يجعلك مشتتاً قليلاً. لكن الشخص الذي فقدته يعود، والخلافات أيضاً في طريقها إلى الهدوء. حالة الطفل أو عدم الرضا في الزواج كلها مؤقتة، والجو العام اليوم في الواقع ليس سيئاً."},
  "2,8":{"third":7,"text":"أعمال اليوم وشؤونه كلها تنبئ بدفعة إلى الأمام. المكانة والثروة في ارتفاع، شفاء المرضى وعودة أهل السلام تجعل المرء يشعر بالطمأنينة. الدفء في الزواج يتدفق أيضاً، اليوم هو يوم جيد لـ “المضي قدماً”."},
  "2,9":{"third":4,"text":"رحلة اليوم والتجارة تتقدم، وشراء السيارات أو وسائل النقل يسير بنجاح. أثناء تقدم الأعمال يصاحبها النجاح والفرح، والذين فقدوا يعودون إلى الطريق. ما جلبته اليوم هو مزيج من \"الانسجام\" و\"الاستقرار\"."},
  "2,4":{"third":9,"text":"رحلة اليوم وتجارتها كلها تنبئ بانسياب الأمور. القادمون بالأخبار الطيبة، تتقدم المعاملات بسلاسة، والنتيجة مرضية أيضًا. الدفء في الزواج واكتمال الحب يتشابكون معًا، اليوم يوم ثمين يجب تقديره."},
  "2,13":{"third":0,"text":"قد تكون هناك خسائر اقتصادية اليوم، وربما تظهر علامات مغادرة الأشخاص ذوي الدخل المحدود. لكن من الممكن استعادة الملابس أو المجوهرات المفقودة، وستعيدك أخبار من أصدقاء دفئاً إلى قلبك أيضاً. اليوم تتشابك فكرة “الضياع” و“الربح” معاً، فلا داعي للانشغال بالمبالغة في الحساب."},
  "2,0":{"third":13,"text":"رحلتنا وائتلافنا اليومان سلسان، وتتقدم الأعمال بنغمة تشعرك بأن كل شيء \"على حق\". الحب مكتمل، والأصدقاء يجتمعون، وحتى الأعداء يتراجعون. اليوم هو يوم \"السير في الطريق الصحيح\"."},
  "2,6":{"third":14,"text":"رحلة اليوم والزواج يسيران بسلاسة نسبياً، العلاقة الشريكة جيدة، الخير والجمال يحيطان بك. العدو يتراجع، حالة المريض تتحسن. اليوم من المناسب أن تتعامل بلطف مع الناس، ستأتي الأعمال الطيبة إليك دون أن تلاحظ."},
  "2,14":{"third":6,"text":"رحلة اليوم ليست سلسة للغاية، فالمسائل المتعلقة بالأطفال أو الأشخاص ذوي المكانة البارزة غالباً ما تجلب الألم والحزن. الحوادث المرورية أو النفقات الاقتصادية تترك الإنسان متعباً. قد تفقد الملابس أيضاً. لكن تذكر أن بعض أيام الصعوبة تهدف إلى جعلك أكثر تقديراً لأوقات السلام."},
  "2,11":{"third":12,"text":"عملية شراء المركبة اليوم سارت بسلاسة، وبركة وتجربة الخبراء محاطة بك من حولك. الخسارة تُعوض، ومساعدة الآخرين ستعود عليك أنت أيضًا. شفاء المريض، النجاح، وكمال الحب، يجعل اليوم مفعمًا بالدفء اللطيف."},
  "2,12":{"third":11,"text":"الصحة الذهنية والجسدية اليوم تقترب الثروة أيضًا. العمل يسير، من خلال عوائد المركبات أو الحيوانات يشعر الإنسان بالطمأنينة. الحبيب المفقود في طريق العودة، وفوائد المرأة تجعل اليوم أكثر اكتمالاً. الاستقرار اليوم حقيقي."},
  "2,5":{"third":10,"text":"رحلة اليوم وأفعاله تحملان نفحة من \"السير الصحيح\". السعادة والفرح يرافقانهما، الزواج والشراكات تسير بسلاسة، والمعاملات أيضًا تسير بسلاسة. كل شيء يبدو جيدًا ومملوءًا بالبركة. اليوم هو يوم جيد تُظهر فيه \"كل شيء في الاتجاه الصحيح\"."},
  "0,1":{"third":0,"text":"اليوم مناسب للسير، والرحلة مع الفرقة ستعود آمنة. في الحشود قد تحدث تجمعات وتفريقات، وقد تكون هناك حفلات زفاف أو مراسم عزاء. إذا كان الجو متوتراً فاحرص على تفادي الصدامات اللفظية. أنت اليوم فقط اتبع الطريق، ستقودك الرياح إلى المكان الذي يجب أن تذهب إليه."},
  "0,0":{"third":1,"text":"اليوم هو يوم جيد للوصول إلى الطريق. سواء للسفر البعيد أو للتنقل اليومي، يتسم ذلك بسلسلة من الانسيابية. شراء المركبات والماشية يسير بسلاسة، والحب يقترب، والراحلون في طريق العودة. تسير الأمور بسلاسة، وكل خطوة اليوم واقفة على عقدة/عند نقطة."},
  "0,8":{"third":10,"text":"اليوم هو يوم \"الصعود\". المكانة والمجد يقتربان، والرغبات في طريقها للتحقق. الصحة الجسدية والعقلية في تحسن، والأشخاص المفقودون في طريق العودة. النجاح والثروة في انتظارك أمامك، فقط واصل التقدم للأمام."},
  "0,10":{"third":8,"text":"رحلة اليوم وعودتك هادئتان، المسافرون بأمان، ثروة المرأة وصفها وعملياتها تسير بسلاسة. لا يوجد الكثير من الخيارات والتردد، الطريق مُمهّدة، ما عليك سوى أن تمضي بثبات حتى النهاية."},
  "0,7":{"third":9,"text":"اليوم قد تشعر بالحزن بسهولة وبوجود عائق. يتعذر تقدم الأعمال وتبدو الأهداف بعيدة. الإحساس بالانفصال عن الأصدقاء أو الزوجة أو الأطفال يجعل الأمر مرهقًا، وقد تظهر علامات المغادرة على الأقل من جانب ضعيف. لكن تذكر أن نهاية الطريق ليست بالضرورة كما تتخيلها؛ قد تكون نقطة انعطاف."},
  "0,9":{"third":7,"text":"الجدال اليوم والعداء يبدوان لا مفر منهما، فالتكاليف الاقتصادية وظروف المفقودين السيئة يثيران القلق. الرحلة غير موفَّقة، واحتمالية وقوع حوادث مفاجئة تقطع النفس. صورة السجن والتقييد، سواء كانت مادية أو معنوية. اليوم لا يجوز المخاطرة، الأفضل الحفاظ على الحذر لا الهجوم."},
  "0,14":{"third":5,"text":"رحلتنا اليوم وأنشطتنا مجدية، تقدم الأمور بسلاسة، وتبدو العلاقات مع كبار السن والشركاء وديّة. لكن إذا كان اليوم يجلب نذير سوء، فاحرص على مخاطر المرض — النتيجة قد لا تكون كما تبدو في الظاهر. اتخذ لنفسك يقيناً، ولا داعي للقلق المفرط."},
  "0,5":{"third":14,"text":"اليوم يوم مليء بالفرح. تسير الأمور بسلاسة، جميع الأمور تتجه نحو الأفضل، الأشخاص الذين فقدوا يعودون. خبر حمل زوجتي وإنجاب طفل يجعل الناس يتطلعون إلى المستقبل. الخير اليوم حقيقي وواقع."},
  "0,11":{"third":12,"text":"رحلة اليوم وإجراءاته تحت رعاية أعلىParty أو القائد، فالتقدم في الثروة والشؤون ضمن المتوقع. يتم تعويض الخسائر، وولاء العبد يجلب إليك شعوراً بالاعتماد. الشخص المفقود في طريقه للعودة، وحالة المريض في تحسن. اليوم \"المثل\" هو تجمع من عدة أطراف."},
  "0,12":{"third":11,"text":"اليوم هو يوم \"العودة\" و\"الإتمام\". عودة المسافر بسلام، والبركة والمتعة تحيطان بك من كبار السن. صحة الجسم والعقل، والأمنيات في طريقها للتحقق، يبدو الحب والزواج مكتملين. اليوم مناسب لإتمام الأمور والاحتفال."},
  "0,4":{"third":3,"text":"في رغبات اليوم يراودها قليل من القلق. نداء الزواج أو العاطفة يرن في القلب، لكن الجسد ضعيف قليلًا، وقد تتبلور جدالات وعداء. من الناحية الاقتصادية قد يكون هناك استنزاف، وربما يظهر من في موقف منخفض مؤشرات الهروب. رحلة اليوم تبدو صعبة أيضًا — لكن كل خطوة للأمام تكون بمثابة تأكيد للاتجاه نحو الذات."},
  "0,3":{"third":4,"text":"ثروة اليوم قريبة، لكن بعض جوانب العمل تُشعِرك بعدم الرضا. تلك الأمور غير اللائقة — سواء كانت تشير إلى الشرب أو القمار أو الرغبات السرية — تتأرجح على الهامش. من المتوقع أن تُسترد المسروقات، كما أن الإيمان المفقود يعاود النهوض. في تعقيدات اليوم تختبئ أدلة على نوع من العودة."},
  "0,15":{"third":13,"text":"رحلتك وحالتك اليوم جيدة، السعادة والفرح يحيطانك. تتحقق الأمنيات، يعود الحبلى بسلام، ويحظى بالاحترام والمحبة من النساء. لكن الصعوبات أثناء السفر والأشياء المفقودة التي يصعب العثور عليها هي أيضًا ألم اليوم الخفي. المصالح والندم غالبًا ما يسيران جنبًا إلى جنب."},
  "0,13":{"third":15,"text":"الوضع اليوم جيد، سعادةك تأتي من راحة الصديقات الأنثى والعائلة والتقاء الحبيب. الثروة في الطريق، والشيء المفقود من الممكن استرجاعه. لكن حال المريض ما زالت بحاجة إلى متابعة. اليوم الجيد هو الدفء واليقظة."},
  "0,6":{"third":2,"text":"محور اليوم يتركز على الحوامل والمرضى. مساعدة الخادمين سمحت للأمور أن تتقدم، قد يكون هناك تقدم جديد في الرحلة البحرية. لكن الصور النمطية عن الحبس والتقييد، سواء كانت حرفية أو تعبيرًا نفسيًا، تشير إلى شعور بالضيق. العمل يواجه عائقًا، والظروف ليست مواتية—لكن صدقوا بأن الضيق نفسه هو مقدمة لكسر الجمود."},
  "0,2":{"third":6,"text":"اليوم يتسم بالتعايش الودي مع النساء، والسعادة والفرح يحيطانك. الشراكة ناجحة، وفي الزواج دفءٌ وحميمية. ما فُقد من شيء يأمل في الاسترجاع، لكن الجدال على الميراث أو الرحلة المزعجة تذكّرك بأن الخير يضم في طيّاته ما يتطلب الصبر. درس اليوم: أن تبقى يقظاً وسط الفرح."},
};
