{id:1,letters:"\u0627 \u0627 \u0627",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0633\u0645\u0649 \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u0644\u0642\u062f \u0645\u0646\u062d\u062a\u064f\u0647 \u062b\u0631\u0648\u0629\u064b \u0648\u0641\u064a\u0631\u0629 \u0648\u0630\u0631\u064a\u0629\u064b \u0645\u062a\u0648\u0627\u0635\u0644\u0629\u060c \u0648\u0641\u062a\u062d\u062a\u064f \u0644\u0647 \u0637\u0631\u064a\u0642\u064b\u0627 \u0645\u0645\u0647\u0651\u062f\u064b\u0627 \u0644\u0644\u0645\u0633\u062a\u0642\u0628\u0644.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u062a\u0641\u0633\u0631\u060c \u0644\u0645\u0627 \u062a\u0633\u0623\u0644 \u0639\u0646\u0647 \u0623\u0628\u0634\u0631\u0643 \u0628\u0641\u0631\u062d \u0645\u0628\u0634\u0631: \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0639\u0627\u0645 \u0633\u062a\u062d\u0635\u0644 \u0639\u0644\u0649 \u0631\u0632\u0642 \u0648\u0641\u064a\u0631 \u0648\u0638\u0631\u0648\u0641 \u0645\u0648\u0627\u062a\u064a\u0629\u060c \u0648\u0628\u0645\u0634\u064a\u0626\u0629 \u0627\u0644\u0639\u0644\u064a \u0633\u062a\u062a\u062d\u0642\u0642 \u0644\u0643 \u0643\u0644 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u062a\u064a \u062a\u0631\u062c\u0648\u0647\u0627."},
{id:2,letters:"\u0627 \u0627 \u0628",fortune:"\u0634\u0631\u064a\u0631",text:"\u0627\u0644\u0623\u0639\u0644\u0649 \u0627\u0644\u0633\u064a\u062f \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u062d\u0630\u0631\u0647\u0645\u060c \u0648\u0644\u064a\u0643\u0634\u0641 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0639\u0628\u062b\u0647\u0645!\n\n\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u062c\u062a\u0647\u062f \u0641\u064a \u0627\u0644\u062a\u062d\u0641\u0651\u0638 \u0639\u0645\u0651\u0627 \u062a\u0631\u062c\u0648\u0647\u060c \u0648\u0627\u0628\u062a\u0639\u062f \u0639\u0646\u0647 \u0642\u062f\u0631 \u0627\u0633\u062a\u0637\u0627\u0639\u062a\u0643\u060c \u0644\u0623\u0646\u0651\u0647 \u0644\u0627 \u064a\u0646\u0641\u0639\u0643\u060c \u0628\u0644 \u064a\u062c\u0631\u0651 \u0639\u0644\u064a\u0643 \u0636\u0631\u0631\u0627\u064b\u060c \u0648\u0641\u064a \u0627\u0644\u0646\u0647\u0627\u064a\u0629 \u064a\u062b\u0645\u0631 \u0646\u062f\u0645\u064b\u0627. \u0623\u0631\u0649 \u062d\u0648\u0644\u0643 \u0623\u0639\u062f\u0627\u0621\u064b \u0648\u0645\u062a\u0631\u0641\u0651\u0647\u064a\u0646 \u064a\u0633\u0639\u0648\u0646 \u0644\u0644\u062a\u0642\u0631\u0651\u0628 \u0645\u0646\u0643 \u0648\u062a\u0646\u0641\u064a\u0630 \u0645\u0643\u0627\u0626\u062f\u060c \u0641\u0627\u062d\u0630\u0631\u060c \u0641\u0647\u0645 \u0623\u0639\u062f\u0627\u0621 \u062d\u0642\u064b\u0627."},
{id:3,letters:"\u0627 \u0627 \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u0625\u0646\u0647\u0645 \u064a\u0628\u062a\u0647\u062c\u0648\u0646 \u0628\u0627\u0644\u0646\u0639\u0645 \u0627\u0644\u062a\u064a \u0648\u0647\u0628\u0647\u0627 \u0627\u0644\u0642\u062f\u0631 \u0644\u0647\u0645\u060c \u0648\u064a\u064f\u0628\u0634\u0631\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u0645\u0627 \u0632\u0627\u0644\u0648\u0627 \u0641\u064a \u0627\u0644\u062e\u0644\u0641\u061b \u0641\u0647\u0645 \u0644\u0627 \u062e\u0648\u0641 \u0639\u0644\u064a\u0647\u0645 \u0648\u0644\u0627 \u0647\u0645 \u064a\u062d\u0632\u0646\u0648\u0646.\n\n\u0623\u064a\u062a\u0647\u0627 \u0627\u0644\u0628\u0627\u062d\u062b\u0629/\u0623\u064a\u062a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u0629\u060c \u0623\u0628\u0634\u0631\u0643: \u0627\u0644\u0641\u0631\u062d \u0627\u0644\u0642\u0631\u064a\u0628 \u0622\u062a\u064d\u060c \u0648\u0641\u0631\u0635 \u0627\u0644\u0648\u0641\u0631\u0629 \u0633\u062a\u0631\u0627\u0641\u0642\u0643. \u0627\u0630\u0647\u0628\u064a \u0644\u062a\u062d\u0642\u0642\u064a \u0645\u0627 \u062a\u0634\u062a\u0647\u064a\u0646\u060c \u0648\u0625\u0630\u0627 \u0623\u0631\u0627\u062f \u0627\u0644\u0639\u0644\u064a\u0651 \u0630\u0644\u0643 \u0641\u0644\u0646 \u062a\u062d\u062a\u0627\u062c\u064a \u0625\u0644\u0649 \u062c\u0647\u062f \u0644\u062a\u062d\u0635\u0644\u064a\u0647. \u0627\u0644\u0623\u0645\u0646\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u062e\u062a\u0628\u0626 \u0641\u064a \u0642\u0644\u0628\u0643 \u0648\u062a\u0644\u0643 \u0627\u0644\u062a\u064a \u0644\u0645 \u062a\u0628\u0631\u0632 \u0628\u0639\u062f \u0633\u062a\u062a\u062d\u0642\u0642 \u0641\u064a \u0637\u064a\u0641 \u0645\u0646 \u0627\u0644\u0641\u0631\u062d \u0648\u0627\u0644\u0645\u062c\u062f \u0648\u0627\u0644\u0627\u0631\u062a\u064a\u0627\u062d."},
{id:4,letters:"\u0627 \u0627 \u062f",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0623\u0639\u0644\u0649 \u0627\u0644\u0633\u064a\u062f \u0647\u0648 \u0627\u0644\u0625\u0638\u0647\u0627\u0631: \u0623\u0646\u062a \u062a\u0642\u0648\u0644: \u0625\u0646\u0646\u0627 \u0627\u0644\u0622\u0646 \u0646\u0648\u0627\u062c\u0647 \u0641\u0642\u0637 \u0627\u0644\u0623\u0642\u062f\u0627\u0631 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0628\u0645\u0631\u0633\u0648\u0645 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0641\u0647\u0648 \u0645\u0639\u064a\u0646\u0646\u0627 \u0648\u062d\u0627\u0645\u064a\u0646\u0627.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0623\u0628\u0634\u0631\u0643: \u062a\u0648\u0643\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u0644\u064a\u060c \u0648\u0627\u0635\u0628\u0631 \u0642\u0644\u064a\u0644\u0627\u064b \u0641\u064a \u0645\u0627 \u062a\u0631\u062c\u0648\u0647\u060c \u0648\u0627\u0637\u0644\u0628 \u0639\u0648\u0646\u0647. \u0644\u0627 \u062a\u064e\u063a\u0652\u0636\u064e\u0628\u0652\u060c \u0641\u0627\u0635\u0628\u0631 \u0648\u0627\u0646\u062a\u0638\u0631 \u0623\u0646 \u064a\u0641\u062a\u062d \u0627\u0644\u0644\u0647 \u0644\u0643 \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u062e\u064a\u0631."},
{id:5,letters:"\u0627 \u0628 \u0627",fortune:"\u0634\u0631\u064a\u0631",text:"\u0627\u0644\u0633\u064a\u0651\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0645\u0638\u0647\u0631: \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u064a\u062d\u0630\u0651\u0631\u0643\u0645 \u0623\u0646 \u062a\u062d\u0627\u0641\u0638\u0648\u0627 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0643\u0645\u060c \u0648\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u062d\u0642\u0627\u064b \u0645\u062d\u0628 \u0644\u0644\u0646\u0627\u0633 \u062c\u0645\u064a\u0639\u0627\u064b.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0648\u0642\u062f \u0638\u0646\u0646\u062a\u064e\u0647 \u0642\u0631\u064a\u0628\u064b\u0627 \u062c\u062f\u064b\u0627\u060c \u0625\u0644\u0627 \u0623\u0646\u0647 \u0641\u064a \u0627\u0644\u0648\u0627\u0642\u0639 \u0628\u0639\u064a\u062f \u0643\u0623\u0642\u0637\u0627\u0631 \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a. \u0644\u0630\u0627 \u0644\u0627 \u062a\u0637\u0644\u0628\u0647 \u0623\u0628\u062f\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0623\u0628\u062f\u060c \u0648\u0627\u0628\u0652\u062a\u064e\u0639\u0650\u062f\u0652 \u0639\u0646\u0647 \u0628\u0639\u064a\u062f\u064b\u0627\u060c \u0644\u0623\u0646 \u0646\u0641\u0639\u0647 \u0636\u0626\u064a\u0644 \u0648\u0636\u0631\u0631\u0647 \u0639\u0638\u064a\u0645. \u0644\u0627 \u062a\u064f\u062c\u0647\u0650\u062f\u0652 \u0646\u0641\u0633\u0643 \u0645\u0646 \u0623\u062c\u0644\u0647\u060c \u0648\u0627\u0628\u062d\u062b \u0639\u0646 \u0633\u0628\u064a\u0644 \u0622\u062e\u0631\u060c \u0641\u0633\u062a\u0646\u0627\u0644 \u062b\u0645\u0631\u0629 \u0623\u0641\u0636\u0644."},
{id:6,letters:"\u0627 \u062c \u0627",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u0648\u0645\u0646 \u0622\u064a\u0627\u062a\u0647 \u0623\u0646\u0647 \u064a\u0631\u0633\u0644 \u0627\u0644\u0631\u064a\u062d \u0645\u0628\u0634\u0651\u0631\u0629\u064b \u0628\u0627\u0644\u062e\u064a\u0631\u060c \u0643\u064a \u062a\u062a\u0630\u0648\u0642\u0648\u0627 \u0646\u0639\u0645\u062a\u0647.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0623\u0628\u0634\u0631\u0643: \u0627\u0644\u0639\u0644\u064a \u0633\u064a\u0641\u0643\u0643 \u0627\u0644\u0645\u0635\u0627\u0626\u0628 \u0648\u0627\u0644\u0634\u0642\u0627\u0621 \u0627\u0644\u0630\u064a \u0646\u0632\u0644 \u0628\u0643. \u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0646\u0641\u0633\u0643 \u0633\u062a\u062d\u0635\u0644 \u0639\u0644\u064a\u0647\u060c \u0648\u0633\u062a\u0631\u0649 \u0641\u064a\u0647 \u0645\u0627 \u064a\u0633\u0631\u0643 \u0648\u064a\u0641\u0631\u062d \u0642\u0644\u0628\u0643. \u0627\u0644\u0641\u0631\u062c \u0642\u0631\u064a\u0628 \u062c\u062f\u064b\u0627\u060c \u0648\u0627\u0644\u0623\u062d\u0628\u0629 \u0627\u0644\u0628\u0639\u064a\u062f\u0648\u0646 \u0633\u064a\u0639\u0648\u062f\u0648\u0646 \u0642\u0631\u064a\u0628\u064b\u0627. \u0643\u0644 \u0645\u0627 \u0641\u064f\u0642\u062f \u0645\u0646 \u064a\u062f\u0643 \u0633\u064a\u0639\u0648\u062f \u0625\u0644\u064a\u0643 \u062f\u0648\u0646 \u0639\u0646\u0627\u0621."},
{id:7,letters:"\u0627 \u062f \u0627",fortune:"\u0634\u0631\u064a\u0631",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0648\u0636\u062d: \u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646! \u0627\u0644\u0633\u0643\u0631\u060c \u0627\u0644\u0645\u064a\u0633\u0631\u060c \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0623\u0635\u0646\u0627\u0645\u060c \u0637\u0644\u0628 \u0627\u0644\u0642\u0631\u0639\u0627\u0646\u060c \u0643\u0644\u0647\u0627 \u0623\u0641\u0639\u0627\u0644 \u0646\u062c\u0633\u0629\u060c \u0648\u0645\u0646\u0647\u062c \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646\u060c \u0641\u0627\u062c\u062a\u0646\u0628\u0648\u0627 \u0630\u0644\u0643.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u060c \u0627\u062a\u0631\u0643 \u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0648\u0644\u0627 \u062a\u062c\u0647\u062f \u0646\u0641\u0633\u0643 \u0641\u064a\u0647. \u0625\u0646 \u0633\u0623\u0644\u064e\u0643 \u063a\u064a\u0631\u0643 \u0639\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0641\u0644\u0627 \u062a\u0641\u0639\u0644 \u0644\u0647 \u0645\u0639\u0631\u0648\u0641\u064b\u0627\u060c \u0641\u0625\u0646 \u0630\u0644\u0643 \u0627\u0644\u0634\u062e\u0635 \u064a\u062e\u062f\u0639\u0643. \u0627\u0644\u0633\u0645\u0627\u0621 \u0633\u062a\u0639\u0648\u0636\u0643 \u0628\u062e\u064a\u0631 \u0623\u0628\u0644\u063a\u060c \u0641\u0644\u0627 \u062a\u0641\u0634\u0649 \u0633\u0631\u0643 \u0644\u0623\u062d\u062f\u060c \u0648\u062a\u064e\u062d\u064e\u0641\u0651\u064e\u0638\u0652 \u0623\u0643\u062b\u0631 \u0644\u062a\u062a\u062c\u0646\u0628 \u0627\u0644\u062e\u062f\u0627\u0639\u060c \u0641\u0625\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0639\u0644\u064a\u0645."},
{id:8,letters:"\u0627 \u0628 \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0633\u0645\u0649 \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u0647\u0645 \u0641\u064a\u0647\u0627 \u064a\u0623\u062a\u0648\u0646 \u0631\u0632\u0642\u0647\u0645 \u0635\u0628\u0627\u062d\u0627 \u0648\u0645\u0633\u0627\u0621\u064b.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0644\u063a\u0643 \u0628\u0634\u0631\u0649 \u0639\u0638\u064a\u0645\u0629 \u0648\u0631\u0632\u0642 \u0648\u0641\u064a\u0631: \u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0633\u064a\u0623\u062a\u064a\u0643 \u0644\u0627 \u0645\u062d\u0627\u0644\u0629 \u0628\u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0648\u062a\u0637\u0644\u0628\u0647. \u0623\u0633\u0631\u0639 \u0641\u064a \u0641\u0639\u0644 \u0645\u0627 \u062a\u0634\u0627\u0621\u060c \u0641\u0627\u062d\u0645\u062f \u0648\u0627\u0634\u0643\u0631 \u0627\u0644\u0639\u0644\u064a\u060c \u0641\u0625\u0646\u0647 \u0633\u064a\u0632\u064a\u062f\u0643 \u0645\u0646\u0647. \u0642\u062f \u0641\u062a\u062d \u0627\u0644\u0642\u062f\u0631 \u0644\u0643 \u0628\u0627\u0628 \u0627\u0644\u0633\u0639\u0627\u062f\u0629\u060c \u0648\u0627\u0644\u0641\u0631\u062c \u0642\u0631\u064a\u0628\u060c \u0641\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0639\u0627\u0644\u0645 \u062d\u0643\u064a\u0645."},
{id:9,letters:"\u0627 \u062c \u0628",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u0625\u0646\u0647\u0645 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0622\u062e\u0631\u064a\u0646\u060c \u0648\u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0645\u0633\u0627\u0639\u062f\u0629 \u0623\u0646\u0641\u0633\u0647\u0645.\n\n\u0648\u0623\u0645\u0627 \u0623\u0646\u062a \u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644 \u0641\u0625\u0646\u064a \u0623\u0631\u0627\u0643 \u0645\u062d\u0627\u0637\u064b\u0627 \u0628\u062c\u0645\u0627\u0639\u0629 \u064a\u0631\u063a\u0628\u0648\u0646 \u0641\u064a\u0627\u0644\u0627\u0635\u0637\u0641\u0627\u0641 \u0628\u0643 \u0638\u0627\u0647\u0631\u064a\u064b\u0627 \u0623\u0635\u062f\u0642\u0627\u0621 \u0648\u0642\u0644\u0648\u0628\u0647\u0645 \u0645\u062e\u0627\u062f\u0639\u0629. \u0644\u0642\u062f \u0642\u062f\u0651\u0631 \u0627\u0644\u0642\u062f\u0631 \u0623\u0646 \u064a\u0630\u0647\u0628\u0648\u0627 \u0639\u0646\u0643 \u0648\u064a\u062c\u0639\u0644\u0647\u0645 \u0643\u0644\u0651 \u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0645 \u0645\u0646\u0634\u063a\u0644\u0627 \u0628\u0646\u0641\u0633\u0647. \u0641\u0627\u062d\u0631\u0635 \u0639\u0644\u0649 \u0627\u0644\u0635\u0628\u0631 \u0648\u0644\u0627 \u062a\u062d\u0632\u0646\u060c \u062c\u0647\u0651\u0650\u0632 \u0646\u0641\u0633\u0643 \u0644\u0643\u0644\u0651 \u0623\u0645\u0631 \u0644\u062a\u0628\u062a\u0639\u062f \u0639\u0646 \u0627\u0644\u062d\u0642\u062f \u0648\u0627\u0644\u0639\u062f\u0627\u0648\u0629. \u0627\u0644\u062a\u0645\u0633 \u0637\u0631\u064a\u0642\u064b\u0627 \u0622\u062e\u0631 \u0641\u062a\u0623\u0630\u0646 \u0644\u0643 \u0631\u0624\u064a\u062a\u0647 \u062a\u062d\u0642\u064a\u0642\u064b\u0627 \u0643\u0627\u0645\u0644\u0627\u064b."},
{id:10,letters:"\u0627 \u0628 \u062f",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0633\u0645\u0649 \u064a\u0642\u0648\u0644: \u0645\u0646 \u064a\u062a\u0642\u0648\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u064a\u064f\u0645\u0647\u062f \u0644\u0647 \u0633\u0628\u064a\u0644\u060c \u0648\u064a\u064f\u0631\u0632\u0642 \u0645\u0646 \u062d\u064a\u062b \u0644\u0627 \u064a\u062d\u062a\u0633\u0628. \u0645\u0646 \u064a\u062a\u0648\u0643\u0651\u0644 \u0639\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u062a\u064f\u0648\u0641\u0651\u064e\u0631 \u0644\u0647 \u0627\u0644\u0643\u0641\u0627\u064a\u0629.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u062e\u0628\u0631\u0643 \u0628\u0646\u0628\u0623 \u0633\u0627\u0631 \u0639\u0646 \u0631\u062d\u0644\u062a\u0643 \u0627\u0644\u0645\u0631\u062a\u0642\u0628\u0629: \u0633\u062a\u062d\u0635\u0644 \u0639\u0644\u0649 \u0645\u0627 \u062a\u0631\u062c\u0648\u0647. \u0627\u0633\u0639 \u0628\u0633\u0631\u0639\u0629 \u0641\u064a \u0645\u0627 \u062a\u0634\u0627\u0621 \u0623\u0646 \u062a\u0641\u0639\u0644\u0647\u060c \u0648\u0644\u0643\u0646 \u0627\u062d\u0645\u062f \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0641\u0625\u0646\u0647 \u0633\u064a\u0632\u064a\u062f\u0643 \u0639\u0637\u064a\u0629. \u0642\u062f \u0641\u064f\u062a\u062d\u062a \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0633\u0639\u0627\u062f\u0629\u060c \u0648\u0633\u064a\u0639\u0648\u062f \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u0627\u0644\u0628\u0639\u064a\u062f\u060c \u0648\u0627\u0644\u062a\u062d\u0631\u0631 \u062d\u0627\u0636\u0631 \u0627\u0644\u0622\u0646."},
{id:11,letters:"\u0627 \u062c \u062f",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0638\u0627\u0647\u0631: \u0642\u062f \u0623\u0642\u0628\u0644\u062a \u0639\u0644\u064a\u0643\u0645 \u0639\u0627\u0642\u0628\u0629 \u062c\u0647\u0646\u0645\u060c \u0641\u0646\u062c\u0651\u0627\u0643\u0645 \u0645\u0646\u0647\u0627.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631\u0643\u060c \u0644\u0643\u0646 \u0627\u062d\u0630\u0631 \u0645\u0645\u0627 \u062a\u0631\u062c\u0648\u0647. \u0627\u0644\u0639\u0644\u064a \u0647\u0648 \u0634\u0647\u064a\u062f\u0643\u060c \u0641\u0644\u0627 \u062a\u062a\u0633\u0631\u0639 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631\u060c \u0644\u0623\u0646 \u0641\u064a\u0647 \u062a\u0646\u0627\u0642\u0636\u0627\u062a \u0648\u0623\u0643\u0627\u0630\u064a\u0628 \u0642\u062f \u062a\u0631\u0645\u0649 \u0644\u0625\u064a\u0630\u0627\u0626\u0643. \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0643\u0648\u0646 \u062d\u0630\u0631\u0627\u064b\u060c \u0641\u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0639\u0644\u064a \u0648\u0628\u0641\u0636\u0644\u0647 \u0648\u0642\u062f\u0631\u062a\u0647 \u0627\u0644\u0639\u0638\u064a\u0645\u0629 \u0641\u0633\u0648\u0641 \u064a\u0639\u064a\u0646\u0643 \u0639\u0644\u0649 \u0627\u0644\u062a\u063a\u0644\u0628 \u0639\u0644\u064a\u0647\u0627."},
{id:12,letters:"\u0627 \u062f \u0628",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u0623\u0638\u0647\u0631: \u0644\u0642\u062f \u0631\u0623\u0648\u0627 \u0628\u0623\u0645 \u0623\u0639\u064a\u0646\u0647\u0645 \u0623\u0646 \u0627\u0644\u0639\u062f\u0648 \u0643\u0627\u0646 \u0636\u0639\u0641 \u0639\u062f\u062f\u0647\u0645. \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u064a\u0639\u064a\u0646 \u0648\u064a\u062f\u0639\u0645 \u0645\u0646 \u064a\u0634\u0627\u0621.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631\u0643. \u0631\u0623\u064a\u062a\u0643 \u0642\u0644\u0642\u0627\u064b \u0645\u0646 \u0623\u062c\u0644 \u0634\u062e\u0635 \u0628\u0639\u064a\u062f\u060c \u0648\u0642\u0644\u0628\u0643 \u0645\u0636\u0637\u0631\u0628 \u0628\u0627\u0644\u0647\u0645\u0648\u0645\u060c \u0645\u062b\u0642\u0644 \u0628\u0627\u0644\u0623\u0641\u0643\u0627\u0631. \u0644\u0643\u0646 \u064a\u062c\u0628 \u0623\u0646 \u062a\u0641\u0631\u062d \u0628\u0644\u0642\u0627\u0626\u0647\u060c \u0641\u0647\u0648 \u0633\u064a\u0623\u062a\u064a \u0642\u0631\u064a\u0628\u0627\u064b \u0645\u062d\u0645\u0644\u0627\u064b \u0628\u0627\u0644\u0633\u0631\u0648\u0631. \u0627\u0644\u0623\u0645\u0646\u064a\u0629 \u0627\u0644\u062a\u064a \u0633\u0623\u0644\u062a \u0639\u0646\u0647\u0627 \u0633\u062a\u062a\u062d\u0642\u0642 \u0628\u0623\u0641\u0636\u0644 \u0635\u0648\u0631\u0629\u060c \u0641\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0639\u0644\u064a\u0645."},
{id:13,letters:"\u0627 \u062f \u062c",fortune:"\u0634\u0631\u064a\u0631",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0623\u0639\u0644\u0646: \u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646! \u0627\u062f\u062e\u0644\u0648\u0627 \u062c\u0645\u064a\u0639\u064b\u0627 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0644\u0627 \u062a\u062a\u0628\u0639\u0648\u0627 \u062e\u0637\u0648\u0627\u062a \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u060c \u0625\u0646\u0647 \u0644\u0643\u0645 \u0639\u062f\u0648 \u0645\u0628\u064a\u0646.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0634\u062f\u064a\u062f \u0627\u0644\u062d\u0630\u0631 \u0641\u064a\u0645\u0627 \u062a\u0631\u062c\u0648\u0647\u060c \u0644\u0627 \u062a\u0637\u0644\u0628\u0647\u060c \u0644\u0623\u0646 \u0641\u064a\u0647 \u0639\u0644\u064a\u0643 \u0636\u0631\u0631\u064b\u0627. \u0644\u0627 \u062a\u0641\u0634 \u0644\u0623\u062d\u062f \u0633\u0631\u064b\u0627\u060c \u0641\u0642\u062f \u062a\u062c\u0644\u0628 \u0627\u0644\u0644\u0633\u0627\u0646 \u0639\u0644\u064a\u0643 \u0627\u0644\u0634\u0642\u0627\u0621. \u0627\u062d\u0630\u0631 \u0639\u062f\u0648\u0643\u060c \u0641\u062a\u0646\u0627\u0644 \u0627\u0644\u0637\u0645\u0623\u0646\u064a\u0646\u0629\u060c \u0641\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0639\u0644\u064a\u0645."},
{id:14,letters:"\u0627 \u0628 \u0628",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0638\u0627\u0647\u0631: \u0627\u0644\u0645\u062a\u0642\u0648\u0646 \u062d\u0642\u064b\u0627 \u064a\u0642\u064a\u0645\u0648\u0646 \u0628\u064a\u0646 \u0627\u0644\u062c\u0646\u0627\u062a \u0648\u0627\u0644\u064a\u0646\u0627\u0628\u064a\u0639. \u0627\u062f\u062e\u0644\u0648\u0627 \u0641\u064a\u0647\u0627 \u0633\u0627\u0644\u0645\u064a\u0646 \u0648\u0622\u0645\u0646\u064a\u0646.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0623\u0628\u0634\u0631\u0643: \u0625\u0630\u0627 \u0641\u0631\u062d\u062a \u0628\u0627\u0646\u062a\u0635\u0627\u0631 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u0648 \u0648\u062a\u063a\u0644\u0628\u062a \u0639\u0644\u0649 \u0627\u0644\u0645\u0628\u0637\u0644\u064a\u0646\u060c \u0641\u0642\u062f \u0623\u0646\u0642\u0630\u0643 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0645\u0646 \u0643\u0644 \u0645\u0627 \u064a\u0645\u0643\u0646 \u0639\u062f\u0651\u0647 \u0639\u0642\u0628\u0629. \u0623\u0645\u0627 \u0645\u0627 \u062a\u0633\u0623\u0644 \u0639\u0646\u0647 \u0645\u0646 \u0623\u0645\u0646\u064a\u0629\u060c \u0641\u0639\u0627\u0645\u0644\u0647\u0627 \u0628\u0644\u0637\u0641 \u0648\u0635\u0628\u0631 \u0625\u0644\u0649 \u0623\u0646 \u062a\u0631\u0649 \u062b\u0645\u0631\u0629 \u062a\u0628\u0647\u062c \u0642\u0644\u0628\u0643. \u0625\u0630\u0627 \u0634\u0627\u0621 \u0627\u0644\u0639\u0644\u064a\u0651\u060c \u0641\u0633\u064a\u0628\u0644\u063a \u0642\u0644\u0628\u0643 \u0635\u0641\u0627\u0621\u064b \u0648\u064a\u0645\u062a\u0644\u0626 \u0633\u0631\u0648\u0631\u0627\u064b."},
{id:15,letters:"\u0627 \u062c \u062c",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0638\u0627\u0647\u0631: \u0627\u0644\u0645\u062d\u0633\u0646\u0648\u0646 \u064a\u062c\u0646\u0648\u0646 \u062e\u064a\u0631\u0647\u0645\u060c \u0648\u0627\u0644\u0645\u0633\u064a\u0626\u0648\u0646 \u064a\u062c\u0646\u0648\u0646 \u0623\u0630\u0627\u0647\u0645. \u0625\u0646 \u0643\u0646\u062a\u0645 \u0635\u0627\u0628\u0631\u064a\u0646 \u0648\u0645\u062a\u0642\u064a\u0646 \u0641\u0644\u0646 \u062a\u0636\u0631\u0651\u0643\u0645 \u0645\u0643\u0627\u0626\u062f \u0627\u0644\u0639\u062f\u0648\u0651 \u0634\u064a\u0626\u0627.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0642\u064e\u0648\u0650\u0651\u0645 \u0646\u064a\u062a\u0643. \u0627\u062d\u0630\u0631 \u0627\u0644\u0623\u0645\u0631 \u0627\u0644\u0630\u064a \u062a\u0623\u0645\u0644\u0647\u060c \u0641\u0625\u0646\u0647 \u0644\u0627 \u064a\u0646\u0641\u0639\u0643 \u0628\u0634\u064a\u0621. \u0627\u062d\u0641\u0638 \u0627\u0644\u0633\u0631 \u0648\u0644\u0627 \u062a\u0641\u0634\u0650\u0647\u060c \u0644\u062a\u062c\u0646\u0628 \u0627\u0644\u062d\u0633\u062f \u0648\u0627\u0644\u0643\u0631\u0627\u0647\u064a\u0629. \u0627\u0637\u0644\u0628 \u0639\u0648\u0646 \u0627\u0644\u0639\u0644\u064a\u060c \u062d\u062a\u0649 \u064a\u0641\u062a\u062d \u0644\u0643 \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0633\u0639\u0627\u062f\u0629."},
{id:16,letters:"\u0627 \u062f \u062f",fortune:"\u0634\u0631\u064a\u0631",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0645\u0628\u064a\u0646: \u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646! \u0643\u0648\u0646\u0648\u0627 \u0645\u0633\u062a\u0639\u062f\u064a\u0646\u060c \u0641\u0642\u0648\u0645\u0648\u0627 \u0641\u0631\u0642\u064b\u0627 \u0644\u0644\u0647\u062c\u0648\u0645\u060c \u0623\u0648 \u0642\u0648\u0645\u0648\u0627 \u062c\u0645\u064a\u0639\u064b\u0627 \u0644\u0644\u0647\u062c\u0648\u0645.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u064a\u062c\u0628 \u0623\u0646 \u062a\u0643\u0648\u0646 \u062d\u0630\u0631\u0627\u064b \u062c\u062f\u0627\u064b \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631. \u0625\u0646 \u0641\u0639\u0644\u062a\u0647 \u0641\u0642\u062f \u062a\u0648\u0627\u062c\u0647 \u062e\u0628\u0627\u062b\u0629 \u0648\u062d\u0642\u062f\u0627\u064b \u0648\u0647\u0645\u0648\u0645\u0627\u064b\u060c \u0648\u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0625\u0644\u0647\u064a \u0647\u0648 \u0634\u0627\u0647\u0650\u062f\u064f\u0643. \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u062d\u0630\u0631 \u0645\u0646 \u0627\u0644\u0645\u062e\u0627\u062f\u0639\u064a\u0646\u060c \u0644\u0623\u0646\u0647\u0645 \u064a\u0631\u064a\u062f\u0648\u0646 \u0627\u0644\u0627\u0642\u062a\u0631\u0627\u0628 \u0645\u0646\u0643 \u0644\u064a\u062c\u0631\u0628\u0648\u0627 \u0645\u0643\u0627\u0626\u062f\u0647\u0645. \u0625\u0646 \u0623\u0642\u062f\u0645\u062a \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0641\u0633\u0648\u0641 \u062a\u0644\u0627\u0642\u064a \u0645\u0634\u0642\u0629\u064b \u0648\u0643\u062f\u062d\u0627\u064b. \u0627\u0643\u0628\u062d \u0644\u0633\u0627\u0646\u0643\u060c \u0648\u0644\u0627 \u062a\u0641\u0634\u0651 \u0633\u0631\u0651\u0627\u064b \u0644\u0623\u062d\u062f\u060c \u0644\u062a\u062a\u0641\u0627\u062f\u0649 \u0645\u0643\u0627\u0626\u062f \u0627\u0644\u0623\u0634\u0631\u0627\u0631."},
{id:17,letters:"\u0628 \u0628 \u0628",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0642\u0627\u0644: \u0627\u0644\u064a\u0648\u0645 \u0642\u062f \u0623\u062a\u0645\u0645\u062a \u0644\u0643\u0645 \u062f\u064a\u0646\u0643\u0645\u060c \u0648\u0623\u062a\u0645\u0645\u062a \u0639\u0644\u064a\u0643\u0645 \u0646\u0639\u0645\u062a\u064a\u060c \u0648\u0627\u062e\u062a\u0631\u062a \u0644\u0643\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u062f\u064a\u0646\u064b\u0627.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631\u0643 \u0628\u0645\u0627 \u062a\u0631\u062c\u0648\u0647: \u0627\u0644\u062c\u0645\u064a\u0639 \u064a\u062b\u0646\u0648\u0646 \u0639\u0644\u0649 \u0641\u0636\u064a\u0644\u062a\u0643 \u0648\u064a\u0642\u062f\u0631\u0648\u0646 \u0623\u0639\u0645\u0627\u0644\u0643. \u0623\u0639\u062f\u0627\u0624\u0643 \u064a\u0646\u0648\u0648\u0646 \u062e\u062f\u0627\u0639\u0643\u060c \u0644\u0643\u0646 \u062d\u0643\u0645 \u0627\u0644\u0633\u0645\u0627\u0621 \u0633\u064a\u062c\u0639\u0644 \u062e\u0637\u062a\u0647\u0645 \u062a\u0646\u0647\u0627\u0631 \u0648\u064a\u0633\u0627\u0639\u062f\u0643 \u0639\u0644\u0649 \u0627\u0644\u0646\u0635\u0631 \u0639\u0644\u064a\u0647\u0645. \u0633\u064a\u0645\u0646\u062d\u0643 \u0645\u0646 \u062a\u0633\u0623\u0644 \u0639\u0646\u0647 \u0645\u0627 \u062a\u0631\u062c\u0648\u0647\u060c \u0642\u062f \u062a\u0643\u0648\u0646 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0633\u064a\u0631\u0629 \u0644\u0643\u0646\u0647 \u0633\u064a\u0624\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u062a\u064a\u0633\u064a\u0631."},
{id:18,letters:"\u062c \u062c \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0633\u0645\u0649 \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u062a\u0642\u0648\u0644: \u0647\u0630\u0647 \u0647\u064a \u0646\u0639\u0645\u0629 \u0648\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0633\u0645\u0627\u0621 \u0648\u0631\u062d\u0645\u062a\u0647\u0627 \u0627\u0644\u0648\u0627\u0639\u064a\u0629\u060c \u062c\u0639\u0644\u062a\u0647\u0645 \u064a\u0633\u0631\u0648\u0646 \u0628\u0630\u0644\u0643\u060c \u0641\u0647\u0630\u0627 \u0623\u0641\u0636\u0644 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u062a\u064a \u062c\u0645\u0639\u0648\u0647\u0627.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0641\u0623\u0628\u0644\u063a\u0643 \u0628\u0634\u0631\u0649 \u0639\u0646 \u0643\u0644 \u0645\u0627 \u064a\u0645\u0646\u062d\u0643 \u0625\u064a\u0627\u0647 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621: \u0641\u0643\u0644 \u064a\u0648\u0645 \u064a\u0641\u062a\u062d\u0648\u0646 \u0644\u0643 \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0642\u0648\u062a \u0648\u0627\u0644\u0628\u0631\u0643\u0627\u062a \u0648\u0627\u0644\u0633\u0631\u0648\u0631\u060c \u0648\u064a\u0639\u0648\u0646\u0646\u0651\u0643 \u0639\u0644\u0649 \u0647\u0632\u064a\u0645\u0629 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0648\u0627\u0644\u0645\u062e\u0627\u062f\u0639\u064a\u0646. \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0634\u0643\u0631\u060c \u0644\u0623\u0646\u0647\u0645 \u0628\u0641\u0636\u0644\u0647\u0650\u0645 \u0648\u0643\u0631\u0645\u0650\u0647\u0645 \u0648\u0648\u0633\u0639\u062a\u0650\u0647\u0645 \u0633\u064a\u0645\u0646\u062d\u0648\u0646\u0643."},
{id:19,letters:"\u062f \u062f \u062f",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0638\u0627\u0647\u0631: \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u064a\u0648\u0645\u060c \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u064a\u0641\u0631\u062d\u0648\u0646 \u0628\u0646\u0635\u0631\u0629 \u0627\u0644\u0633\u0645\u0627\u0621. \u0647\u0648 \u064a\u0646\u0635\u0631 \u0645\u0646 \u064a\u0634\u0627\u0621\u060c \u0625\u0646\u0647 \u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621\u060c \u062d\u0642\u064b\u0627 \u0631\u062d\u064a\u0645.\n\n\u064a\u0627 \u0633\u0627\u0626\u0650\u0644\u060c \u0623\u0628\u0634\u0631\u0643: \u0641\u0639\u0644 \u062d\u0643\u0645 \u0648\u062d\u0643\u0645\u0629\u060c \u0628\u0646\u0639\u0645\u0629 \u0627\u0644\u0639\u0644\u0648\u0651 \u0627\u0644\u0639\u0644\u064a\u0627\u060c \u0633\u064a\u062c\u0639\u0644 \u0642\u0644\u0628\u0643 \u0623\u0643\u062b\u0631 \u0633\u0631\u0648\u0631\u064b\u0627. \u062a\u062a\u062d\u0642\u0642 \u0623\u0645\u0646\u064a\u062a\u0643\u060c \u0648\u062a\u0646\u062c\u062d \u0623\u0645\u0648\u0631\u0643\u060c \u0648\u062a\u062a\u0645\u0651 \u0645\u0633\u0627\u0639\u064a\u0643. \u0628\u0639\u062f \u0627\u0644\u0634\u062f\u0629\u060c \u0633\u064a\u0647\u0628\u0651 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u064a\u0633\u064a\u0631 \u0633\u0631\u064a\u0639\u064b\u0627."},
{id:20,letters:"\u0628 \u0628 \u0627",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u064f\u0638\u0647\u0650\u0631: \u0627\u0644\u0645\u062a\u0642\u0648\u0646 \u064a\u0642\u064a\u0645\u0648\u0646 \u062d\u0642\u064b\u0627 \u0628\u064a\u0646 \u0627\u0644\u062c\u0646\u0627\u062a \u0648\u0627\u0644\u0639\u064a\u0648\u0646. \u0627\u062f\u062e\u0644\u0648\u0627\u0647\u0627 \u0628\u0633\u0644\u0627\u0645 \u0648\u0623\u0645\u0627\u0646. \u0648\u0642\u064a\u0644 \u0623\u064a\u0636\u064b\u0627: \u0628\u064a\u0646 \u0627\u0644\u0643\u0644\u0645\u0627\u062a\u060c \u0645\u0646 \u0623\u0635\u062f\u0642 \u0645\u0646 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a\u061f\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0644\u0623\u062c\u0644\u0643 \u0646\u064f\u0628\u0634\u0651\u0631 \u0628\u0627\u0644\u0638\u0641\u0631 \u0639\u0644\u0649 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0648\u0627\u0644\u0645\u064f\u0631\u062a\u0627\u0628\u064a\u0646. \u0623\u0645\u0627 \u0645\u0627 \u062a\u0633\u0623\u0644 \u0639\u0646\u0647 \u0645\u0646 \u0623\u0645\u0627\u0646\u064d \u0641\u0627\u0635\u0628\u0631 \u0642\u0644\u064a\u0644\u0627\u064b\u060c \u0648\u0627\u0646\u062a\u0638\u0631 \u0623\u0646 \u064a\u0641\u062a\u062d \u0644\u0643 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0628\u0627\u0628 \u0627\u0644\u0633\u0639\u0627\u062f\u0629\u060c \u0641\u0633\u062a\u0631\u0649 \u0641\u064a\u0647 \u062b\u0645\u0631\u064b\u0627 \u064a\u0628\u0647\u062c \u0642\u0644\u0628\u0643."},
{id:21,letters:"\u062c \u062c \u0627",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0642\u0648\u0644: \u0641\u064a\u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0627\u0635\u0628\u0631\u060c \u0648\u0644\u0627 \u062a\u064f\u0633\u0631\u0639\u060c \u0644\u0623\u0646 \u0627\u0644\u0625\u0633\u0631\u0627\u0639 \u0637\u0631\u064a\u0642 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u060c \u0648\u0627\u0644\u0635\u0628\u0631 \u0645\u0641\u062a\u0627\u062d \u0627\u0644\u062e\u0644\u0627\u0635. \u0648\u0633\u064a\u0631\u0634\u062f\u0643 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0625\u0644\u0649 \u0643\u0644 \u062e\u064a\u0631\u064d \u0646\u0627\u0632\u0644\u064d \u0639\u0644\u064a\u0643. \u0627\u0630\u0647\u0628 \u0641\u062a\u0646\u0632\u0647\u060c \u0641\u0633\u062a\u0631\u0649 \u062d\u0638\u0648\u0638\u064b\u0627 \u0643\u062b\u064a\u0631\u0629\u060c \u0641\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0639\u0644\u064a\u0645."},
{id:22,letters:"\u062f \u062f \u0627",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0638\u0645 \u0623\u0638\u0647\u0631: \u0644\u0642\u062f \u0633\u0645\u0639\u0646\u0627 \u0648\u0623\u0637\u0639\u0646\u0627\u060c \u0641\u0627\u063a\u0641\u0631 \u0644\u0646\u0627. \u0631\u0628\u064a! \u0623\u0646\u062a \u0627\u0644\u0645\u0644\u062c\u0623 \u0627\u0644\u0648\u062d\u064a\u062f.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0623\u0645\u0633\u0643 \u0644\u0633\u0627\u0646\u0643\u060c \u0648\u0644\u0627 \u062a\u0641\u0634\u0650 \u0633\u0631\u0627\u064b \u0644\u0623\u062d\u062f. \u0627\u0635\u0628\u0631 \u0648\u0627\u0646\u062a\u0638\u0631 \u0623\u0646 \u064a\u0641\u062a\u062d \u0644\u0643 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0633\u0639\u0627\u062f\u0629. \u062a\u0648\u0643\u0644 \u0639\u0644\u0649 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0641\u0647\u064a \u062a\u062d\u0628 \u0627\u0644\u0645\u062a\u0648\u0643\u0644\u064a\u0646. \u0627\u0644\u0635\u0628\u0631 \u0645\u0641\u062a\u0627\u062d \u0627\u0644\u062e\u0644\u0627\u0635\u060c \u0648\u0627\u0644\u0639\u062c\u0644\u0629 \u0637\u0631\u064a\u0642 \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646\u060c \u0648\u0627\u0644\u0633\u0645\u0627\u0621 \u062d\u0642\u064b\u0627 \u0645\u0639 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646."},
{id:23,letters:"\u0628 \u0627 \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u0627\u062f\u062e\u0644\u0648\u0627 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u0628\u0648\u0627\u0628\u0629! \u0625\u0630\u0627 \u062f\u062e\u0644\u062a\u0645\u060c \u0641\u0633\u062a\u0646\u062a\u0635\u0631\u0648\u0646 \u062d\u062a\u0645\u0627\u064b. \u062a\u0648\u0643\u0644\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0625\u0644\u0647\u064a \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0624\u0645\u0646\u064a\u0646.\n\n\u064a\u0627 \u0645\u0633\u062a\u062c\u0648\u0628\u060c \u0644\u0627 \u062a\u062e\u0641 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631\u060c \u0641\u0627\u0644\u0639\u0644\u064a \u0645\u0637\u0644\u0639 \u0639\u0644\u064a\u0643 \u0628\u0644\u0627 \u0634\u0643. \u0623\u0631\u0627\u0643 \u0645\u062a\u0623\u0645\u0644\u0627\u064b \u0628\u0634\u0623\u0646 \u0623\u0645\u0631\u064d \u0645\u0627\u061b \u0627\u0635\u0628\u0631 \u0642\u0644\u064a\u0644\u0627\u064b \u0641\u0633\u062a\u0628\u0644\u063a \u0623\u062e\u0628\u0627\u0631\u064b\u0627 \u0637\u064a\u0628\u0629\u064b \u0648\u0637\u0645\u0623\u0646\u064a\u0646\u0629\u064b\u060c \u0648\u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0639\u0644\u064a \u0641\u0627\u0644\u0641\u0643\u0627\u0643 \u0642\u0631\u064a\u0628."},
{id:24,letters:"\u0628 \u062c \u0628",fortune:"\u0634\u0631\u064a\u0631",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0638\u0647\u0648\u0631: \u0625\u0630\u0627 \u0627\u0633\u062a\u064f\u062e\u062f\u0645\u062a \u062c\u0645\u064a\u0639 \u0623\u0634\u062c\u0627\u0631 \u0627\u0644\u0623\u0631\u0636 \u0643\u0642\u0644\u0645\u060c \u0648\u0627\u0644\u0628\u062d\u0631 \u0643\u062d\u0628\u0631\u060c \u0641\u0625\u0646 \u0643\u0644\u0627\u0645 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0644\u0646 \u064a\u064e\u0646\u0642\u0636\u064a.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0644\u0627 \u062a\u0641\u0643\u0631 \u0623\u0643\u062b\u0631 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631\u060c \u0644\u0623\u0646 \u0630\u0644\u0643 \u0643\u0645\u0646 \u064a\u0637\u0644\u0628 \u0627\u0644\u0646\u062c\u0648\u0645 \u0641\u064a \u0648\u0636\u062d \u0627\u0644\u0646\u0647\u0627\u0631. \u0644\u0627 \u062a\u062a\u0639\u0628 \u0646\u0641\u0633\u0643\u060c \u0627\u0644\u062a\u062e\u0644\u064a \u0639\u0646\u0647 \u0623\u0641\u0636\u0644 \u0644\u0643. \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u062a\u064a \u0646\u0644\u062a\u0647\u0627 \u0642\u062f \u0643\u0627\u0646\u062a \u0648\u0627\u0636\u062d\u0629: \u0627\u0644\u062a\u062e\u0644\u064a \u064a\u062c\u0644\u0628 \u0627\u0644\u062e\u064a\u0631\u060c \u0627\u0644\u062a\u0645\u0633\u0643 \u064a\u062c\u0644\u0628 \u0627\u0644\u0634\u0624\u0645. \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0633\u064a\u0633\u0627\u0639\u062f\u0643 \u0641\u064a \u0646\u064a\u0644 \u0645\u0627 \u0647\u0648 \u0622\u062e\u0631."},
{id:25,letters:"\u0628 \u0628 \u062f",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u062f\u0644\u064a\u0644: \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0645\u0639 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u062a\u0641\u0633\u0631\u060c \u0641\u064a\u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0648\u062a\u0641\u0643\u0631 \u0641\u064a\u0647 \u0641\u064a \u0642\u0644\u0628\u0643\u060c \u0641\u0644\u0627 \u062a\u0643\u0646 \u0639\u0627\u062c\u0644\u0627\u064b\u061b \u0627\u0644\u0639\u062c\u0644\u0629 \u0645\u0646 \u0637\u0631\u0642 \u0627\u0644\u0634\u064a\u0637\u0627\u0646. \u0625\u0646 \u0627\u062d\u062a\u0633\u0628\u062a \u0648\u0635\u0628\u0631\u062a \u0641\u0633\u062a\u0646\u0627\u0644 \u062c\u0632\u0627\u0621\u064b \u0648\u0627\u0641\u0631\u0627\u064b."},
{id:26,letters:"\u0628 \u062c \u062f",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0633\u0645\u0649 \u064a\u064f\u0638\u0647\u0631: \u0627\u0635\u0628\u0631\u060c \u0643\u0645\u0627 \u064a\u0635\u0628\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0639\u0632\u0645 \u062f\u0627\u0626\u0645\u064b\u0627\u060c \u0648\u0644\u0627 \u062a\u062a\u0637\u0644\u0628 \u0623\u0646 \u064a\u0638\u0647\u0631 \u0639\u0642\u0627\u0628\u0647\u0645 \u0628\u0633\u0631\u0639\u0629.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631\u0643: \u0641\u064a\u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0644\u0627 \u062a\u063a\u062a\u0631\u0639\u064e\u060c \u0628\u0644 \u0627\u0635\u0628\u0631 \u0639\u0644\u064a\u0647 \u0628\u062d\u064f\u0633\u0646\u0650 \u0627\u0646\u062a\u0638\u0627\u0631\u060c \u0648\u0627\u0646\u062a\u0638\u0631 \u062d\u0643\u0645 \u0627\u0644\u0633\u0645\u0627\u0621 \u0641\u0627\u0644\u0623\u0645\u0631 \u0627\u0644\u0645\u062d\u062a\u0648\u0645 \u0633\u064a\u0642\u0639. \u0631\u063a\u0628\u062a\u0643 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0644\u062d\u0638\u0629 \u0644\u0627 \u062a\u062a\u062d\u0642\u0642\u060c \u0648\u0644\u0643\u0646 \u0628\u0639\u062f \u064a\u0623\u0633\u0643\u060c \u0648\u0628\u0625\u0631\u0627\u062f\u0629\u0650 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0633\u064a\u064f\u0646\u0627\u0644\u064f\u0643 \u0645\u0627 \u062a\u0631\u062c\u0648\u0647."},
{id:27,letters:"\u0628 \u0627 \u0627",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0638\u0647\u0631: \u0623\u0645\u0627 \u062a\u0631\u0648\u0646\u061f \u0644\u0642\u062f \u0647\u064a\u0623 \u0644\u0643\u0645 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0627\u0644\u0643\u0648\u0646 \u0648\u0643\u0644 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u0627\u062a \u0648\u0623\u063a\u062f\u0642 \u0639\u0644\u064a\u0643\u0645 \u0646\u0639\u0645\u0629 \u0625\u062e\u0644\u0627\u0635 \u0627\u0644\u0642\u0644\u0628 \u0648\u0627\u0644\u0633\u0631\u064a\u0631\u0629 \u0648\u0627\u0644\u0628\u062f\u0646\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0623\u062e\u0628\u0627\u0631 \u0633\u0627\u0631\u0629 \u0644\u0637\u0644\u0628\u0643 \u0627\u0644\u0645\u062d\u062f\u062f: \u0633\u062a\u0631\u0649 \u062b\u0645\u0631\u0629 \u062a\u064f\u0633\u0631\u0643. \u0623\u064e\u0633\u0652\u0631\u0650\u0639 \u0648\u0627\u0637\u0644\u0628 \u0639\u0648\u0646 \u0627\u0644\u0623\u0639\u0638\u0645\u060c \u0641\u0633\u062a\u0646\u062c\u062d \u0648\u0633\u062a\u062a\u062d\u0642\u0642 \u0627\u0644\u0623\u0645\u0646\u064a\u0629. \u0642\u062f \u063a\u064a\u0651\u064e\u0631\u062a \u0644\u0643 \u0637\u0631\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0643\u0644 \u0634\u064a\u0621\u060c \u0648\u0633\u062a\u0646\u0627\u0644 \u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0648\u0623\u0646\u062a \u0641\u064a \u0623\u0641\u0636\u0644 \u062d\u0627\u0644\u060c \u0641\u0628\u0650\u0646\u0650\u0639\u0652\u0645\u062a\u0647\u0650 \u0627\u0637\u0645\u0626\u0646 \u0648\u0627\u0633\u062a\u0645\u062a\u0639."},
{id:28,letters:"\u0628 \u062c \u062c",fortune:"\u0634\u0631\u064a\u0631",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0648\u0636\u062d: \u0644\u0645\u0627\u0630\u0627 \u0644\u0627 \u064a\u0631\u0633\u0644 \u0643\u0644 \u062c\u0645\u0627\u0639\u0629 \u0639\u062f\u0629 \u0623\u0634\u062e\u0627\u0635 \u0644\u0637\u0644\u0628 \u0641\u0647\u0645 \u0623\u0639\u0645\u0642 \u0644\u0644\u062a\u0639\u0627\u0644\u064a\u0645\u061f\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u062d\u0630\u0631\u0643 \u0623\u0644\u0627 \u062a\u0642\u0648\u0645 \u0628\u0645\u0627 \u062a\u0631\u062c\u0648\u0647\u060c \u0644\u0623\u0646\u0647 \u0625\u0646 \u0641\u0639\u0644\u062a \u0641\u0633\u064a\u0642\u0648\u062f\u0643 \u0630\u0644\u0643 \u0625\u0644\u0649 \u0627\u0644\u0646\u062f\u0645 \u0648\u0627\u0644\u0628\u063a\u0636\u060c \u0648\u064a\u0632\u062f\u0627\u062f \u0647\u0645\u0643 \u062d\u0632\u0646\u0627\u064b. \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0628\u0631\u062d\u0645\u062a\u0647 \u0648\u0625\u062d\u0633\u0627\u0646\u0647 \u064a\u0646\u062c\u064a\u0643 \u0645\u0646 \u0630\u0644\u0643. \u0623\u0646\u062a \u062a\u062e\u0637\u0637 \u0633\u0631\u0627 \u0648\u062a\u0632\u0646 \u0627\u0644\u0623\u0645\u0648\u0631 \u0641\u064a \u0642\u0644\u0628\u0643 \u062f\u0648\u0645\u0627\u064b\u060c \u0641\u0627\u062a\u0631\u0643 \u0627\u0644\u0623\u0645\u0631\u060c \u0641\u0625\u0646\u0647 \u0644\u0646 \u064a\u062a\u062d\u0642\u0642 \u0644\u0643\u060c \u0648\u0633\u062a\u0643\u0627\u0641\u0626\u0643 \u0627\u0644\u0633\u0645\u0627\u0621 \u0628\u062e\u064a\u0631\u064d \u0623\u0641\u0636\u0644."},
{id:29,letters:"\u0628 \u062f \u062f",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0642\u0627\u0644: \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u062d\u0630\u0631: \u0623\u0646\u0627 \u0645\u062c\u0631\u062f \u0628\u0634\u0631 \u0645\u062b\u0644\u0643\u0645\u060c \u0623\u0646\u0632\u0644 \u0625\u0644\u064a\u0651\u064e \u0627\u0644\u0648\u062d\u064a: \u0631\u0628\u0643\u0645 \u0647\u0648 \u0627\u0644\u0625\u0644\u0647 \u0627\u0644\u0648\u0627\u062d\u062f \u0627\u0644\u0623\u062d\u062f.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0623\u0628\u0634\u0631: \u0627\u0633\u0639\u064e \u0644\u0645\u0639\u0648\u0646\u0629 \u0627\u0644\u0639\u0644\u064a \u0648\u0627\u0633\u062a\u0648\u062f\u0639\u0647\u060c \u0641\u0625\u0646\u0647 \u064a\u0641\u0631\u062c \u0647\u0645\u0643. \u0644\u0627 \u062a\u062e\u0641 \u0645\u0646 \u0627\u0644\u0623\u0639\u062f\u0627\u0621\u060c \u0641\u0645\u0646 \u0644\u0645 \u064a\u0643\u0646 \u0633\u0648\u0649 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0621 \u0648\u0627\u0644\u062a\u0634\u0647\u064a\u0631 \u0644\u0627 \u064a\u0636\u0631\u0651\u0643 \u0628\u0634\u064a\u0621. \u0645\u0627 \u062a\u0633\u0623\u0644 \u0639\u0646\u0647 \u0633\u064a\u064f\u0645\u0646\u062d\u0643 \u0628\u0623\u062d\u0628\u0651 \u0635\u0648\u0631 \u0627\u0644\u062a\u0644\u0628\u064a\u0629 \u0625\u0644\u064a\u0643\u060c \u0641\u0627\u0644\u0642\u062f\u0631 \u064a\u0633\u0631\u0639 \u0628\u0646\u0639\u0645\u0629 \u0648\u0631\u062d\u0645\u0629 \u0644\u062a\u0641\u0631\u0627\u062d\u0643."},
{id:30,letters:"\u0628 \u0627 \u0628",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0638\u0647\u0631: \u0644\u0643\u064a \u064a\u0643\u0627\u0641\u0626 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0627\u0644\u0646\u0627\u0633 \u0639\u0644\u0649 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0648\u064a\u0645\u0646\u062d\u0647\u0645 \u0627\u0644\u0646\u0650\u0639\u064e\u0645. \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u064a\u0639\u0638\u0651\u0645 \u0625\u0645\u062f\u0627\u062f \u0645\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0627\u0644\u0628\u0634\u0631.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631\u0643: \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0633\u064a\u0645\u0646\u062d\u0643 \u0631\u0632\u0642\u064b\u0627 \u0648\u0627\u0633\u0639\u064b\u0627\u060c \u0648\u0633\u062a\u0646\u0627\u0644 \u0645\u0627 \u062a\u0628\u062a\u063a\u064a \u0641\u064a \u0623\u0645\u0648\u0631\u0643. \u0644\u0643\u0646 \u0639\u0644\u064a\u0643 \u0628\u0628\u0639\u0636 \u0627\u0644\u0635\u0628\u0631\u060c \u0641\u0627\u0644\u0644\u0647 \u0633\u064a\u064f\u0641\u062a\u062d \u0644\u0643 \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0628\u0634\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u062f\u062f\u0629\u060c \u0648\u064a\u063a\u062f\u0642 \u0639\u0644\u064a\u0643 \u0628\u0627\u0644\u0646\u0635\u0631 \u0648\u0627\u0644\u0628\u0631\u0643\u0627\u062a. \u0647\u0643\u0630\u0627 \u0623\u0634\u0627\u0631 \u0627\u0644\u0642\u0631\u0639\u060c \u0641\u0644\u0627 \u062a\u062e\u0641."},
{id:31,letters:"\u0628 \u062c \u0627",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0623\u0639\u0644\u0649 \u0627\u0644\u0633\u064a\u062f \u0647\u0648 \u0627\u0644\u0628\u064a\u0627\u0646: \u062d\u0627\u0644\u062a\u0647\u0645\u060c \u0643\u0625\u0646\u0633\u0627\u0646 \u064a\u064f\u0634\u0639\u0644 \u0627\u0644\u0646\u0627\u0631\u060c \u0648\u062d\u064a\u0646 \u064a\u0636\u064a\u0621 \u0646\u0648\u0631 \u0627\u0644\u0646\u0627\u0631 \u0641\u064a \u0643\u0644 \u0627\u0644\u062c\u0647\u0627\u062a\u060c \u064a\u0623\u062e\u0630 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0628\u0631\u064a\u0642\u0647\u060c \u0648\u064a\u062a\u0631\u0643\u0647 \u0641\u064a \u0638\u0644\u0645\u0627\u062a \u0643\u062b\u064a\u0641\u0629\u060c \u0641\u0644\u0627 \u064a\u0631\u0649 \u0634\u064a\u0626\u064b\u0627.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u060c \u0623\u0631\u0627\u0643 \u063a\u0627\u0631\u0642\u064b\u0627 \u0641\u064a \u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0628\u0634\u0623\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631\u060c \u0641\u0627\u062a\u0631\u0643\u0647\u060c \u0625\u0644\u0649 \u0623\u0646 \u064a\u062c\u0639\u0644 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0627\u0644\u0623\u0645\u0648\u0631 \u0633\u0647\u0644\u0629. \u0625\u0630\u0627 \u0623\u0628\u0642\u064a\u062a \u0627\u0644\u0633\u0631 \u062a\u062c\u0627\u0647 \u0627\u0644\u0639\u062f\u0648\u060c \u0641\u0633\u064a\u0646\u062c\u064a\u0643 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0641\u064a \u0643\u0644 \u0623\u0645\u0648\u0631\u0643\u060c \u0641\u0627\u0644\u0644\u0647 \u0627\u0644\u0639\u0644\u064a\u0645 \u0627\u0644\u062d\u0642."},
{id:32,letters:"\u0628 \u0627 \u0647\u0640",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u062e\u0627\u0644\u0642 \u0627\u0644\u0623\u0639\u0644\u0649 \u0623\u0638\u0647\u0631: \u0623\u0646\u0642\u0630\u0647 \u0647\u0648 \u0648\u0645\u0624\u0645\u0646\u0648\u0647 \u0645\u0646 \u0627\u0644\u0645\u0635\u064a\u0628\u0629 \u0627\u0644\u0639\u0638\u064a\u0645\u0629.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631\u0643 \u0628\u0623\u062e\u0628\u0627\u0631 \u0633\u0627\u0631\u0629: \u0645\u0627 \u0641\u064a \u0642\u0644\u0628\u0643 \u0645\u0646 \u0623\u0645\u0646\u064a\u0627\u062a \u062e\u0641\u064a\u0629 \u0633\u0648\u0641 \u064a\u062a\u062d\u0642\u0642 \u0628\u0633\u0647\u0648\u0644\u0629 \u0648\u0628\u0627\u0644\u0642\u0637\u0639. \u0627\u0644\u0623\u0639\u0638\u0645 \u064a\u0639\u064a\u0646\u0643 \u0639\u0644\u0649 \u0647\u0632\u064a\u0645\u0629 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0648\u0627\u0644\u0645\u062e\u0627\u062f\u0639\u064a\u0646\u060c \u0648\u064a\u062e\u0644\u0635\u0643 \u0645\u0646 \u0627\u0644\u0645\u0635\u0627\u0639\u0628 \u0627\u0644\u0648\u0627\u0642\u0639\u0629 \u0639\u0644\u0649 \u062c\u0633\u062f\u0643\u060c \u0641\u0633\u062a\u0646\u0627\u0644 \u0645\u0627 \u062a\u0631\u062c\u0648\u0647\u060c \u0648\u064a\u0639\u0645 \u0642\u0644\u0628\u0643 \u0627\u0644\u062e\u0634\u064a\u0629 \u0648\u0627\u0644\u0641\u0631\u062d."},
{id:33,letters:"\u062c \u0628 \u062f",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0633\u0645\u0649 \u0647\u0648 \u0627\u0644\u0628\u064a\u0627\u0646: \u0647\u0643\u0630\u0627 \u0623\u0639\u064a\u0646\u064f\u0647 \u0644\u0623\u0632\u064a\u0644 \u0633\u0648\u0621\u0647 \u0648\u0642\u0628\u062d\u0647. \u0647\u0648 \u062d\u0642\u064b\u0627 \u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0645 \u0627\u0644\u0637\u0627\u0647\u0631\u0648\u0646 \u0644\u064a.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0631\u0627\u0643 \u062d\u0627\u0645\u0644\u0627\u064b \u0647\u0645\u0648\u0645\u0627\u064b \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631\u060c \u0648\u0627\u0636\u0637\u0631\u0627\u0628 \u0627\u0644\u0646\u0641\u0633 \u0645\u0633\u062a\u0628\u062f \u0628\u0643. \u062a\u0648\u062f \u0623\u0646 \u062a\u0641\u0639\u0644 \u0648\u062a\u0631\u064a\u062f \u0623\u0646 \u062a\u0645\u062a\u0646\u0639\u060c \u0648\u0627\u0644\u0638\u0631\u0648\u0641 \u0639\u0633\u064a\u0631\u0629\u060c \u0648\u0627\u0644\u0635\u062f\u0631 \u0645\u0643\u0628\u0648\u062a\u060c \u0648\u0627\u062d\u062a\u0642\u0627\u0646 \u0627\u0644\u063a\u0636\u0628 \u0641\u064a\u0643. \u0648\u0645\u0639 \u0630\u0644\u0643 \u0625\u0630\u0627 \u062a\u062a\u0631\u0643\u0647\u060c \u0641\u0627\u0644\u0645\u062a\u0639\u0627\u0644 \u0628\u0631\u062d\u0645\u062a\u0647 \u0648\u0641\u0636\u0644\u0647 \u0648\u0646\u0648\u0631 \u0641\u0647\u0645\u0647 \u064a\u0632\u064a\u0644 \u0639\u0646\u0643 \u0647\u0645\u0648\u0645\u0643."},
{id:34,letters:"\u062c \u062c \u0628",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u0627\u0630\u0647\u0628! \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0639\u0627\u0644\u0645\u060c \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0642\u0648\u0644 \u062f\u0627\u0626\u0645\u0627\u064b: \u0644\u0627 \u062a\u0644\u0645\u0633\u0646\u064a.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631\u0643: \u0643\u0644 \u0645\u0627 \u062a\u0637\u0644\u0628\u0647 \u064a\u0645\u0643\u0646 \u0623\u0646 \u062a\u062d\u0635\u0644 \u0639\u0644\u064a\u0647\u060c \u0644\u0623\u0646 \u0627\u0644\u062d\u0638 \u0627\u0644\u062c\u064a\u062f \u064a\u0642\u062a\u0631\u0628 \u0645\u0646\u0643\u060c \u0633\u062a\u062d\u0635\u0644 \u0633\u0631\u064a\u0639\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0641\u0631\u062d \u0648\u0627\u0644\u0646\u0635\u0631 \u0627\u0644\u0642\u0631\u064a\u0628. \u0627\u0644\u0623\u0645\u0646\u064a\u0629 \u0627\u0644\u062a\u064a \u0633\u0623\u0644\u062a \u0639\u0646\u0647\u0627 \u0633\u062a\u062a\u062d\u0642\u0642 \u0642\u0631\u064a\u0628\u064b\u0627 \u0628\u0644\u0627 \u062a\u0623\u062e\u064a\u0631 \u0648\u0644\u0627 \u0639\u0646\u0627\u0621\u060c \u0641\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0633\u064a\u062c\u0639\u0644 \u0627\u0644\u0623\u0645\u0648\u0631 \u064a\u0633\u064a\u0631\u0629. \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0645\u062f\u062d \u0648\u062a\u0643\u0648\u0646 \u0634\u0627\u0643\u0631\u0627\u064b\u060c \u0641\u0647\u0648 \u0633\u064a\u0645\u0646\u062d\u0643 \u0645\u0646 \u062d\u0633\u0646 \u062d\u0638\u0647 \u0648\u0641\u0636\u0644\u0647 \u0627\u0644\u0648\u0641\u064a\u0631."},
{id:35,letters:"\u062c \u062c \u062f",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0633\u0645\u0649 \u064a\u0628\u064a\u0651\u0646: \u0625\u0646 \u0643\u0646\u062a \u062a\u062a\u0648\u0642 \u0623\u0646 \u064a\u0633\u0644\u0643\u0648\u0627 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0635\u062d\u064a\u062d\u060c \u0641\u0625\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0644\u0627 \u064a\u062c\u0639\u0644 \u0627\u0644\u0636\u0627\u0644\u064a\u0646 \u064a\u0646\u0627\u0644\u0648\u0646 \u0627\u0644\u0637\u0631\u064a\u0642\u060c \u0641\u0647\u0645 \u0642\u0637 \u0628\u0644\u0627 \u0645\u0639\u064a\u0646.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0644\u0627 \u062a\u062a\u0645\u0633\u0643 \u0628\u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631\u060c \u0627\u0635\u0628\u0631 \u0648\u0627\u0646\u062a\u0638\u0631 \u062d\u062a\u0649 \u064a\u062d\u0643\u0645 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0641\u064a \u0645\u0627 \u0644\u0627 \u0645\u062d\u0627\u0644\u0629. \u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0639\u0644\u064a\u060c \u0633\u064a\u064f\u0633\u062a\u062c\u0627\u0628 \u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0639\u0646\u062f\u0647 \u0639\u0627\u062c\u0644\u0627\u064b \u0623\u0645 \u0622\u062c\u0644\u0627\u064b\u060c \u0648\u0644\u0646 \u064a\u062a\u0637\u0644\u0628 \u0630\u0644\u0643 \u062c\u0647\u062f\u064b\u0627. \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0644\u062a\u0645\u0633 \u0627\u0644\u062e\u064a\u0631 \u0645\u0646 \u0627\u0644\u0646\u0628\u064a \u0643\u062b\u064a\u0631\u064b\u0627."},
{id:36,letters:"\u062c \u0627 \u0627",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0645\u064f\u0628\u064e\u064a\u0651\u0650\u0646: \u0628\u0639\u062f \u0645\u062e\u0627\u0641\u062a\u0647\u0645 \u0633\u064a\u0628\u062f\u0644\u0647\u0627 \u0628\u0627\u0644\u0637\u0645\u0623\u0646\u064a\u0646\u0629. \u0625\u0646\u0647\u0645 \u064a\u0639\u0628\u062f\u0648\u0646\u0646\u064a \u0648\u0644\u0627 \u064a\u0634\u0631\u0643\u0648\u0646 \u0645\u0639\u064a \u0623\u062d\u062f\u064b\u0627.\n\n\u064a\u0627 \u0633\u0627\u0626\u0650\u0644\u064f\u060c \u0623\u0639\u0637\u064a\u0643\u064e \u0628\u0634\u0631\u0649: \u0644\u0627 \u062a\u062e\u0641\u0652 \u0645\u0645\u0627 \u062a\u0631\u062c\u0648\u0647\u060c \u0641\u0627\u0644\u0645\u062a\u0639\u0627\u0644\u064f \u0633\u064a\u0639\u064a\u0646\u0643\u064f \u0628\u0646\u0635\u0631\u064d \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0643\u064e \u0648\u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0646\u064e\u060c \u0648\u0633\u062a\u0646\u064e\u0627\u0644\u064f \u0645\u0627 \u062a\u0631\u062c\u0648\u0647\u064f \u0641\u064a \u0641\u0631\u062d\u064d \u0648\u0633\u064a\u0631\u064d \u064a\u0633\u064f\u0631\u0651\u0627\u0646\u0650."},
{id:37,letters:"\u062c \u0628 \u062f",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0638\u0645 \u064a\u0638\u0647\u0631: \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u064a\u062d\u0627\u0633\u0628 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0641\u0642\u0637 \u0648\u0641\u0642 \u0645\u0627 \u0645\u0646\u062d\u064e\u0647 \u0645\u0646 \u0642\u062f\u0631\u0627\u062a. \u0628\u0639\u062f \u0627\u0644\u0634\u062f\u0627\u0626\u062f\u060c \u064a\u0633\u0631\u0639 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0641\u064a \u0623\u0646 \u064a\u0646\u0632\u0644 \u0627\u0644\u0633\u0647\u0648\u0644\u0629.\n\n\u064a\u0627 \u0633\u0627\u0644\u0643\u060c \u0625\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0642\u062f \u0648\u0647\u0628\u0643 \u0627\u0644\u062e\u064a\u0631 \u0648\u0627\u0644\u0633\u0631\u0648\u0631\u060c \u0641\u0627\u062d\u0645\u062f \u0648\u0627\u0635\u0628\u0631 \u0639\u0644\u0649 \u0645\u0627 \u062a\u0631\u062c\u0648\u0647\u060c \u0648\u062f\u0639\u0647 \u0644\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062a\u064a. \u064a\u064f\u0638\u0647\u0631 \u0627\u0644\u062a\u0646\u062c\u064a\u0645 \u0647\u0643\u0630\u0627: \u0628\u0627\u0644\u0635\u0628\u0631 \u062a\u064f\u062c\u0646\u0628 \u0627\u0644\u062d\u0645\u0627\u0642\u0629\u060c \u0648\u0625\u0644\u0627 \u0641\u0627\u0644\u062d\u0645\u0627\u0642\u0629 \u0644\u0627 \u062a\u0646\u0641\u0639 \u0623\u064a\u0636\u0627\u064b. \u0641\u0625\u0630\u0627 \u0634\u0627\u0621 \u0627\u0644\u0639\u0644\u064a\u060c \u062a\u0635\u064a\u0631 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u0639\u0633\u0631\u0629 \u0633\u0647\u0644\u0629 \u0644\u0643."},
{id:38,letters:"\u062c \u062f \u062f",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0642\u0627\u0644: \u0623\u0639\u0638\u0645 \u0631\u0639\u0628 \u0644\u0627 \u064a\u0633\u0628\u0628 \u0642\u0644\u0642\u064b\u0627\u060c \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u064a\u0631\u062d\u0628\u0648\u0646 \u0628\u0647 \u0642\u0627\u0626\u0644\u064a\u0646: \u0647\u0630\u0627 \u0647\u0648 \u0627\u0644\u0639\u064a\u062f \u0627\u0644\u0630\u064a \u0648\u064f\u0639\u0650\u062f\u062a\u0645 \u0628\u0647.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631\u0643: \u062d\u0627\u0641\u0638\u0643 \u0642\u062f \u0648\u0639\u062f\u0643 \u0628\u0635\u062f\u0642. \u0648\u0625\u0646 \u0644\u0645 \u062a\u0643\u0646 \u062a\u062f\u0631\u064a \u0627\u0644\u062d\u064a\u0644\u0629\u060c \u0641\u0633\u062a\u0646\u0627\u0644 \u0627\u0644\u062e\u0644\u0627\u0635. \u0644\u0627 \u062a\u0642\u0644\u0642\u060c \u0644\u0623\u0646\u0646\u0627 \u0646\u0634\u064a\u062f \u0644\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0648\u0642\u062f \u0648\u0639\u062f\u0643 \u0628\u0627\u0644\u0633\u0631\u0648\u0631 \u0648\u062d\u0642\u0642 \u0623\u0645\u0646\u064a\u062a\u0643. \u0628\u0625\u0631\u0627\u062f\u0629 \u0627\u0644\u0639\u0627\u0644\u064a \u0633\u062a\u0646\u0627\u0644 \u0637\u0644\u0628\u0643 \u0628\u0623\u0641\u0636\u0644 \u0647\u064a\u0626\u0629 \u0648\u0623\u0637\u0645\u0626\u0646 \u0642\u0644\u0628."},
{id:39,letters:"\u062c \u0627 \u0628",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0638\u0647\u0631: \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0633\u064a\u0641\u0643\u0651 \u0639\u0642\u062f\u0629 \u0627\u0644\u0643\u0628\u062a \u0641\u064a \u0635\u062f\u0631\u0643 \u0645\u0646 \u0623\u062c\u0644\u0643\u060c \u0648\u0633\u062a\u0646\u0627\u0644 \u0645\u0627 \u062a\u0639\u062a\u0645\u062f \u0639\u0644\u064a\u0647 \u0641\u064a \u0623\u0645\u0648\u0631\u0643 \u0633\u0631\u064a\u0639\u064b\u0627. \u0627\u0644\u0642\u0644\u0628 \u064a\u062e\u0634\u0639 \u0648\u064a\u0641\u0631\u062d. \u0623\u0645\u0646\u064a\u062a\u0643 \u0633\u062a\u0643\u0648\u0646 \u0648\u0641\u0642 \u0646\u0639\u0645\u0647 \u0648\u0631\u062d\u0645\u062a\u0647 \u0648\u0631\u0624\u064a\u062a\u0647 \u0627\u0644\u0631\u062d\u064a\u0645\u0629\u060c \u0648\u062a\u062a\u0645 \u0628\u062d\u0633\u0628 \u0645\u0627 \u062a\u0631\u064a\u062f \u0648\u062a\u0631\u062c\u0648\u060c \u0641\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0639\u0644\u064a\u0645 \u0644\u0644\u063a\u0627\u064a\u0629."},
{id:40,letters:"\u062c \u062f \u0627",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0642\u0648\u0644: \u0625\u0646 \u0643\u0646\u062a\u0645 \u0634\u0627\u0643\u0631\u064a\u0646 \u0641\u0633\u0623\u0632\u064a\u062f\u0643\u0645\u061b \u0648\u0625\u0646 \u0643\u0646\u062a\u0645 \u062c\u0627\u062d\u062f\u064a\u0646 \u0641\u0633\u0623\u0643\u0648\u0646 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628.\n\n\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631: \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u062a\u062d\u0644\u0649 \u0628\u0627\u0644\u0635\u0628\u0631\u060c \u0644\u0627 \u062a\u062a\u0647\u0648\u0631\u060c \u0627\u0646\u062a\u0638\u0631 \u062d\u062a\u0651\u0649 \u062a\u062a\u062d\u0642\u0651\u0642 \u0645\u0648\u0627\u0632\u064a\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0627\u0644\u0645\u062d\u062a\u0648\u0645\u0629. \u0635\u0628\u0631\u0643 \u064a\u0639\u062a\u0645\u062f \u0643\u0644\u0651\u064a\u0627\u064b \u0639\u0644\u0649 \u0646\u0635\u0631 \u0627\u0644\u0639\u0644\u064a\u0651\u060c \u0641\u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0645\u0639 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646."},
{id:41,letters:"\u062c \u0628 \u0628",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u0623\u064e\u0645\u064e\u0631\u064e: \u0641\u0641\u062a\u062d\u062a \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0648\u0623\u0637\u0644\u0642\u062a \u0645\u0637\u0631\u0627\u064b \u063a\u0632\u064a\u0631\u0627\u064b\u061b \u0641\u0641\u064e\u062c\u0651\u064e\u0631\u062a\u064f \u064a\u0646\u0627\u0628\u064a\u0639 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u062c\u062a\u0645\u0639\u062a \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u0648\u0641\u0642 \u0646\u0638\u0627\u0645\u064d \u0645\u0639\u064a\u0651\u0646. \u062d\u064e\u0645\u064e\u0644\u062a\u064f\u0647\u0645 \u0639\u0644\u0649 \u0633\u0641\u064a\u0646\u0629 \u0645\u0646 \u062e\u0634\u0628 \u0648\u0645\u0633\u0627\u0645\u064a\u0631 \u062d\u062f\u064a\u062f\u064a\u0629\u060c \u0641\u0623\u0628\u062d\u0631\u0648\u0627 \u062a\u062d\u062a \u0631\u0639\u0627\u064a\u062a\u064a.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0644\u063a\u0643 \u0628\u0634\u0631\u0649 \u0645\u0627 \u062a\u0633\u0623\u0644 \u0639\u0646\u0647: \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0644\u062d\u0638\u0629 \u0628\u0627\u0644\u0630\u0627\u062a\u060c \u0627\u062c\u0639\u0644 \u0639\u0632\u064a\u0645\u062a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0639\u0645\u0644 \u0628\u0647\u060c \u0644\u0623\u0646 \u0633\u0646\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0633\u062a\u0645\u0646\u062d\u0643 \u0645\u0646 \u0627\u0644\u0628\u0631\u0643\u0627\u062a \u0627\u0644\u0645\u063a\u062f\u0642\u0629 \u0648\u0627\u0644\u0631\u0632\u0642 \u0627\u0644\u0648\u0641\u064a\u0631\u060c \u0648\u0627\u0644\u0644\u0647 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0645\u064e\u0646\u0652 \u064a\u0642\u0631\u0631 \u0645\u0639\u0627\u0644\u064a \u0627\u0644\u0633\u0639\u0627\u062f\u0629 \u0648\u0627\u0644\u0646\u062c\u0627\u062d."},
{id:42,letters:"\u062c \u062f \u0628",fortune:"\u0634\u0631\u064a\u0631",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u064f\u0638\u0647\u0631: \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0637\u0644\u0628 \u0627\u0644\u0645\u063a\u0641\u0631\u0629 \u0645\u0646 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u062a\u062a\u0631\u0643 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631\u060c \u0648\u0644\u0627 \u062a\u0637\u0644\u0628\u0647\u060c \u0644\u0623\u0646\u0647 \u0636\u0627\u0631 \u0648\u0644\u0627 \u0646\u0627\u0641\u0639. \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u062d\u0630\u0631 \u0639\u062f\u0651\u0648\u0643\u060c \u0644\u0623\u0646\u0647 \u064a\u0628\u0637\u0646 \u0627\u0644\u0645\u0643\u0627\u0626\u062f. \u0627\u0643\u0638\u0645 \u0644\u0633\u0627\u0646\u0643\u060c \u0648\u0644\u0627 \u062a\u064f\u0641\u0634\u064a \u0627\u0644\u0633\u0631\u0651\u060c \u0641\u0633\u0628\u064a\u0644 \u0627\u0644\u0633\u0645\u0627\u0621 \u0643\u0627\u0641\u064d \u0644\u0644\u0627\u0639\u062a\u0645\u0627\u062f."},
{id:43,letters:"\u062c \u0628 \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u0625\u0646\u0647 \u064a\u0642\u0648\u0644 \u0623\u0646\u0647 \u0623\u0646\u0632\u0644 \u0627\u0644\u063a\u064a\u062b\u060c \u0648\u0623\u0646\u0627 \u0623\u0633\u062a\u062e\u062f\u0645\u0647 \u0644\u0623\u062d\u064a\u064a \u0627\u0644\u0623\u0631\u0636 \u0627\u0644\u0645\u064a\u0651\u062a\u0629.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0644\u0623\u062c\u0644\u0643 \u062a\u062a\u0642\u0627\u0628\u0644 \u0623\u0645\u0646\u064a\u062a\u0643 \u0628\u062e\u0628\u0631 \u0633\u0627\u0631: \u0633\u062a\u062d\u0635\u0644 \u0633\u0631\u064a\u0639\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0628\u0647\u062c\u0629 \u0648\u0627\u0644\u062a\u062d\u0631\u0631. \u0623\u064f\u0633\u0631\u0639 \u0641\u064a \u062a\u062d\u0642\u064a\u0642 \u0623\u0645\u0646\u064a\u062a\u0643\u060c \u0648\u0628\u0625\u0631\u0627\u062f\u0629 \u0627\u0644\u0639\u0644\u064a\u0651 \u0633\u062a\u062d\u0642\u0642\u0647\u0627 \u0644\u0627 \u0645\u062d\u0627\u0644\u0629\u060c \u0641\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0645\u0639 \u0627\u0644\u0630\u0627\u0643\u0631\u064a\u0646 \u0648\u0627\u0644\u0645\u062a\u0645\u0634\u0651\u064a\u0646 \u0645\u0639\u0647."},
{id:44,letters:"\u062c \u062f \u062c",fortune:"\u0634\u0631\u064a\u0631",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0638\u0647\u0631: \u0633\u0648\u0627\u0621 \u0643\u064f\u0646\u0651\u0627 \u0642\u0644\u0642\u064a\u0646 \u0623\u0648 \u0635\u0627\u0628\u0631\u064a\u0646\u060c \u0641\u064a \u062d\u0627\u0644\u062a\u0646\u0627 \u0644\u062f\u0649\u0651\u064e \u0647\u064a \u0646\u0641\u0633\u0647\u0627\u060c \u0644\u0627 \u0645\u0647\u0631\u0628. \u0641\u0644\u062a\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u064a\u0639\u0644\u0645 \u062d\u0642\u064b\u0627 \u0623\u062d\u0648\u0627\u0644 \u0642\u0644\u0648\u0628\u0643\u0645\u060c \u0641\u0644\u062a\u062a\u062d\u0641\u0638\u0648\u0627 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0643\u0645.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0627\u062a\u0631\u0643 \u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0648\u0644\u0627 \u062a\u0637\u0644\u0628\u0647 \u0623\u0628\u062f\u0627\u064b\u060c \u0644\u0623\u0646 \u0647\u0646\u0627\u0643 \u0623\u0639\u062f\u0627\u0621 \u0648\u0645\u062e\u0627\u062f\u0639\u0648\u0646 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0636\u0639. \u0625\u0646 \u0643\u0627\u0646 \u0642\u062f\u0631 \u0627\u0644\u0633\u0645\u0627\u0621 \u0643\u0630\u0644\u0643\u060c \u0641\u0628\u0641\u0636\u0644 \u0631\u062d\u0645\u062a\u0647 \u064a\u0633\u0627\u0639\u062f\u0643 \u0639\u0644\u0649 \u0627\u0644\u062a\u063a\u0644\u0628 \u0639\u0644\u064a\u0647\u0645."},
{id:45,letters:"\u062f \u062f \u0628",fortune:"\u0633\u0639\u064a\u062f",text:"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u062f\u064e \u0627\u0644\u0623\u064e\u0639\u0652\u0644\u064e\u0649 \u0647\u064f\u0648\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0647\u0650\u0631\u064f: \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0639\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0637\u0651\u064e\u0631\u0650\u064a\u0642\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u0650\u064a\u0651\u064f\u060c \u0641\u064e\u0644\u064e\u0627 \u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649 \u063a\u064e\u0644\u064e\u0628\u064e\u062a\u0650\u0643\u064f\u0645\u0652\u061b \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e\u0643\u064f\u0645\u0652 \u0647\u064f\u0648\u064e\u060c \u0641\u064e\u0645\u064e\u0646\u0652 \u0633\u064e\u064a\u064f\u0639\u0650\u064a\u0646\u064f\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u062f\u064e\u0626\u0650\u0630\u064d\u061f\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0644\u064a\u062a\u0645\u0646\u0649 \u0627\u0644\u0644\u0647 \u0623\u0646 \u062a\u062a\u062d\u0642\u0642 \u0623\u0645\u0646\u064a\u062a\u0643 \u0648\u062a\u0646\u062a\u0635\u0631 \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0643 \u0641\u062a\u0641\u0631\u062d. \u0625\u0646\u0643 \u0625\u0630\u0627 \u0633\u0639\u064a\u062a \u0648\u0631\u0627\u0621 \u0623\u0645\u0646\u064a\u062a\u0643 \u0641\u0633\u062a\u062a\u062d\u0642\u0642. \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0623\u0645\u0631 \u0623\u0647\u0644 \u0628\u064a\u062a\u0643 \u0628\u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0627\u062b\u0628\u062a \u0641\u064a \u0627\u0644\u0635\u0644\u0627\u0629 \u0635\u0628\u0631\u0627 \u0639\u0638\u064a\u0645\u0627. \u0627\u0633\u0623\u0644 \u0645\u062d\u0645\u062f\u064b\u0627 \u0623\u0646 \u064a\u0645\u0646\u062d\u0643 \u0627\u0644\u0628\u0631\u0643\u0629\u060c \u0641\u0631\u0632\u0642\u0643 \u0633\u064a\u0632\u062f\u0627\u062f."},
{id:46,letters:"\u062f \u062f \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u064f\u0638\u0647\u0631: \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0624\u0645\u0646\u0648\u0646 \u0648\u064a\u0639\u0645\u0644\u0648\u0646 \u0627\u0644\u0635\u0627\u0644\u062d\u0627\u062a \u0633\u064a\u064f\u062c\u0639\u0644\u0648\u0646 \u0627\u0644\u062c\u0646\u0629 \u0645\u0633\u0643\u0646\u0647\u0645\u060c \u0648\u064a\u062e\u0644\u062f\u0648\u0646 \u0641\u064a\u0647\u0627\u060c \u0648\u0644\u0646 \u064a\u0631\u063a\u0628\u0648\u0627 \u0641\u064a \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0625\u0646\u0645\u0627 \u0623\u064f\u0628\u0634\u0651\u0650\u0631\u0643 \u0628\u0623\u0646\u0651\u064e\u0643 \u0633\u062a\u062d\u0638\u0649 \u0628\u0641\u0631\u062d\u064d \u0645\u0628\u0627\u0631\u0643\u064d. \u0642\u0627\u0644 \u0627\u0644\u0623\u0639\u0644\u0649: \u0625\u0646\u0652 \u0643\u0646\u062a\u0645\u0652 \u0634\u0627\u0643\u0631\u064a\u0646\u064e \u0641\u0633\u0623\u0632\u064a\u062f\u064f\u0643\u0645. \u0641\u0627\u0630\u0643\u0631\u0648\u0627\u060c \u0644\u0623\u0646\u0651\u064e \u0627\u0644\u0630\u0646\u0648\u0628\u064e \u062a\u064f\u0645\u062d\u064a \u0627\u0644\u0646\u0651\u0650\u0639\u064e\u0645\u064e\u060c \u0648\u0633\u064f\u0631\u0639\u0629\u064f \u0639\u0630\u0627\u0628\u0650 \u0627\u0644\u0631\u0651\u064e\u0628\u0651\u0650 \u0634\u062f\u064a\u062f\u0629\u064c."},
{id:47,letters:"\u062f \u0627 \u0627",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0642\u0648\u0644: \u064a\u0627 \u062f\u0627\u0648\u062f! \u0625\u0646\u064a \u0642\u062f \u062c\u0639\u0644\u062a\u0643 \u0646\u0627\u0626\u0628\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0641\u0627\u0635\u0641\u062d \u0628\u0627\u0644\u062d\u0642 \u0639\u0644\u0649 \u0627\u0644\u0634\u0639\u0628\u060c \u0648\u0644\u0627 \u062a\u062a\u0628\u0639 \u0623\u0647\u0648\u0627\u0621\u0643.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0644\u0627 \u062a\u062a\u062e\u0627\u0635\u0645 \u0645\u0639 \u0627\u0644\u0646\u0627\u0633 \u0648\u0644\u0627 \u062a\u062a\u062d\u0627\u0645\u0644 \u0639\u0644\u064a\u0647\u0645. \u062a\u062d\u0644\u0651\u064e \u0628\u0642\u0644\u064a\u0644 \u0645\u0646 \u0627\u0644\u0635\u0628\u0631 \u0641\u064a\u0645\u0627 \u062a\u0631\u062c\u0648\u0647. \u0627\u0644\u0622\u0646 \u0623\u0646\u062a \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u064a\u0631\u0629\u060c \u062a\u0631\u064a\u062f \u0623\u0646 \u062a\u0641\u0639\u0644 \u0648\u062a\u062a\u0631\u062f\u062f. \u0641\u064a \u0648\u0642\u062a \u0622\u062e\u0631\u060c \u0628\u0641\u0636\u0644 \u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u062a\u0635\u0644 \u0625\u0644\u0649 \u0645\u0637\u0644\u0628\u0643 \u062f\u0648\u0646 \u062c\u0647\u062f."},
{id:48,letters:"\u062f \u0628 \u062f",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0623\u0638\u0647\u0631: \u0625\u0646 \u0643\u0646\u062a\u0645 \u062a\u0633\u0623\u0644\u0648\u0646 \u0627\u0644\u062d\u0643\u0645 \u0641\u0642\u062f \u0646\u0632\u0644\u061b \u0648\u0625\u0646 \u062a\u0648\u0642\u0641\u062a\u0645 \u0639\u0646 \u0627\u0644\u0625\u062b\u0645 \u0641\u0630\u0644\u0643 \u062e\u064a\u0631. \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u062d\u0642\u064b\u0627 \u0645\u0639 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0623\u0628\u0634\u0631\u0643: \u0642\u062f \u062d\u0644 \u0646\u0635\u0631 \u0645\u0646 \u0627\u0644\u0639\u0644\u064a \u0627\u0644\u0639\u0638\u064a\u0645. \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0645\u0639\u0643\u060c \u0644\u064a\u0628\u062f\u062f \u062d\u0633\u0627\u0628 \u0623\u0639\u062f\u0627\u0626\u0643 \u0648\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0634\u0631\u064a\u0631\u0629\u060c \u0648\u064a\u0632\u064a\u062f\u0643 \u0646\u0639\u0645\u0629. \u0641\u0627\u0630\u0643\u0631\u0647\u0645\u060c \u0644\u0623\u0646\u0647\u0645 \u0647\u062f\u0651\u0648\u0643\u060c \u0641\u0643\u0646 \u0634\u0627\u0643\u0631\u0627\u064b."},
{id:49,letters:"\u062f \u0628 \u0627",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u0623\u064e\u0645\u064e\u0631\u064e: \u0641\u0641\u062a\u062d\u062a \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0648\u0623\u0637\u0644\u0642\u062a \u0645\u0637\u0631\u0627\u064b \u063a\u0632\u064a\u0631\u0627\u064b\u061b \u0641\u0641\u064e\u062c\u0651\u064e\u0631\u062a\u064f \u064a\u0646\u0627\u0628\u064a\u0639 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u062c\u062a\u0645\u0639\u062a \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u0648\u0641\u0642 \u0646\u0638\u0627\u0645\u064d \u0645\u0639\u064a\u0651\u0646. \u062d\u064e\u0645\u064e\u0644\u062a\u064f\u0647\u0645 \u0639\u0644\u0649 \u0633\u0641\u064a\u0646\u0629 \u0645\u0646 \u062e\u0634\u0628 \u0648\u0645\u0633\u0627\u0645\u064a\u0631 \u062d\u062f\u064a\u062f\u064a\u0629\u060c \u0641\u0623\u0628\u062d\u0631\u0648\u0627 \u062a\u062d\u062a \u0631\u0639\u0627\u064a\u062a\u064a.\n\n\u0627\u0644\u0633\u0627\u0626\u0644\u064f\u060c \u0625\u0646\u0645\u0627 \u0645\u0646 \u0623\u062c\u0644\u0643 \u0642\u062f \u0646\u0627\u0644 \u0627\u0644\u0641\u0631\u062d \u0648\u0627\u0644\u0633\u0631\u0648\u0631\u060c \u0641\u062d\u0642\u064b\u0627 \u0642\u062f \u062e\u0644\u0651\u0635\u0643\u0650 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0645\u0646 \u0643\u0644 \u0647\u0645\u0651 \u0648\u0643\u0622\u0628\u0629. \u0625\u0646\u0647 \u0633\u064a\u062d\u0642\u0642 \u0644\u0643 \u0643\u0644 \u0631\u063a\u0628\u0629 \u062a\u0631\u062c\u0648\u0647\u0627\u060c \u0648\u0633\u064a\u0647\u064a\u0626 \u0644\u0643 \u0643\u0644 \u0627\u0644\u0623\u0633\u0628\u0627\u0628. \u0641\u0627\u0634\u0643\u0631\u0650 \u0627\u0644\u0639\u0644\u064a\u0651\u060c \u0641\u0625\u0646\u0647 \u0633\u064a\u0632\u064a\u062f\u0643\u0650 \u062e\u064a\u0631\u064b\u0627 \u0648\u0628\u0631\u0643\u0629\u064b."},
{id:50,letters:"\u062f \u062c \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0634\u0627\u0647\u062f: \u0642\u062f \u0623\u0646\u0632\u0644\u062a \u0627\u0644\u0643\u0627\u0644\u0633\u064a\u0648\u0645 \u0648\u0627\u0644\u062d\u062f\u064a\u062f\u060c \u0641\u064a\u0647 \u0639\u0642\u0648\u0628\u0627\u062a \u0634\u062f\u064a\u062f\u0629\u060c \u0643\u0645\u0627 \u0641\u064a\u0647 \u0641\u0648\u0627\u0626\u062f \u0639\u062f\u064a\u062f\u0629\u060c \u0644\u0643\u064a \u062a\u0639\u0644\u0645 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0645\u0646 \u064a\u0633\u0627\u0639\u062f\u0647\u0645 \u062e\u0641\u064a\u0629 \u0648\u0645\u0646 \u0647\u0645 \u0631\u0633\u0644\u0647\u0645. \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u062d\u0642\u064b\u0627 \u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621.\n\n\u064a\u0627 \u0645\u0633\u062a\u0641\u0633\u0631\u060c \u0644\u0643 \u0633\u0631\u0648\u0631 \u0644\u0623\u0646\u0643 \u0633\u062a\u062d\u0635\u0644 \u0639\u0644\u0649 \u0627\u0644\u0633\u0639\u0627\u062f\u0629 \u0648\u0627\u0644\u0631\u0632\u0642 \u0627\u0644\u0648\u0641\u064a\u0631. \u0645\u0627 \u062a\u0633\u0623\u0644 \u0639\u0646\u0647 \u0633\u064a\u062a\u062d\u0642\u0642 \u0644\u0627 \u0645\u062d\u0627\u0644\u0629 \u0648\u064a\u0643\u0648\u0646 \u0645\u0628\u0627\u0631\u0643\u064b\u0627\u060c \u0641\u0644\u062a\u0641\u0631\u062d \u0628\u0642\u0636\u0627\u0621 \u0627\u0644\u0639\u0644\u064a\u060c \u0648\u0627\u062a\u0642\u0650 \u0648\u0627\u0641\u0631\u062d\u060c \u0641\u0633\u0628\u064a\u0644 \u0627\u0644\u0633\u0645\u0627\u0621 \u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u0633\u064a\u0631 \u0639\u0644\u0649 \u0645\u0627 \u064a\u0631\u0636\u0649."},
{id:51,letters:"\u062f \u0628 \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0647\u0627\u062f\u064a: \u0647\u0648 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0644\u0627 \u0625\u0644\u0647 \u063a\u064a\u0631\u0647. \u064a\u0639\u0644\u0645 \u0627\u0644\u063a\u064a\u0628 \u0648\u0627\u0644\u0638\u0627\u0647\u0631\u060c \u0623\u0631\u062d\u0645 \u0627\u0644\u0631\u0627\u062d\u0645\u064a\u0646 \u0648\u0623\u0639\u0638\u0645 \u0627\u0644\u0631\u062d\u0645\u0629.\n\n\u064a\u0627 \u0633\u0627\u0626\u0650\u0644\u064f \u0625\u0646\u064a \u0623\u0628\u0634\u0651\u0631\u0643\u064e: \u0631\u0623\u064a\u062a\u064f\u0643 \u062a\u0637\u0644\u0628\u064f \u0623\u0645\u0631\u064b\u0627\u060c \u0648\u0628\u0641\u0636\u0644\u0647 \u0633\u062a\u062a\u0641\u0648\u0642\u064f \u0639\u0644\u0649 \u0639\u062f\u0648\u0643 \u0648\u0627\u0644\u0645\u0636\u0644\u0651\u0650\u064a\u0646\u060c \u0648\u0647\u0648 \u064a\u062a\u0636\u0645\u0651\u0646\u064f \u0646\u0635\u0631\u0629\u064b \u0648\u0641\u0643\u0651\u064e\u0629\u064b \u0648\u0641\u0631\u062d\u064b\u0627. \u0639\u0644\u064a\u0643\u064e \u0628\u0627\u0644\u062d\u0645\u062f\u0650 \u0648\u0627\u0644\u0634\u0643\u0631\u0650\u060c \u0641\u0642\u062f \u0627\u0633\u062a\u062a\u0628\u0651\u064e\u062a \u0644\u0647 \u0646\u0639\u0645\u0629\u064f \u0631\u0628\u0648\u0628\u064a\u0651\u0629\u064c \u0645\u064f\u0646\u0650\u0639\u064e\u062a\u0652 \u0644\u0643. \u0627\u0644\u0637\u0631\u064a\u0642\u064f \u0627\u0644\u0625\u0644\u0647\u064a\u0651\u064f \u0639\u0644\u064a\u0645\u064c \u0628\u0627\u0644\u0643\u0627\u0645\u0644."},
{id:52,letters:"\u062f \u0627 \u062f",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0648\u0627\u0636\u062d: \u0638\u0644\u0645\u0627\u062a \u0648\u0646\u0648\u0631 \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u062a\u0639\u0648\u062f\u0627\u0646 \u0644\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0648\u062d\u062f\u0647\u060c \u0641\u0643\u0644 \u0627\u0644\u0623\u0645\u0648\u0631 \u062a\u0639\u0648\u062f \u0625\u0644\u064a\u0647\u060c \u0644\u0630\u0627 \u064a\u062c\u0628 \u0627\u0644\u0633\u062c\u0648\u062f \u0644\u0647 \u0648\u0627\u0644\u062a\u0648\u0643\u0644 \u0639\u0644\u064a\u0647. \u0631\u0628\u0643 \u0644\u0627 \u064a\u0636\u064a\u0639 \u0645\u0627 \u062a\u0641\u0639\u0644\u0648\u0646.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0642\u064a\u062f \u0644\u0633\u0627\u0646\u0643 \u0644\u0626\u0644\u0627 \u062a\u062c\u0644\u0628 \u0627\u0644\u0636\u0631\u0631. \u0627\u062d\u0630\u0631 \u0639\u062f\u0648\u0643\u060c \u0644\u0623\u0646\u0647\u0645 \u064a\u062f\u0628\u0631\u0648\u0646 \u0627\u0644\u062d\u064a\u0644 \u0644\u0625\u064a\u0630\u0627\u0626\u0643. \u0641\u064a\u0645\u0627 \u062a\u0633\u0623\u0644 \u0639\u0646\u0647\u060c \u0627\u0646\u0635\u0631\u0641 \u0625\u0644\u0649 \u0623\u0645\u0648\u0631 \u0623\u062e\u0631\u0649\u060c \u0647\u0646\u0627 \u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0627 \u062a\u0637\u0644\u0628\u0647\u060c \u0639\u0646\u062f \u0627\u0644\u0639\u0644\u064a \u0627\u0644\u0645\u0628\u064a\u0646\u060c \u0633\u062a\u0646\u0627\u0644 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0628\u0631\u0643\u0629 \u0641\u064a \u0645\u0648\u0627\u0636\u0639 \u0623\u062e\u0631\u0649."},
{id:53,letters:"\u062f \u062c \u062f",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0633\u064a\u062f \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648 \u0627\u0644\u0628\u064a\u0627\u0646: \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633! \u0645\u0646 \u0631\u0628\u0643\u0645 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u060c \u0648\u062f\u0648\u0627\u0621 \u0625\u0635\u0644\u0627\u062d \u0627\u0644\u0646\u0641\u0633\u060c \u0648\u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0648\u0627\u0644\u0631\u062d\u0645\u0629\u060c \u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0628\u0627\u0644\u062a\u0623\u0643\u064a\u062f.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631 \u0628\u062e\u0628\u0631 \u0633\u0631\u0645\u062f\u064a \u0648\u0628\u0641\u0631\u062d \u0648\u0627\u0641\u0631\u060c \u0641\u0628\u0647\u0630\u0627 \u064a\u0623\u0645\u0631\u0643 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0623\u0646 \u062a\u0641\u0631\u062d. \u064a\u0639\u0648\u062f \u0625\u0644\u064a\u0643 \u0645\u0646 \u0628\u0639\u064a\u062f \u062d\u0627\u0645\u0644\u064b\u0627 \u0627\u0644\u0628\u0634\u0631\u0649. \u0623\u062a\u0645 \u0631\u063a\u0628\u062a\u0643 \u0628\u0633\u0631\u0639\u0629\u060c \u0644\u0623\u0646 \u062a\u062d\u0642\u064a\u0642\u0647\u0627 \u0633\u0647\u0644. \u0641\u0644\u062a\u062a\u0643\u0644\u0644 \u0647\u0630\u0647 \u0627\u0644\u0646\u0639\u0645\u0629 \u0628\u0627\u0644\u0646\u0635\u0631\u060c \u0641\u062a\u062a\u062d\u0642\u0642 \u0643\u0644 \u0623\u0645\u0627\u0646\u064a\u0643."},
{id:54,letters:"\u062f \u0627 \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0633\u0645\u0649 \u0647\u0648 \u0627\u0644\u0630\u064a \u0623\u0648\u0636\u062d: \u064a\u0627 \u0631\u0628\u064a! \u0644\u0642\u062f \u0645\u0646\u062d\u062a\u0646\u064a \u0627\u0644\u0633\u0644\u0637\u0627\u0646\u060c \u0648\u0639\u0644\u0651\u0645\u062a\u0646\u064a \u062a\u0641\u0633\u064a\u0631 \u0627\u0644\u0623\u062d\u0644\u0627\u0645. \u062e\u0627\u0644\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636! \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629 \u0623\u0646\u062a \u0648\u0644\u064a\u064a.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0644\u0643 \u0623\u0646 \u062a\u0641\u0631\u062d \u0644\u0623\u0646\u0643 \u0633\u062a\u062d\u0635\u0644 \u0639\u0644\u0649 \u0645\u0627 \u062a\u0631\u064a\u062f \u062f\u0648\u0646 \u062c\u0647\u062f \u0648\u0633\u062a\u0646\u0627\u0644 \u062e\u064a\u0631\u064b\u0627 \u0648\u0641\u064a\u0631\u064b\u0627. \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0644\u0637\u0644\u0628 \u0627\u0644\u0630\u064a \u0633\u0623\u0644\u062a \u0639\u0646\u0647\u060c \u0627\u0633\u0652\u0639\u064e \u0628\u0633\u0631\u0639\u0629 \u0648\u0644\u0627 \u062a\u0645\u0627\u0637\u0644\u060c \u0644\u0623\u0646\u0647 \u0633\u0647\u0644 \u0627\u0644\u062a\u062d\u0642\u064a\u0642. \u0648\u0639\u0646\u062f \u062a\u0644\u0627\u0648\u0629 \u0642\u0648\u0644 \u0627\u0644\u0639\u0644\u064a: \u0623\u0633\u062a\u0648\u062f\u0639 \u0623\u0645\u0631\u064a \u0644\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a\u060c \u0641\u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u064a\u0631\u0627\u0642\u0628 \u0627\u0644\u062c\u0645\u064a\u0639 \u0628\u062c\u0644\u0627\u0621."},
{id:55,letters:"\u062f \u062c \u0628",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0633\u0645\u0649 \u0647\u0648 \u064a\u0638\u0647\u0631: \u0625\u0646 \u0644\u0645 \u064a\u062b\u0646\u0650 \u0639\u0644\u064a\u0647 \u063a\u064a\u0631\u0647\u060c \u0641\u0644\u0627 \u0628\u062f \u0623\u0646 \u064a\u0628\u0642\u0649 \u0628\u0637\u0646 \u0627\u0644\u0633\u0645\u0643\u0629 \u062d\u062a\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0628\u0634\u0631\u0643: \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0648\u0643\u0644 \u0625\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0633\u0645\u0627\u0621. \u0623\u0646\u062a \u0645\u0628\u0627\u0631\u0643\u060c \u0627\u0644\u062d\u0638 \u0627\u0644\u0633\u0639\u064a\u062f \u0641\u064a \u0637\u0631\u064a\u0642\u0647 \u0625\u0644\u064a\u0643\u060c \u0633\u062a\u062d\u0635\u0644 \u0639\u0644\u0649 \u0645\u0627 \u062a\u0637\u0644\u0628. \u0644\u0643\u0646 \u0625\u0646 \u0643\u0646\u062a \u062d\u0643\u064a\u0645\u064b\u0627\u060c \u0641\u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u062a\u062e\u0644\u0649 \u0639\u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0646\u064a\u0629\u060c \u0644\u0623\u0646\u0647\u0627 \u0635\u0639\u0628\u0629\u060c \u0648\u0627\u0628\u062d\u062b \u0639\u0646 \u0623\u0645\u0631 \u0622\u062e\u0631\u060c \u0641\u0633\u062a\u0646\u0627\u0644 \u0627\u0644\u062a\u062d\u0631\u0631."},
{id:56,letters:"\u0628 \u062f \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0638\u0647\u0631: \u0623\u0645\u0627 \u062a\u0631\u0648\u0646\u061f \u0644\u0642\u062f \u0647\u064a\u0623 \u0644\u0643\u0645 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0627\u0644\u0643\u0648\u0646 \u0648\u0643\u0644 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u0627\u062a \u0648\u0623\u063a\u062f\u0642 \u0639\u0644\u064a\u0643\u0645 \u0646\u0639\u0645\u0629 \u0625\u062e\u0644\u0627\u0635 \u0627\u0644\u0642\u0644\u0628 \u0648\u0627\u0644\u0633\u0631\u064a\u0631\u0629 \u0648\u0627\u0644\u0628\u062f\u0646\n\n\u0623\u064a\u062a\u0647\u0627 \u0627\u0644\u0645\u0633\u062a\u0641\u062a\u064a\u0629\u060c \u0641\u064a\u0645\u0627 \u062a\u0631\u062c\u064a\u0646 \u0641\u0648\u0636\u064a \u0627\u0644\u0623\u0645\u0631 \u0625\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0641\u0633\u064a\u062a\u0645. \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0637\u0644\u0628\u064a \u0639\u0648\u0646 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0641\u0625\u0646\u0647 \u0633\u064a\u0648\u0641\u064a\u0643 \u062d\u0642\u0643. \u0633\u0628\u064a\u0644 \u0627\u0644\u0633\u0645\u0627\u0621 \u0639\u0644\u064a\u0645 \u0644\u0644\u063a\u0627\u064a\u0629."},
{id:57,letters:"\u062c \u0628 \u0627",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0638\u0645 \u0647\u0648 \u0627\u0644\u0645\u0628\u064a\u0646: \u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633! \u0627\u062a\u0642\u0648\u0627 \u0631\u0628\u0643\u0645\u060c \u0641\u0625\u0646 \u0642\u064a\u0627\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0644\u0634\u064a\u0621 \u0639\u0638\u064a\u0645.\n\n\u064a\u0627 \u0633\u0627\u0626\u0650\u0644\u064c\u060c \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0633\u062a\u0639\u062f \u0644\u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631\u060c \u0648\u062a\u0623\u062c\u0644\u0647 \u0625\u0644\u0649 \u0648\u0642\u062a \u0644\u0627\u062d\u0642\u060c \u0641\u0644\u0627 \u062a\u062a\u0639\u062c\u0644. \u0625\u0646 \u0631\u063a\u0628\u062a\u0643 \u0633\u062a\u062d\u0642\u0642 \u0641\u064a\u0645\u0627 \u0628\u0639\u062f\u060c \u0641\u0627\u062a\u0642\u0650 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0621 \u0648\u0627\u0637\u0644\u0628 \u0627\u0644\u0645\u063a\u0641\u0631\u0629."},
{id:58,letters:"\u0628 \u062f \u0628",fortune:"\u0634\u0631\u064a\u0631",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0634\u064a\u0631: \u0646\u0647\u0627\u064a\u062a\u0647 \u0645\u0646 \u0627\u0644\u0641\u0639\u0644 \u0647\u064a \u0627\u0644\u062e\u0633\u0631\u0627\u0646.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0641\u064a\u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0644\u0627 \u062a\u0643\u0646 \u0645\u0633\u062a\u0639\u062c\u0644\u0627\u064b\u060c \u062a\u062c\u0646\u0628 \u0627\u0644\u0645\u0643\u0631\u060c \u0643\u064f\u0646 \u062d\u0630\u0631\u0627\u064b. \u0625\u0646 \u0627\u062a\u0628\u0639\u062a \u0630\u0644\u0643\u060c \u0641\u0644\u0646 \u062a\u062d\u0635\u0644 \u0625\u0644\u0627 \u0639\u0644\u0649 \u0627\u0644\u062e\u0633\u0631\u0627\u0646. \u0642\u062f \u062a\u0624\u062c\u0644 \u0631\u063a\u0628\u062a\u0643 \u0625\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0642\u0628\u0644\u060c \u0644\u0623\u0646 \u0627\u0644\u0639\u0644\u064a \u064a\u0642\u0648\u0644: \u0628\u0639\u062f \u0627\u0644\u0634\u062f\u0629\u060c \u064a\u0647\u0628 \u0627\u0644\u0637\u0631\u064a\u0642 \u0633\u0647\u0648\u0644\u0629 \u0633\u0631\u064a\u0639\u0629. \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0625\u0644\u0647\u064a \u0639\u0644\u064a\u0645."},
{id:59,letters:"\u0628 \u0628 \u062c",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0623\u0639\u0644\u0649 \u0627\u0644\u0633\u064a\u062f \u0623\u0634\u0627\u0631: \u0623\u0646\u0627 \u0623\u0646\u0632\u0644\u062a\u064f \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0644\u0634\u0650\u0641\u0627\u0621 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u0631\u062d\u0645\u062a\u0647\u0650\u0645. \u0648\u0642\u0627\u0644 \u0623\u064a\u0636\u064b\u0627: \u062f\u0648\u0627\u0621 \u0642\u0644\u0648\u0628 \u0627\u0644\u0645\u062e\u0644\u0635\u064a\u0646. \u0648\u0642\u0627\u0644 \u0623\u064a\u0636\u064b\u0627: \u0648\u064a\u0634\u0641\u064a \u0635\u062f\u0648\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.\n\n\u064a\u0627 \u0633\u0627\u0626\u0650\u0644\u060c \u0644\u0623\u0645\u0646\u064a\u062a\u0643 \u0623\u064f\u0628\u0634\u0631 \u0628\u0633\u0639\u0627\u062f\u0629 \u0648\u0628\u0647\u062c\u0629 \u0637\u064a\u0628\u0629\u060c \u0648\u0644\u0643\u0646 \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u062a\u0645\u0633\u0643 \u0628\u0642\u0644\u0628\u064d \u0631\u0627\u0633\u062e\u060c \u0648\u062a\u0646\u062a\u0638\u0631 \u0642\u062f\u0631\u064e \u0627\u0644\u0633\u0645\u0627\u0621 \u062d\u062a\u0649 \u064a\u0641\u062a\u062d \u0644\u0643 \u0628\u0627\u0628\u0647. \u0643\u0644 \u0645\u0627 \u062a\u0637\u0644\u0628\u0647 \u0633\u064a\u062a\u062d\u0642\u0642 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u0646\u0627\u0633\u0628. \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0630\u0643\u0631 \u0643\u0644\u0645\u0627\u062a\u064d \u0637\u064a\u0628\u0629 \u062f\u0627\u0626\u0645\u064b\u0627\u060c \u0644\u0623\u0646 \u0644\u0644\u0643\u0644\u0627\u0645 \u0642\u062f\u0631\u0629\u064b \u0639\u0644\u0649 \u0627\u0644\u062a\u062f\u0627\u0648\u064a \u0648\u0641\u062a\u062d \u0627\u0644\u0645\u0623\u0632\u0642. \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0625\u0644\u0647\u064a \u0639\u0644\u064a\u0645\u060c \u0648\u0643\u0644 \u0627\u0644\u0623\u0645\u0648\u0631 \u0644\u0647\u0627 \u0642\u062f\u0631\u0647\u0627 \u0627\u0644\u0645\u0642\u0631\u0631."},
{id:60,letters:"\u0628 \u062f \u0627",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u0647\u0648: \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646! \u0644\u0627 \u062a\u062c\u0639\u0644\u0648\u0627 \u0623\u0645\u0648\u0627\u0644\u0643\u0645 \u062a\u063a\u0641\u0644\u0648\u0627 \u0639\u0646 \u0630\u0643\u0631 \u0631\u0628\u0643\u0645.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u062a\u062e\u0644\u064e\u0651 \u0639\u0645\u0627 \u0641\u064a \u0642\u0644\u0628\u0643 \u0648\u0633\u0637 \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0627\u0621\u060c \u0641\u0648\u0633\u0627\u0637\u062a\u0647 \u0644\u0627 \u062a\u0646\u0641\u0639\u0643. \u0639\u0627\u0645\u0650\u0644\u0652\u0647 \u0628\u0627\u0644\u062d\u0633\u0646\u0649\u060c \u0641\u0633\u062a\u0646\u0627\u0644 \u0645\u0646\u0641\u0639\u0629. \u0627\u0639\u0628\u062f \u0631\u0628\u0643 \u062d\u062a\u0649 \u062a\u0623\u062a\u064a\u0643 \u0627\u0644\u0628\u064a\u0646\u0629 \u0627\u0644\u062e\u0627\u0644\u064a\u0629 \u0645\u0646 \u0627\u0644\u0634\u0643."},
{id:61,letters:"\u062c \u0628 \u0628",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0642\u0648\u0644: \u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0644\u064a\u0633\u062a \u0625\u0644\u0627 \u0644\u0639\u0628\u064b\u0627 \u0648\u0644\u0647\u0648\u064b\u0627 \u0648\u0632\u064a\u0646\u0629\u064b \u0648\u062a\u0641\u0627\u062e\u0631\u064b\u0627 \u0648\u062a\u0646\u0627\u0641\u0633\u064b\u0627 \u0641\u064a \u062c\u0645\u0639 \u0627\u0644\u0645\u0627\u0644.\n\n\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0623\u0631\u0627\u0643 \u062a\u0637\u0644\u0628 \u0623\u0645\u0631\u064b\u0627 \u0648\u0642\u062f \u0623\u0631\u0647\u0642\u062a \u0646\u0641\u0633\u0643\u060c \u0648\u0642\u062f \u0627\u0636\u0637\u0631\u0628 \u0631\u0623\u064a\u0643 \u0628\u064a\u0646 \u0627\u0644\u0625\u0642\u062f\u0627\u0645 \u0648\u0627\u0644\u062a\u0631\u0627\u062c\u0639. \u0639\u0644\u064a\u0643 \u0628\u0627\u0644\u0635\u0628\u0631\u060c \u0648\u0633\u062a\u0646\u0627\u0644 \u0623\u0644\u0648\u0627\u0646\u064b\u0627 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631 \u0648\u0627\u0644\u0628\u0631\u0643\u0629."},
{id:62,letters:"\u062f \u0627 \u0628",fortune:"\u0648\u0633\u0637",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0639\u0644\u0649 \u064a\u0642\u0648\u0644: \u0625\u0646 \u0643\u0646\u062a\u0645 \u0634\u0627\u0643\u0631\u064a\u0646 \u0641\u0633\u0623\u0632\u064a\u062f\u0643\u0645\u061b \u0648\u0625\u0646 \u0643\u0646\u062a\u0645 \u062c\u0627\u062d\u062f\u064a\u0646 \u0641\u0633\u0623\u0643\u0648\u0646 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628. \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0645\u0639 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646.\n\n\u0627\u0644\u0645\u0633\u062a\u0646\u0643\u0631\u060c \u0623\u0628\u0634\u0631: \u0627\u0635\u0628\u0631 \u0641\u0633\u064a\u0643\u0634\u0641 \u0644\u0643 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0628\u0627\u0628 \u0627\u0644\u0633\u0639\u0627\u062f\u0629 \u0648\u0627\u0644\u0641\u0631\u062d. \u0639\u0644\u064a\u0643 \u0623\u0646 \u062a\u0648\u0643\u0644 \u0623\u0645\u0648\u0631\u0643 \u0625\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a\u060c \u0641\u0625\u0646\u0647 \u064a\u062d\u0628 \u0627\u0644\u0645\u062a\u0648\u0643\u0644\u064a\u0646. \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u064a \u0647\u0648 \u0645\u064e\u0646 \u064a\u062d\u0642\u0642 \u0627\u0644\u0623\u0645\u0648\u0631 \u0644\u0644\u0645\u0633\u062a\u062d\u0642\u064a\u0646."},
{id:63,letters:"\u0628 \u062c \u0628",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0631\u0628 \u0627\u0644\u0623\u0633\u0645\u0649 \u064a\u0634\u064a\u0631: \u0646\u0635\u0631 \u0627\u0644\u0622\u062a\u064a \u0645\u0646 \u0627\u0644\u0623\u0639\u0644\u0649 \u0642\u062f \u062d\u0644\u0651.\n\n\u064a\u0627 \u0633\u0627\u0626\u0650\u0644\u060c \u0644\u0623\u062c\u0644 \u0637\u0644\u0628\u0643 \u0627\u0644\u062e\u0627\u0635 \u0623\u062e\u0628\u0627\u0631 \u0633\u0627\u0631\u0651\u0629: \u0628\u0645\u0634\u064a\u0626\u0629 \u0627\u0644\u0623\u0639\u0638\u0645\u060c \u0633\u062a\u062d\u0635\u0644 \u0639\u0644\u0649 \u0623\u0641\u0631\u0627\u062d \u0648\u0631\u062e\u0627\u0621 \u0645\u0646 \u0643\u0644\u0651 \u0646\u0648\u0639. \u0639\u0644\u064a\u0643 \u0628\u0627\u0644\u0645\u062f\u064a\u062d\u060c \u0641\u0647\u0648 \u0633\u064a\u0632\u064a\u062f\u0643 \u0645\u0646 \u0639\u0637\u0627\u064a\u0627\u0647."},
{id:64,letters:"\u0628 \u0628 \u0628",fortune:"\u0633\u0639\u064a\u062f",text:"\u0627\u0644\u0639\u0644\u064a \u0627\u0644\u0631\u0627\u0632\u0642 \u064a\u0642\u0648\u0644: \u0627\u0644\u064a\u0648\u0645 \u0642\u062f \u0623\u062a\u0645\u0645\u062a \u0644\u0643\u0645 \u0637\u0631\u064a\u0642\u0643\u0645. \u0648\u064a\u0642\u0648\u0644 \u0623\u064a\u0636\u0627\u064b: \u0623\u0646\u0632\u0644\u062a \u0627\u0644\u0642\u0631\u0622\u0646 \u0644\u0634\u0641\u0627\u0621 \u0648\u0625\u064a\u0645\u0627\u0646 \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u0631\u062d\u0645\u0629\u060c \u0648\u0644\u0623\u062c\u0644 \u0623\u0646 \u064a\u0632\u062f\u0627\u062f \u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0641\u064a \u0635\u062f\u0648\u0631\u0647\u0645.\n\n\u064a\u0627 \u0633\u0627\u0626\u0644\u0627\u064b\u060c \u0623\u0628\u0634\u0650\u0631 \u0628\u062e\u0628\u0631 \u0633\u0627\u0631: \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0625\u0644\u0647\u064a \u0642\u062f \u0623\u0639\u062f \u0644\u0643 \u062c\u0645\u064a\u0639 \u0623\u0641\u0631\u0627\u062d \u0633\u0639\u064a\u062f\u0629\u060c \u0648\u0645\u0627 \u062a\u0631\u062c\u0648\u0647 \u0633\u064a\u064f\u062d\u0642\u0642 \u0628\u0623\u062d\u0633\u0646 \u0635\u0648\u0631\u0629. \u0627\u0630\u0647\u0628 \u0648\u0627\u0637\u0644\u0628\u0647\u060c \u0641\u0627\u0644\u062f\u0631\u0628 \u0627\u0644\u0625\u0644\u0647\u064a \u0645\u0639\u0643."}
